lMinutes < 60) {\n    return `${totalMinutes}m`;\n  }\n  const hours = Math.floor(totalMinutes / 60);\n  const minutes = totalMinutes % 60;\n  if (minutes === 0) return `${hours}h`;\n  return `${hours}h ${minutes}m`;\n}\n\n// ── Display a value that's already in HH:MM format ──\nfunction displayHHMM(value: number | undefined | null): string {\n  if (!value && value !== 0) return '0:00';\n  return formatHours(value);\n}\n\n// ── Get firm code from employee ID prefix ──\nfunction getFirmFromEmployeeId(employeeId: string): string {\n  const id = employeeId.toUpperCase();\n  if (id.startsWith('LAPL')) return 'LAPL';\n  if (id.startsWith('LRSL')) return 'LRSL';\n  if (id.startsWith('SI-') || id.startsWith('SI0')) return 'SI';\n  if (id.startsWith('SDF')) return 'SDF';\n  return ''; // fallback to existing department/firm\n}\n\nconst FIRMS = ['LAPL', 'LRSL', 'SI', 'SDF'];\nconst LOCATIONS = ['Ajmer', 'Gurgaon', 'Palra Warehouse', 'Jaipur', 'Roofing Factory'];\nconst MONTHS = [\n  'January', 'February', 'March', 'April', 'May', 'June',\n  'July', 'August', 'September', 'October', 'November', 'December',\n];\n\n// ── Attendance Record Type ──\ninterface AttendanceRecord {\n  id: string;\n  employeeId: string;\n  date: string;\n  checkIn: string | null;\n  checkOut: string | null;\n  totalHours: number;\n  status: string;\n  lateEntry: boolean;\n  earlyOut: boolean;\n  halfDay: boolean;\n  overtimeHours: number;\n  isSunday: boolean;\n  isPH: boolean;\n  sundayHours: number;\n  employee?: {\n    fullName: string;\n    employeeId: string;\n    department: string;\n    designation: string;\n    location: string;\n  };\n}\n\n// ── Monthly Summary Type ──\ninterface MonthlySummary {\n  employee: {\n    fullName: string;\n    employeeId: string;\n    firm: string;\n    firmFullName?: string;\n    location: string;\n    department: string;\n    designation: string;\n    shiftHours: number;\n    employmentType?: string;\n    hourlyRate?: number;\n    monthlySalary?: number;\n    overtimeRate?: number;\n  };\n  month: number;\n  year: number;\n  monthName: string;\n  daysInMonth: number;\n  totalWorkingDays: number;\n  presentDays: number;\n  absentDays: number;\n  leaveDays: number;\n  paidLeaves?: number;\n  annualLeaves?: number;\n  unpaidLeaves?: number;\n  halfDays: number;\n  holidayDays: number;\n  weeklyOffs: number;\n  sundays: number;\n  totalAttendance: number;\n  totalWorkHours: number;\n  totalOvertimeHours: number;\n  totalSundayHours: number;\n  totalHrsInclSunday?: number;\n  lateEntries: number;\n  earlyOuts?: number;\n  records: AttendanceRecord[];\n  // Salary calculation fields (from monthly-summary API)\n  perDayRate?: number;\n  calculatedHourlyRate?: number;\n  calculatedBaseSalary?: number;\n  calculatedOtAmount?: number;\n  calculatedGrossSalary?: number;\n}\n\n// ── Animated Counter ──\nfunction AnimatedCounter({ value, prefix = '', suffix = '', decimals = 0 }: {\n  value: number; prefix?: string; suffix?: string; decimals?: number;\n}) {\n  const [display, setDisplay] = useState(0);\n  useEffect(() => {\n    const duration = 1000;\n    const startTime = Date.now();\n    const step = () => {\n      const elapsed = Date.now() - startTime;\n      const progress = Math.min(elapsed / duration, 1);\n      const eased = 1 - Math.pow(1 - progress, 3);\n      setDisplay(value * eased);\n      if (progress < 1) requestAnimationFrame(step);\n    };\n    requestAnimationFrame(step);\n  }, [value]);\n\n  if (decimals > 0) {\n    return <span>{prefix}{display.toFixed(decimals)}{suffix}</span>;\n  }\n  return <span>{prefix}{Math.round(display).toLocaleString()}{suffix}</span>;\n}\n\n// ── Status badge with colors ──\nfunction StatusBadge({ status }: { status: string }) {\n  const config: Record<string, { bg: string; text: string; label: string }> = {\n    present: { bg: 'bg-emerald-500/15 border-emerald-500/20', text: 'text-emerald-600 dark:text-emerald-400', label: 'Present' },\n    late: { bg: 'bg-yellow-500/15 border-yellow-500/20', text: 'text-yellow-600 dark:text-yellow-400', label: 'Late' },\n    'early-out': { bg: 'bg-rose-500/15 border-rose-500/20', text: 'text-rose-600 dark:text-rose-400', label: 'Early Out' },\n    absent: { bg: 'bg-red-500/15 border-red-500/20', text: 'text-red-600 dark:text-red-400', label: 'Absent' },\n    'half-day': { bg: 'bg-orange-500/15 border-orange-500/20', text: 'text-orange-600 dark:text-orange-400', label: 'Half-Day' },\n    holiday: { bg: 'bg-purple-500/15 border-purple-500/20', text: 'text-purple-600 dark:text-purple-400', label: 'Holiday' },\n    'weekly-off': { bg: 'bg-blue-500/15 border-blue-500/20', text: 'text-blue-600 dark:text-blue-400', label: 'Weekly Off' },\n  };\n  const s = config[status] || { bg: 'bg-muted border-border', text: 'text-muted-foreground', label: status };\n  return (\n    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border whitespace-nowrap ${s.bg} ${s.text}`}>\n      {s.label}\n    </span>\n  );\n}\n\n// ── Firm badge ──\nfunction FirmBadge({ firm }: { firm: string }) {\n  return <span className={`${FIRM_BADGE_CLASS[firm] || 'firm-badge-lapl'} whitespace-nowrap shrink-0`}>{firm}</span>;\n}\n\nexport function AttendanceTracker() {\n  const [records, setRecords] = useState<AttendanceRecord[]>([]);\n  const [summary, setSummary] = useState({\n    present: 0, absent: 0, late: 0, earlyOut: 0, halfDay: 0, ot: 0,\n  });\n  const [employees, setEmployees] = useState<{ employeeId: string; fullName: string; department: string; location: string; firm: string; shiftStart: string; shiftEnd: string; shiftHours: number }[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [open, setOpen] = useState(false);\n  const [form, setForm] = useState({ employeeId: '', date: '', checkIn: '', checkOut: '' });\n  const [employeeSearch, setEmployeeSearch] = useState('');\n\n  // ── Filters ──\n  const now = new Date();\n  const [filterMonth, setFilterMonth] = useState(String(now.getMonth() + 1));\n  const [filterYear, setFilterYear] = useState(String(now.getFullYear()));\n  const [filterFirm, setFilterFirm] = useState('all');\n  const [filterLocation, setFilterLocation] = useState('all');\n  const [searchEmployee, setSearchEmployee] = useState('');\n\n  // ── Daily tab: date filter + status filter ──\n  const [filterDate, setFilterDate] = useState(() => {\n    const d = new Date();\n    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;\n  });\n  const [statusFilter, setStatusFilter] = useState<string>('all'); // 'all' | 'present' | 'absent' | 'late' | 'early-out' | 'ot'\n\n  // ── Edit state ──\n  const [editOpen, setEditOpen] = useState(false);\n  const [editRecord, setEditRecord] = useState<AttendanceRecord | null>(null);\n  const [editForm, setEditForm] = useState({ checkIn: '', checkOut: '' });\n\n  // ── Monthly Summary state ──\n  const [monthlyEmpId, setMonthlyEmpId] = useState('');\n  const [monthlySummary, setMonthlySummary] = useState<MonthlySummary | null>(null);\n  const [monthlyLoading, setMonthlyLoading] = useState(false);\n\n  // ── Import state ──\n  const [importFile, setImportFile] = useState<File | null>(null);\n  const [importPreview, setImportPreview] = useState<any[]>([]);\n  const [importing, setImporting] = useState(false);\n  const [importResult, setImportResult] = useState<any>(null);\n  const [importDate, setImportDate] = useState(() => {\n    const d = new Date();\n    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;\n  });\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  // ── Master Excel Sheet state ──\n  const [masterFirm, setMasterFirm] = useState('all');\n  const [masterExporting, setMasterExporting] = useState(false);\n\n  // ── Load data ──\n  const loadData = useCallback(async () => {\n    setLoading(true);\n    try {\n      const params = new URLSearchParams();\n      // If a specific date is selected, use date filter; otherwise use month/year\n      if (filterDate) {\n        params.set('date', filterDate);\n      } else {\n        params.set('month', filterMonth);\n        params.set('year', filterYear);\n      }\n      if (filterFirm !== 'all') params.set('department', filterFirm);\n      if (filterLocation !== 'all') params.set('location', filterLocation);\n\n      const [attRes, empRes] = await Promise.all([\n        fetch(`/api/attendance?${params}`),\n        fetch('/api/employees?status=Yes'),\n      ]);\n      const attData = await attRes.json();\n      const empData = await empRes.json();\n\n      const recs: AttendanceRecord[] = attData.records || attData;\n      setRecords(recs);\n      setEmployees(empData.map((e: any) => ({\n        employeeId: e.employeeId,\n        fullName: e.fullName,\n        department: e.department,\n        location: e.location,\n        firm: e.firm,\n        shiftStart: e.shiftStart || '10:00',\n        shiftEnd: e.shiftEnd || '19:00',\n        shiftHours: e.shiftHours || 9,\n      })));\n\n      const summ = attData.summary || {};\n      setSummary({\n        present: summ.present || recs.filter((a: any) => ['present', 'late', 'early-out'].includes(a.status)).length,\n        absent: summ.absent || recs.filter((a: any) => a.status === 'absent').length,\n        late: summ.late || recs.filter((a: any) => a.lateEntry).length,\n        earlyOut: summ.earlyOuts || recs.filter((a: any) => a.earlyOut).length,\n        halfDay: summ.halfDay || recs.filter((a: any) => a.halfDay).length,\n        ot: Math.round((summ.totalOvertimeHours || recs.reduce((s: number, a: any) => s + a.overtimeHours, 0)) * 100) / 100,\n      });\n    } catch {\n      toast.error('Failed to load attendance data');\n    }\n    setLoading(false);\n  }, [filterDate, filterMonth, filterYear, filterFirm, filterLocation]);\n\n  useEffect(() => { loadData(); }, [loadData]);\n\n  // ── Filtered records by employee search + status filter ──\n  const filteredRecords = useMemo(() => {\n    let filtered = records;\n    // Status filter\n    if (statusFilter !== 'all') {\n      if (statusFilter === 'present') {\n        filtered = filtered.filter((r) => ['present', 'late', 'early-out'].includes(r.status));\n      } else if (statusFilter === 'absent') {\n        filtered = filtered.filter((r) => r.status === 'absent');\n      } else if (statusFilter === 'late') {\n        filtered = filtered.filter((r) => r.lateEntry);\n      } else if (statusFilter === 'early-out') {\n        filtered = filtered.filter((r) => r.earlyOut);\n      } else if (statusFilter === 'ot') {\n        filtered = filtered.filter((r) => r.overtimeHours > 0);\n      }\n    }\n    // Employee search\n    if (searchEmployee) {\n      const q = searchEmployee.toLowerCase();\n      filtered = filtered.filter((r) =>\n        r.employee?.fullName?.toLowerCase().includes(q) ||\n        r.employeeId.toLowerCase().includes(q)\n      );\n    }\n    return filtered;\n  }, [records, searchEmployee, statusFilter]);\n\n  // ── Mark attendance submit ──\n  const handleSubmit = async () => {\n    if (!form.employeeId || !form.date) {\n      toast.error('Please select employee and date');\n      return;\n    }\n    try {\n      const res = await fetch('/api/attendance', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(form),\n      });\n      if (!res.ok) {\n        const errData = await res.json().catch(() => ({}));\n        throw new Error(errData.error || `Failed to record attendance`);\n      }\n      toast.success('Attendance recorded successfully');\n      setOpen(false);\n      setForm({ employeeId: '', date: '', checkIn: '', checkOut: '' });\n      setEmployeeSearch('');\n      loadData();\n    } catch (e: any) {\n      toast.error(e.message || 'Failed to record attendance');\n    }\n  };\n\n  // ── Edit attendance ──\n  const handleEdit = (rec: AttendanceRecord) => {\n    setEditRecord(rec);\n    setEditForm({ checkIn: rec.checkIn || '', checkOut: rec.checkOut || '' });\n    setEditOpen(true);\n  };\n\n  const handleEditSubmit = async () => {\n    if (!editRecord) return;\n    try {\n      const res = await fetch(`/api/attendance/${editRecord.id}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(editForm),\n      });\n      if (res.ok) {\n        toast.success('Attendance updated successfully');\n        setEditOpen(false);\n        setEditRecord(null);\n        loadData();\n      } else {\n        const data = await res.json();\n        toast.error(data.error || 'Failed to update');\n      }\n    } catch {\n      toast.error('Failed to update attendance');\n    }\n  };\n\n  // ── Delete attendance ──\n  const handleDelete = async (id: string) => {\n    if (!confirm('Delete this attendance record?')) return;\n    try {\n      const res = await fetch(`/api/attendance/${id}`, { method: 'DELETE' });\n      if (res.ok) {\n        toast.success('Attendance record deleted');\n        loadData();\n      }\n    } catch {\n      toast.error('Failed to delete');\n    }\n  };\n\n  // ── Load Monthly Summary ──\n  const loadMonthlySummary = useCallback(async () => {\n    if (!monthlyEmpId) return;\n    setMonthlyLoading(true);\n    try {\n      const res = await fetch(`/api/attendance/monthly-summary?employeeId=${monthlyEmpId}&month=${filterMonth}&year=${filterYear}`);\n      if (res.ok) {\n        const data = await res.json();\n        setMonthlySummary(data);\n      } else {\n        setMonthlySummary(null);\n      }\n    } catch {\n      toast.error('Failed to load monthly summary');\n      setMonthlySummary(null);\n    }\n    setMonthlyLoading(false);\n  }, [monthlyEmpId, filterMonth, filterYear]);\n\n  useEffect(() => { loadMonthlySummary(); }, [loadMonthlySummary]);\n\n  // ── Export Daily Attendance — via server-side API ──\n  const handleExportDailyExcel = async () => {\n    if (filteredRecords.length === 0) {\n      toast.error('No records to export');\n      return;\n    }\n    try {\n      const params = new URLSearchParams();\n      if (filterDate) params.set('date', filterDate);\n      else { params.set('month', filterMonth); params.set('year', filterYear); }\n      if (filterFirm !== 'all') params.set('department', filterFirm);\n      if (filterLocation !== 'all') params.set('location', filterLocation);\n\n      const res = await fetch(`/api/attendance/export-daily?${params}`);\n      if (!res.ok) { toast.error('Export failed'); return; }\n      const blob = await res.blob();\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = `Daily_Attendance_${MONTHS[parseInt(filterMonth) - 1]}_${filterYear}.xlsx`;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      window.URL.revokeObjectURL(url);\n      toast.success('Daily Attendance Excel downloaded successfully!');\n    } catch (err) {\n      console.error('Daily export error:', err);\n      toast.error('Export failed. Please try again.');\n    }\n  };\n\n  // ── Export Monthly Attendance Register — via server-side API ──\n  const handleExportExcel = async () => {\n    if (!monthlySummary) return;\n    try {\n      const params = new URLSearchParams({\n        employeeId: monthlyEmpId,\n        month: filterMonth,\n        year: filterYear,\n      });\n      const res = await fetch(`/api/attendance/export-monthly?${params}`);\n      if (!res.ok) { toast.error('Export failed'); return; }\n      const blob = await res.blob();\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = `Monthly_Attendance_${monthlySummary.employee.fullName}_${monthlySummary.monthName}_${monthlySummary.year}.xlsx`;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      window.URL.revokeObjectURL(url);\n      toast.success('Monthly Attendance Excel downloaded successfully!');\n    } catch (err) {\n      console.error('Monthly export error:', err);\n      toast.error('Export failed. Please try again.');\n    }\n  };\n\n  // ── Convert Excel serial date to YYYY-MM-DD ──\n  const excelSerialToDate = (serial: number): string => {\n    // Excel serial date: days since Jan 1, 1900 (with the 1900 leap year bug)\n    const epoch = new Date(1899, 11, 30); // Dec 30, 1899 is day 0\n    const date = new Date(epoch.getTime() + serial * 86400000);\n    const y = date.getFullYear();\n    const m = String(date.getMonth() + 1).padStart(2, '0');\n    const d = String(date.getDate()).padStart(2, '0');\n    return `${y}-${m}-${d}`;\n  };\n\n  // ── Convert Excel decimal time to HH:MM ──\n  const excelDecimalToTime = (value: any): string => {\n    if (typeof value === 'string') {\n      // Already a string - check if it looks like HH:MM\n      const trimmed = value.trim();\n      if (/^\\d{1,2}:\\d{2}(:\\d{2})?$/.test(trimmed)) return trimmed.substring(0, 5);\n      // Try parsing as number\n      const num = parseFloat(trimmed);\n      if (!isNaN(num) && num >= 0 && num < 1) {\n        const totalMinutes = Math.round(num * 1440);\n        const hours = Math.floor(totalMinutes / 60);\n        const minutes = totalMinutes % 60;\n        return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;\n      }\n      return trimmed;\n    }\n    if (typeof value === 'number') {\n      if (value >= 1) {\n        // Could be a full datetime serial - extract time portion\n        const timePart = value - Math.floor(value);\n        const totalMinutes = Math.round(timePart * 1440);\n        const hours = Math.floor(totalMinutes / 60);\n        const minutes = totalMinutes % 60;\n        return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;\n      }\n      // Decimal time fraction (0 to <1)\n      const totalMinutes = Math.round(value * 1440);\n      const hours = Math.floor(totalMinutes / 60);\n      const minutes = totalMinutes % 60;\n      return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;\n    }\n    return String(value || '');\n  };\n\n  // ── Parse any date value to YYYY-MM-DD ──\n  const parseDateValue = (value: any): string => {\n    if (!value && value !== 0) return '';\n    if (typeof value === 'number') {\n      // Excel serial date number\n      return excelSerialToDate(value);\n    }\n    const str = String(value).trim();\n    if (!str) return '';\n    // Already in YYYY-MM-DD format\n    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(str)) return str;\n    // Try DD/MM/YYYY or DD-MM-YYYY\n    const dmyMatch = str.match(/^(\\d{1,2})[/\\-.](\\d{1,2})[/\\-.](\\d{4})$/);\n    if (dmyMatch) return `${dmyMatch[3]}-${dmyMatch[2].padStart(2, '0')}-${dmyMatch[1].padStart(2, '0')}`;\n    // Try MM/DD/YYYY\n    const mdyMatch = str.match(/^(\\d{1,2})[/\\-.](\\d{1,2})[/\\-.](\\d{4})$/);\n    if (mdyMatch) return `${mdyMatch[3]}-${mdyMatch[1].padStart(2, '0')}-${mdyMatch[2].padStart(2, '0')}`;\n    // Fallback: try native Date parse\n    try {\n      const d = new Date(str);\n      if (!isNaN(d.getTime())) {\n        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;\n      }\n    } catch {}\n    return str;\n  };\n\n  // ── Smart Employee ID matching ──\n  const smartMatchEmployeeId = (rawId: string, empName: string): string => {\n    if (!rawId && !empName) return '';\n    let empId = String(rawId).trim();\n\n    // If we have an ID, try exact match first\n    if (empId) {\n      // Try exact match\n      const exact = employees.find(e => e.employeeId === empId);\n      if (exact) return exact.employeeId;\n\n      // Try with EMP- prefix (e.g., \"41\" → \"EMP-041\" or \"EMP-41\")\n      const withPrefix = `EMP-${empId.padStart(3, '0')}`;\n      const matchPad = employees.find(e => e.employeeId === withPrefix);\n      if (matchPad) return matchPad.employeeId;\n\n      const withoutPad = `EMP-${empId}`;\n      const matchNoPad = employees.find(e => e.employeeId === withoutPad);\n      if (matchNoPad) return matchNoPad.employeeId;\n    }\n\n    // Match by employee name\n    if (empName) {\n      const nameLower = empName.toLowerCase().trim();\n      // Exact name match\n      const exactName = employees.find(e => e.fullName.toLowerCase() === nameLower);\n      if (exactName) return exactName.employeeId;\n      // Partial name match\n      const partialName = employees.find(e =>\n        e.fullName.toLowerCase().includes(nameLower) || nameLower.includes(e.fullName.toLowerCase())\n      );\n      if (partialName) return partialName.employeeId;\n    }\n\n    return empId; // Return whatever we have\n  };\n\n  // ── File upload handler ──\n  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n    setImportFile(file);\n    setImportResult(null);\n\n    try {\n      const XLSX = await import('xlsx');\n      const arrayBuffer = await file.arrayBuffer();\n      const workbook = XLSX.read(arrayBuffer, { cellDates: false, raw: true });\n      const sheetName = workbook.SheetNames[0];\n      const sheet = workbook.Sheets[sheetName];\n      // Use raw:true to get actual values, then we convert ourselves\n      const data = XLSX.utils.sheet_to_json(sheet, { raw: true });\n\n      if (data.length === 0) {\n        toast.error('No data found in the file');\n        return;\n      }\n\n      // Try to map columns - look for common column names (supports both old and new template formats)\n      const mapped = data.map((row: any) => {\n        // Get raw values from various possible column names\n        const rawEmpId = row['E. Code'] || row['ECode'] || row['Emp Code'] || row['Employee Code'] || row['Employee_Code'] ||\n          row['Employee ID'] || row['employeeId'] || row['Employee_Code'] || row['EMP ID'] || row['Emp ID'] || row['Emp_Code'] || '';\n        const rawEmpName = row['Name'] || row['Employee Name'] || row['fullName'] || row['Employee_Name'] || row['Emp Name'] || '';\n        const rawDate = row['Date'] || row['date'] || row['Attendance Date'] || row['Att Date'] || '';\n        const rawCheckIn = row[' InTime'] || row['InTime'] || row['In Time'] || row['Check In'] || row['checkIn'] || row['In_Time'] || row['IN'] || row['Time In'] || '';\n        const rawCheckOut = row[' OutTime'] || row['OutTime'] || row['Out Time'] || row['Check Out'] || row['checkOut'] || row['Out_Time'] || row['OUT'] || row['Time Out'] || '';\n        const rawShift = row['Shift'] || row['shift'] || '';\n        const rawStatus = row['Status'] || row['status'] || '';\n        const rawRemarks = row['Remarks'] || row['remarks'] || row['Remark'] || row['remark'] || '';\n\n        // Convert values\n        const empId = String(rawEmpId).trim();\n        const empName = String(rawEmpName).trim();\n        const date = parseDateValue(rawDate);\n        const checkIn = excelDecimalToTime(rawCheckIn);\n        const checkOut = excelDecimalToTime(rawCheckOut);\n        const shift = String(rawShift).trim();\n        const status = String(rawStatus).trim();\n        const remarks = String(rawRemarks).trim();\n\n        return { employeeId: empId, employeeName: empName, date, checkIn, checkOut, shift, status, remarks };\n      }).filter(r => r.employeeId || r.employeeName);\n\n      setImportPreview(mapped);\n    } catch (err: any) {\n      toast.error('Failed to parse file: ' + err.message);\n    }\n  };\n\n  // ── Download Excel Template ──\n  // Server-side generated blank template with selected date\n  const handleDownloadTemplate = async () => {\n    try {\n      const params = new URLSearchParams();\n      if (importDate) params.set('date', importDate);\n      const res = await fetch(`/api/attendance/template?${params}`);\n      if (!res.ok) { toast.error('Template download failed'); return; }\n      const blob = await res.blob();\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = `Daily_Attendance_Template.xlsx`;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      window.URL.revokeObjectURL(url);\n      toast.success('Template downloaded! Fill it and upload.');\n    } catch {\n      toast.error('Failed to download template.');\n    }\n  };\n\n  // ── Process import ──\n  const handleProcessImport = async () => {\n    if (importPreview.length === 0) return;\n    setImporting(true);\n\n    try {\n      // Use smart matching for employee IDs\n      const recordsToImport = importPreview.map((row) => {\n        const empId = smartMatchEmployeeId(row.employeeId, row.employeeName);\n        // Use row date if available, otherwise fall back to the selected importDate\n        const date = row.date || importDate;\n        return {\n          employeeId: empId,\n          date,\n          checkIn: row.checkIn || '',\n          checkOut: row.checkOut || '',\n        };\n      }).filter(r => r.employeeId && r.date);\n\n      if (recordsToImport.length === 0) {\n        toast.error('No valid records found. Ensure Employee IDs or Names match the system.');\n        setImporting(false);\n        return;\n      }\n\n      const res = await fetch('/api/attendance/bulk-upload', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ records: recordsToImport }),\n      });\n      const data = await res.json();\n\n      if (res.ok) {\n        setImportResult(data);\n        toast.success(`Processed ${data.successCount} records successfully!`);\n        loadData();\n      } else {\n        toast.error(data.error || 'Import failed');\n      }\n    } catch (err: any) {\n      toast.error('Import failed: ' + err.message);\n    }\n    setImporting(false);\n  };\n\n  // ── Export Master Excel Sheet (firm-wise sheets) ──\n  const handleExportMasterSheet = async () => {\n    setMasterExporting(true);\n    try {\n      const params = new URLSearchParams({\n        firm: masterFirm,\n        month: filterMonth,\n        year: filterYear,\n      });\n      const res = await fetch(`/api/attendance/export-master?${params}`);\n      if (!res.ok) {\n        const errData = await res.json().catch(() => ({}));\n        toast.error(errData.error || 'Master sheet export failed');\n        setMasterExporting(false);\n        return;\n      }\n      const blob = await res.blob();\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = `Master_Sheet_${MONTHS[parseInt(filterMonth) - 1]}_${filterYear}.xlsx`;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      window.URL.revokeObjectURL(url);\n      toast.success('Master Excel Sheet downloaded successfully!');\n    } catch (err) {\n      console.error('Master export error:', err);\n      toast.error('Master sheet export failed. Please try again.');\n    }\n    setMasterExporting(false);\n  };\n\n  // ── Summary cards config — clickable for daily tab ──\n  const statCards = [\n    { title: 'Present', value: summary.present, icon: CheckCircle, gradient: 'gradient-success', color: 'text-emerald-500', filter: 'present' },\n    { title: 'Absent', value: summary.absent, icon: XCircle, gradient: 'gradient-danger', color: 'text-red-500', filter: 'absent' },\n    { title: 'Late', value: summary.late, icon: AlertTriangle, gradient: 'gradient-warning', color: 'text-yellow-500', filter: 'late' },\n    { title: 'Early Out', value: summary.earlyOut, icon: Clock, gradient: 'gradient-rose', color: 'text-rose-500', filter: 'early-out' },\n    { title: 'OT Hours', value: summary.ot, icon: Timer, gradient: 'gradient-info', color: 'text-cyan-500', isHours: true, filter: 'ot' },\n  ];\n\n  // ── Filtered employees for the dialog searchable list ──\n  const filteredEmployees = useMemo(() => {\n    let list = employees;\n    if (employeeSearch) {\n      const q = employeeSearch.toLowerCase();\n      list = list.filter((e) =>\n        e.fullName.toLowerCase().includes(q) || e.employeeId.toLowerCase().includes(q)\n      );\n    }\n    return list;\n  }, [employees, employeeSearch]);\n\n  // Selected employee info\n  const selectedEmployee = useMemo(() => {\n    return employees.find((e) => e.employeeId === form.employeeId);\n  }, [employees, form.employeeId]);\n\n  return (\n    <div className=\"space-y-4\">\n      {/* ── Header ── */}\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\"\n      >\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <Clock className=\"w-5 h-5 text-gold\" />\n            Attendance Tracker\n          </h2>\n          <p className=\"text-sm text-muted-foreground\">\n            Auto-calculated working hours, overtime & deductions\n          </p>\n        </div>\n        <Button\n          className=\"gradient-laxree text-white gap-1.5 shrink-0\"\n          size=\"sm\"\n          onClick={() => setOpen(true)}\n        >\n          <Clock className=\"w-4 h-4\" /> Mark Attendance\n        </Button>\n      </motion.div>\n\n      {/* ── Date Picker + Summary Cards (clickable) ── */}\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"glass-card p-4 space-y-4 border border-gold/10\"\n      >\n        {/* Date Picker Row */}\n        <div className=\"flex flex-col sm:flex-row items-start sm:items-center gap-3\">\n          <div className=\"flex items-center gap-2\">\n            <CalendarDays className=\"w-5 h-5 text-gold\" />\n            <span className=\"text-sm font-semibold\">Select Date</span>\n          </div>\n          <Input\n            type=\"date\"\n            value={filterDate}\n            onChange={(e) => {\n              setFilterDate(e.target.value);\n              setStatusFilter('all');\n              // Auto-set month/year from date for monthly tab sync\n              if (e.target.value) {\n                const d = new Date(e.target.value);\n                setFilterMonth(String(d.getMonth() + 1));\n                setFilterYear(String(d.getFullYear()));\n              }\n            }}\n            className=\"w-full sm:w-48 h-10 text-sm font-medium input-premium rounded-lg\"\n          />\n          {filterDate && (\n            <span className=\"text-xs text-muted-foreground\">\n              {new Date(filterDate + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })}\n            </span>\n          )}\n          <div className=\"sm:ml-auto flex items-center gap-2\">\n            <Select value={filterFirm} onValueChange={(v) => { setFilterFirm(v); setStatusFilter('all'); }}>\n              <SelectTrigger className=\"w-32 h-9 text-xs\">\n                <Building2 className=\"w-3.5 h-3.5 mr-1 text-muted-foreground\" />\n                <SelectValue placeholder=\"All Firms\" />\n              </SelectTrigger>\n              <SelectContent>\n                <SelectItem value=\"all\">All Firms</SelectItem>\n                {FIRMS.map((f) => (<SelectItem key={f} value={f}>{f}</SelectItem>))}\n              </SelectContent>\n            </Select>\n            <Select value={filterLocation} onValueChange={(v) => { setFilterLocation(v); setStatusFilter('all'); }}>\n              <SelectTrigger className=\"w-36 h-9 text-xs\">\n                <MapPin className=\"w-3.5 h-3.5 mr-1 text-muted-foreground\" />\n                <SelectValue placeholder=\"All Locations\" />\n              </SelectTrigger>\n              <SelectContent>\n                <SelectItem value=\"all\">All Locations</SelectItem>\n                {LOCATIONS.map((l) => (<SelectItem key={l} value={l}>{l}</SelectItem>))}\n              </SelectContent>\n            </Select>\n          </div>\n        </div>\n\n        {/* Clickable Summary Cards */}\n        <div className=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3\">\n          {/* \"All\" card */}\n          <motion.div\n            initial={{ opacity: 0, y: 10 }}\n            animate={{ opacity: 1, y: 0 }}\n            transition={{ delay: 0 }}\n            className={`cursor-pointer transition-all duration-200 rounded-xl border-2 ${\n              statusFilter === 'all'\n                ? 'border-gold shadow-lg shadow-gold/10 kpi-card'\n                : 'border-transparent kpi-card hover:border-gold/30'\n            }`}\n            onClick={() => setStatusFilter('all')}\n          >\n            <Card className=\"border-0 shadow-none bg-transparent\">\n              <CardContent className=\"p-3 flex items-center gap-3\">\n                <div className=\"w-10 h-10 rounded-xl gradient-laxree flex items-center justify-center shrink-0 shadow-lg\">\n                  <Users className=\"w-5 h-5 text-white\" />\n                </div>\n                <div className=\"min-w-0\">\n                  <p className=\"text-[10px] text-muted-foreground font-medium truncate\">Total</p>\n                  <p className=\"text-xl font-bold\">\n                    <AnimatedCounter value={records.length} />\n                  </p>\n                </div>\n              </CardContent>\n            </Card>\n          </motion.div>\n          {statCards.map((card, i) => {\n            const Icon = card.icon;\n            const isActive = statusFilter === card.filter;\n            return (\n              <motion.div\n                key={card.title}\n                initial={{ opacity: 0, y: 10 }}\n                animate={{ opacity: 1, y: 0 }}\n                transition={{ delay: (i + 1) * 0.05 }}\n                className={`cursor-pointer transition-all duration-200 rounded-xl border-2 ${\n                  isActive\n                    ? 'border-gold shadow-lg shadow-gold/10 kpi-card'\n                    : 'border-transparent kpi-card hover:border-gold/30'\n                }`}\n                onClick={() => setStatusFilter(isActive ? 'all' : card.filter)}\n              >\n                <Card className=\"border-0 shadow-none bg-transparent\">\n                  <CardContent className=\"p-3 flex items-center gap-3\">\n                    <div className={`w-10 h-10 rounded-xl ${card.gradient} flex items-center justify-center shrink-0 shadow-lg ${isActive ? 'animate-pulse' : ''}`}>\n                      <Icon className=\"w-5 h-5 text-white\" />\n                    </div>\n                    <div className=\"min-w-0\">\n                      <p className=\"text-[10px] text-muted-foreground font-medium truncate\">{card.title}</p>\n                      <p className=\"text-xl font-bold\">\n                        {card.isHours ? (\n                          <span>{formatOT(card.value)}</span>\n                        ) : (\n                          <AnimatedCounter\n                            value={card.value}\n                            suffix={'suffix' in card ? (card as any).suffix : ''}\n                            decimals={'decimals' in card ? (card as any).decimals : 0}\n                          />\n                        )}\n                      </p>\n                    </div>\n                  </CardContent>\n                </Card>\n              </motion.div>\n            );\n          })}\n        </div>\n\n        {/* Active filter indicator */}\n        {statusFilter !== 'all' && (\n          <div className=\"flex items-center gap-2\">\n            <span className=\"text-xs text-muted-foreground\">Showing:</span>\n            <span className=\"inline-flex items-center px-2.5 py-1 rounded-full text-xs font-bold bg-gold/10 text-gold border border-gold/20\">\n              {statCards.find(c => c.filter === statusFilter)?.title || statusFilter} ({filteredRecords.length} records)\n            </span>\n            <button\n              className=\"text-xs text-muted-foreground hover:text-gold underline\"\n              onClick={() => setStatusFilter('all')}\n            >\n              Show All\n            </button>\n          </div>\n        )}\n      </motion.div>\n\n      {/* ── Tabs: Daily / Monthly / Import ── */}\n      <Tabs defaultValue=\"daily\" className=\"space-y-4\">\n        <TabsList className=\"bg-muted/50\">\n          <TabsTrigger value=\"daily\" className=\"gap-1.5 text-xs\">\n            <CalendarDays className=\"w-3.5 h-3.5\" /> Daily\n          </TabsTrigger>\n          <TabsTrigger value=\"monthly\" className=\"gap-1.5 text-xs\">\n            <FileSpreadsheet className=\"w-3.5 h-3.5\" /> Monthly\n          </TabsTrigger>\n          <TabsTrigger value=\"import\" className=\"gap-1.5 text-xs\">\n            <Upload className=\"w-3.5 h-3.5\" /> Import\n          </TabsTrigger>\n        </TabsList>\n\n        {/* ══════════════════════════════════════════════════\n            DAILY ATTENDANCE TAB\n            ══════════════════════════════════════════════════ */}\n        <TabsContent value=\"daily\" className=\"space-y-4\">\n          {/* ── Search + Export Row ── */}\n          <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className=\"flex flex-col sm:flex-row gap-3 items-stretch sm:items-center\">\n            <div className=\"relative flex-1\">\n              <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n              <Input className=\"pl-9 h-9\" placeholder=\"Search employee by name or ID...\" value={searchEmployee} onChange={(e) => setSearchEmployee(e.target.value)} />\n            </div>\n            <Button variant=\"outline\" size=\"sm\" className=\"h-9 gap-1.5 shrink-0\" onClick={handleExportDailyExcel}>\n              <FileDown className=\"w-3.5 h-3.5\" /> Export Excel\n            </Button>\n            <Button\n              variant=\"outline\"\n              size=\"sm\"\n              className=\"h-9 gap-1.5 shrink-0 border-red-500/30 hover:border-red-500/60 hover:bg-red-500/5 text-red-500\"\n              onClick={async () => {\n                if (!confirm('Are you sure you want to CLEAR ALL attendance records? This cannot be undone!')) return;\n                if (!confirm('FINAL WARNING: All attendance data will be permanently deleted. Continue?')) return;\n                try {\n                  const res = await fetch('/api/attendance/clear-all', { method: 'DELETE' });\n                  if (res.ok) {\n                    const data = await res.json();\n                    toast.success(`Cleared ${data.deletedCount} attendance records`);\n                    loadData();\n                  } else {\n                    toast.error('Failed to clear attendance records');\n                  }\n                } catch {\n                  toast.error('Failed to clear attendance records');\n                }\n              }}\n            >\n              <Trash2 className=\"w-3.5 h-3.5\" /> Clear All\n            </Button>\n          </motion.div>\n\n          {/* ── Attendance Table ── */}\n          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-0\">\n                <div className=\"overflow-auto max-h-[65vh]\" style={{ WebkitOverflowScrolling: 'touch' }}>\n                  <Table id=\"daily-attendance-table\">\n                    <TableHeader>\n                      <TableRow className=\"hover:bg-transparent sticky top-0 bg-card z-10\">\n                        <TableHead className=\"min-w-[160px]\">Employee</TableHead>\n                        <TableHead className=\"min-w-[70px]\">Emp Code</TableHead>\n                        <TableHead className=\"hidden md:table-cell min-w-[70px]\">Company</TableHead>\n                        <TableHead className=\"min-w-[80px]\">In Time</TableHead>\n                        <TableHead className=\"hidden sm:table-cell min-w-[70px]\">Out Time</TableHead>\n                        <TableHead className=\"min-w-[50px]\">Hrs</TableHead>\n                        <TableHead className=\"min-w-[80px]\">Status</TableHead>\n                        <TableHead className=\"hidden lg:table-cell min-w-[50px]\">OT</TableHead>\n                        <TableHead className=\"w-[70px] sticky right-0 bg-card\">Actions</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {loading ? (\n                        Array.from({ length: 5 }).map((_, i) => (\n                          <TableRow key={i}>\n                            {Array.from({ length: 9 }).map((_, j) => (\n                              <TableCell key={j}><div className=\"h-4 bg-muted/50 rounded animate-pulse\" /></TableCell>\n                            ))}\n                          </TableRow>\n                        ))\n                      ) : filteredRecords.length === 0 ? (\n                        <TableRow>\n                          <TableCell colSpan={9} className=\"text-center py-12 text-muted-foreground\">\n                            <CalendarDays className=\"w-10 h-10 mx-auto mb-2 opacity-30\" />\n                            <p className=\"font-medium\">No attendance records for this date</p>\n                            <p className=\"text-xs mt-1\">Select a different date or import attendance data</p>\n                          </TableCell>\n                        </TableRow>\n                      ) : (\n                        filteredRecords.map((rec) => (\n                          <TableRow key={rec.id} className=\"hover:bg-muted/30 transition-colors\">\n                            <TableCell>\n                              <div className=\"flex items-center gap-2\">\n                                <div className=\"w-7 h-7 rounded-full gradient-laxree flex items-center justify-center text-white text-[10px] font-bold shrink-0\">\n                                  {rec.employee?.fullName?.charAt(0) || '?'}\n                                </div>\n                                <div className=\"min-w-0 overflow-hidden\">\n                                  <p className=\"text-sm font-medium truncate max-w-[120px]\">{rec.employee?.fullName || rec.employeeId}</p>\n                                </div>\n                              </div>\n                            </TableCell>\n                            <TableCell className=\"text-xs font-mono text-muted-foreground\">{rec.employeeId}</TableCell>\n                            <TableCell className=\"hidden md:table-cell\">\n                              <FirmBadge firm={getFirmFromEmployeeId(rec.employeeId) || rec.employee?.department || ''} />\n                            </TableCell>\n                            <TableCell className=\"text-sm font-mono whitespace-nowrap\">{rec.checkIn || '—'}</TableCell>\n                            <TableCell className=\"hidden sm:table-cell text-sm font-mono whitespace-nowrap\">{rec.checkOut || '—'}</TableCell>\n                            <TableCell className=\"text-sm font-medium whitespace-nowrap\">{rec.totalHours > 0 ? `${formatHours(rec.totalHours)}h` : '—'}</TableCell>\n                            <TableCell><StatusBadge status={rec.status} /></TableCell>\n                            <TableCell className=\"hidden lg:table-cell text-sm whitespace-nowrap\">\n                              {rec.overtimeHours > 0 ? (\n                                <span className=\"text-cyan-600 dark:text-cyan-400 font-medium\">{formatOT(rec.overtimeHours)}</span>\n                              ) : '—'}\n                            </TableCell>\n                            <TableCell className=\"sticky right-0 bg-card\">\n                              <div className=\"flex items-center gap-1\">\n                                <Button variant=\"ghost\" size=\"sm\" className=\"h-7 w-7 p-0\" onClick={() => handleEdit(rec)} title=\"Edit\">\n                                  <Pencil className=\"w-3 h-3\" />\n                                </Button>\n                                <Button variant=\"ghost\" size=\"sm\" className=\"h-7 w-7 p-0 text-destructive hover:text-destructive\" onClick={() => handleDelete(rec.id)} title=\"Delete\">\n                                  <Trash2 className=\"w-3 h-3\" />\n                                </Button>\n                              </div>\n                            </TableCell>\n                          </TableRow>\n                        ))\n                      )}\n                    </TableBody>\n                  </Table>\n                </div>\n              </CardContent>\n            </Card>\n          </motion.div>\n        </TabsContent>\n\n        {/* ══════════════════════════════════════════════════\n            MONTHLY ATTENDANCE TAB\n            ══════════════════════════════════════════════════ */}\n        <TabsContent value=\"monthly\" className=\"space-y-4\">\n          {/* ── Employee Selector ── */}\n          <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className=\"glass-card p-3\">\n            <div className=\"flex flex-col sm:flex-row gap-3 flex-wrap items-end\">\n              <div className=\"flex-1 min-w-[200px]\">\n                <Label className=\"text-xs text-muted-foreground mb-1 block\">Select Employee</Label>\n                <Select value={monthlyEmpId} onValueChange={setMonthlyEmpId}>\n                  <SelectTrigger className=\"w-full h-9\">\n                    <Search className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n                    <SelectValue placeholder=\"Select Employee...\" />\n                  </SelectTrigger>\n                  <SelectContent>\n                    {employees.sort((a, b) => a.fullName.localeCompare(b.fullName)).map(e => (\n                      <SelectItem key={e.employeeId} value={e.employeeId}>\n                        {e.fullName} ({e.employeeId})\n                      </SelectItem>\n                    ))}\n                  </SelectContent>\n                </Select>\n              </div>\n              <Select value={filterMonth} onValueChange={setFilterMonth}>\n                <SelectTrigger className=\"w-full sm:w-36 h-9\"><SelectValue /></SelectTrigger>\n                <SelectContent>\n                  {MONTHS.map((m, i) => (<SelectItem key={i + 1} value={String(i + 1)}>{m}</SelectItem>))}\n                </SelectContent>\n              </Select>\n              <Select value={filterYear} onValueChange={setFilterYear}>\n                <SelectTrigger className=\"w-full sm:w-24 h-9\"><SelectValue /></SelectTrigger>\n                <SelectContent>\n                  {[2024, 2025, 2026, 2027].map(y => (<SelectItem key={y} value={String(y)}>{y}</SelectItem>))}\n                </SelectContent>\n              </Select>\n              {monthlySummary && (\n                <Button variant=\"outline\" size=\"sm\" className=\"h-9 gap-1.5\" onClick={handleExportExcel}>\n                  <FileDown className=\"w-3.5 h-3.5\" /> Export Excel\n                </Button>\n              )}\n            </div>\n          </motion.div>\n\n          {/* ── Monthly Summary Card — Spreadsheet Format ── */}\n          {monthlyLoading ? (\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-8 text-center text-muted-foreground\">\n                <div className=\"animate-spin w-8 h-8 border-2 border-gold border-t-transparent rounded-full mx-auto mb-3\" />\n                <p>Loading monthly summary...</p>\n              </CardContent>\n            </Card>\n          ) : monthlySummary ? (\n            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardContent className=\"p-4 md:p-6 space-y-4\">\n                  {/* Employee Info Header */}\n                  <div className=\"flex items-center gap-3 pb-3 border-b border-border/50\">\n                    {(() => {\n                      const firmCode = getFirmFromEmployeeId(monthlySummary.employee.employeeId) || monthlySummary.employee.firm || monthlySummary.employee.department;\n                      const logoSrc = FIRM_LOGOS[firmCode];\n                      return logoSrc ? (\n                        <div className=\"w-14 h-14 rounded-xl overflow-hidden border-2 border-gold/30 shrink-0 bg-white p-1\">\n                          <Image src={logoSrc} alt={firmCode} width={48} height={48} className=\"w-full h-full object-contain\" />\n                        </div>\n                      ) : (\n                        <div className=\"w-14 h-14 rounded-xl gradient-laxree flex items-center justify-center text-white text-lg font-bold shrink-0\">\n                          {monthlySummary.employee.fullName.charAt(0)}\n                        </div>\n                      );\n                    })()}\n                    <div className=\"min-w-0\">\n                      <h3 className=\"font-bold text-lg\">{monthlySummary.employee.fullName}</h3>\n                      <div className=\"flex items-center gap-2 text-sm text-muted-foreground flex-wrap\">\n                        <span className=\"font-mono\">{monthlySummary.employee.employeeId}</span>\n                        <span>•</span>\n                        <FirmBadge firm={getFirmFromEmployeeId(monthlySummary.employee.employeeId) || monthlySummary.employee.firm || monthlySummary.employee.department} />\n                        <span>•</span>\n                        <span>{monthlySummary.employee.location}</span>\n                        <span>•</span>\n                        <span>{monthlySummary.monthName} {monthlySummary.year}</span>\n                      </div>\n                    </div>\n                  </div>\n\n                  {/* ── Spreadsheet-style Summary Table ── */}\n                  <div className=\"overflow-x-auto rounded-lg border border-border/50\">\n                    <table className=\"w-full text-sm border-collapse\">\n                      <thead>\n                        <tr className=\"bg-emerald-700 dark:bg-emerald-900 text-white\">\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">Days Present</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">Days Absent</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">Half Days</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">AL</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">UL</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">Total Hrs Worked</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">OT Hrs</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider border-r border-emerald-600/30\">Sunday Hrs</th>\n                          <th className=\"px-3 py-2.5 text-left text-xs font-bold uppercase tracking-wider\">Total Hrs (incl. Sunday)</th>\n                        </tr>\n                      </thead>\n                      <tbody>\n                        <tr className=\"bg-muted/30 hover:bg-muted/50 transition-colors\">\n                          <td className=\"px-3 py-3 font-bold text-emerald-600 dark:text-emerald-400 border-r border-border/30\">{monthlySummary.presentDays}</td>\n                          <td className=\"px-3 py-3 font-bold text-red-500 border-r border-border/30\">{monthlySummary.absentDays}</td>\n                          <td className=\"px-3 py-3 font-bold text-orange-500 border-r border-border/30\">{monthlySummary.halfDays}</td>\n                          <td className=\"px-3 py-3 text-blue-500 border-r border-border/30\">{monthlySummary.annualLeaves || 0}</td>\n                          <td className=\"px-3 py-3 text-amber-600 dark:text-amber-400 border-r border-border/30\">{monthlySummary.unpaidLeaves || 0}</td>\n                          <td className=\"px-3 py-3 font-bold text-cyan-600 dark:text-cyan-400 border-r border-border/30\">{displayHHMM(monthlySummary.totalWorkHours)}</td>\n                          <td className=\"px-3 py-3 font-bold text-yellow-600 dark:text-yellow-400 border-r border-border/30\">{formatOT(monthlySummary.totalOvertimeHours)}</td>\n                          <td className=\"px-3 py-3 text-blue-600 dark:text-blue-400 border-r border-border/30\">{displayHHMM(monthlySummary.totalSundayHours)}</td>\n                          <td className=\"px-3 py-3 font-bold text-gold\">{displayHHMM(monthlySummary.totalHrsInclSunday || (monthlySummary.totalWorkHours || 0))}</td>\n                        </tr>\n                      </tbody>\n                    </table>\n                  </div>\n\n                  {/* Additional Info Row */}\n                  <div className=\"grid grid-cols-3 sm:grid-cols-6 gap-2\">\n                    {[\n                      { label: 'Working Days', value: monthlySummary.totalWorkingDays, color: 'text-foreground' },\n                      { label: 'Weekly Offs', value: monthlySummary.weeklyOffs, color: 'text-sky-500' },\n                      { label: 'Sundays', value: monthlySummary.sundays, color: 'text-blue-500' },\n                      { label: 'Late Entries', value: monthlySummary.lateEntries, color: 'text-amber-500' },\n                      { label: 'Early Outs', value: monthlySummary.earlyOuts || 0, color: 'text-rose-500' },\n                      { label: 'Shift Hrs', value: `${displayHHMM(monthlySummary.employee.shiftHours)}h`, color: 'text-muted-foreground' },\n                    ].map(item => (\n                      <div key={item.label} className=\"p-2 rounded-lg bg-muted/20 text-center\">\n                        <p className=\"text-[9px] text-muted-foreground font-medium uppercase tracking-wider\">{item.label}</p>\n                        <p className={`text-sm font-bold ${item.color}`}>{item.value}</p>\n                      </div>\n                    ))}\n                  </div>\n\n                  <Separator />\n\n                  {/* Daily Records Table — Full scrollable */}\n                  <div>\n                    <h4 className=\"text-sm font-semibold mb-2 flex items-center gap-1.5\">\n                      <ChevronRight className=\"w-4 h-4 text-gold\" />\n                      Daily Attendance Breakdown ({monthlySummary.records.length} days)\n                    </h4>\n                    <div\n                      className=\"rounded-lg border border-border/50\"\n                      style={{\n                        maxHeight: '60vh',\n                        overflowY: 'auto',\n                        WebkitOverflowScrolling: 'touch',\n                        scrollBehavior: 'smooth',\n                      }}\n                    >\n                      <Table>\n                        <TableHeader>\n                          <TableRow className=\"hover:bg-transparent sticky top-0 bg-card z-10\">\n                            <TableHead className=\"text-xs\">Date</TableHead>\n                            <TableHead className=\"text-xs\">Day</TableHead>\n                            <TableHead className=\"text-xs\">In</TableHead>\n                            <TableHead className=\"text-xs\">Out</TableHead>\n                            <TableHead className=\"text-xs\">Hrs</TableHead>\n                            <TableHead className=\"text-xs\">Status</TableHead>\n                            <TableHead className=\"text-xs\">OT</TableHead>\n                          </TableRow>\n                        </TableHeader>\n                        <TableBody>\n                          {(() => {\n                            const daysInMonth = new Date(monthlySummary.year, monthlySummary.month, 0).getDate();\n                            const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n                            const rows = [];\n                            for (let day = 1; day <= daysInMonth; day++) {\n                              const dateStr = `${monthlySummary.year}-${String(monthlySummary.month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;\n                              const dateObj = new Date(dateStr + 'T00:00:00');\n                              const dayName = dayNames[dateObj.getDay()];\n                              const rec = monthlySummary.records.find((r: any) => {\n                                const rDate = new Date(r.date);\n                                return rDate.getFullYear() === monthlySummary.year && rDate.getMonth() + 1 === monthlySummary.month && rDate.getDate() === day;\n                              });\n                              const isSunday = dateObj.getDay() === 0;\n                              rows.push(\n                                <TableRow\n                                  key={day}\n                                  className={`${isSunday ? 'bg-blue-500/5' : 'hover:bg-muted/30'} transition-colors`}\n                                >\n                                  <TableCell className=\"text-xs whitespace-nowrap font-medium\">\n                                    {dateObj.toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}\n                                  </TableCell>\n                                  <TableCell className={`text-xs ${isSunday ? 'text-blue-500 font-bold' : ''}`}>{dayName}</TableCell>\n                                  <TableCell className=\"text-xs font-mono\">{rec?.checkIn || '—'}</TableCell>\n                                  <TableCell className=\"text-xs font-mono\">{rec?.checkOut || '—'}</TableCell>\n                                  <TableCell className=\"text-xs font-medium\">{rec && rec.totalHours > 0 ? `${formatHours(rec.totalHours)}h` : '—'}</TableCell>\n                                  <TableCell>\n                                    {rec ? (\n                                      <StatusBadge status={rec.status} />\n                                    ) : isSunday ? (\n                                      <StatusBadge status=\"weekly-off\" />\n                                    ) : (\n                                      <span className=\"text-xs text-muted-foreground italic\">No Record</span>\n                                    )}\n                                  </TableCell>\n                                  <TableCell className=\"text-xs\">{rec && rec.overtimeHours > 0 ? formatOT(rec.overtimeHours) : '—'}</TableCell>\n                                </TableRow>\n                              );\n                            }\n                            return rows;\n                          })()}\n                        </TableBody>\n                      </Table>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n            </motion.div>\n          ) : (\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-8 text-center text-muted-foreground\">\n                <CalendarDays className=\"w-12 h-12 mx-auto mb-3 opacity-30\" />\n                <p>Select an employee to view monthly attendance summary</p>\n              </CardContent>\n            </Card>\n          )}\n\n          {/* ── Master Excel Sheet Export Section ── */}\n          <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className=\"glass-card p-3 border border-gold/20\">\n            <div className=\"flex items-center gap-2 mb-2\">\n              <FileSpreadsheet className=\"w-4 h-4 text-gold\" />\n              <h3 className=\"text-sm font-semibold\">Master Excel Sheet</h3>\n              <span className=\"text-[10px] text-muted-foreground\">— Firm-wise monthly attendance with calendar format</span>\n            </div>\n            <div className=\"flex flex-col sm:flex-row gap-3 flex-wrap items-end\">\n              <div className=\"min-w-[140px]\">\n                <Label className=\"text-xs text-muted-foreground mb-1 block\">Select Firm</Label>\n                <Select value={masterFirm} onValueChange={setMasterFirm}>\n                  <SelectTrigger className=\"w-full h-9\">\n                    <Building2 className=\"w-3.5 h-3.5 mr-1 text-muted-foreground\" />\n                    <SelectValue placeholder=\"All Firms\" />\n                  </SelectTrigger>\n                  <SelectContent>\n                    <SelectItem value=\"all\">All Firms (Separate Sheets)</SelectItem>\n                    {FIRMS.map((f) => (<SelectItem key={f} value={f}>{f} — {FIRM_NAMES[f]}</SelectItem>))}\n                  </SelectContent>\n                </Select>\n              </div>\n              <Select value={filterMonth} onValueChange={setFilterMonth} disabled>\n                <SelectTrigger className=\"w-full sm:w-36 h-9\"><SelectValue /></SelectTrigger>\n                <SelectContent>\n                  {MONTHS.map((m, i) => (<SelectItem key={i + 1} value={String(i + 1)}>{m}</SelectItem>))}\n                </SelectContent>\n              </Select>\n              <Select value={filterYear} onValueChange={setFilterYear} disabled>\n                <SelectTrigger className=\"w-full sm:w-24 h-9\"><SelectValue /></SelectTrigger>\n                <SelectContent>\n                  {[2024, 2025, 2026, 2027].map(y => (<SelectItem key={y} value={String(y)}>{y}</SelectItem>))}\n                </SelectContent>\n              </Select>\n              <Button\n                variant=\"outline\"\n                size=\"sm\"\n                className=\"h-9 gap-1.5 border-gold/30 hover:border-gold/60 hover:bg-gold/5 text-gold\"\n                onClick={handleExportMasterSheet}\n                disabled={masterExporting}\n              >\n                {masterExporting ? (\n                  <>\n                    <div className=\"w-3.5 h-3.5 border-2 border-gold border-t-transparent rounded-full animate-spin\" />\n                    Generating...\n                  </>\n                ) : (\n                  <>\n                    <FileDown className=\"w-3.5 h-3.5\" /> Download Master Sheet\n                  </>\n                )}\n              </Button>\n            </div>\n          </motion.div>\n        </TabsContent>\n\n        {/* ══════════════════════════════════════════════════\n            DAILY ATTENDANCE IMPORT TAB\n            ══════════════════════════════════════════════════ */}\n        <TabsContent value=\"import\" className=\"space-y-4\">\n          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-6 space-y-6\">\n                {/* Upload Section */}\n                <div>\n                  <div className=\"flex items-center justify-between mb-3\">\n                    <h3 className=\"text-sm font-semibold flex items-center gap-2\">\n                      <Upload className=\"w-4 h-4 text-gold\" />\n                      Upload Attendance Sheet\n                    </h3>\n                    <Button\n                      variant=\"outline\"\n                      size=\"sm\"\n                      className=\"h-8 gap-1.5 text-xs border-gold/30 hover:border-gold/60 hover:bg-gold/5\"\n                      onClick={handleDownloadTemplate}\n                    >\n                      <Download className=\"w-3.5 h-3.5\" /> Download Template\n                    </Button>\n                  </div>\n\n                  {/* Attendance Date Picker */}\n                  <div className=\"mb-4\">\n                    <Label htmlFor=\"importDate\" className=\"text-xs font-semibold flex items-center gap-1.5 mb-1.5\">\n                      <CalendarDays className=\"w-3.5 h-3.5 text-gold\" />\n                      Attendance Date\n                    </Label>\n                    <Input\n                      id=\"importDate\"\n                      type=\"date\"\n                      value={importDate}\n                      onChange={(e) => setImportDate(e.target.value)}\n                      className=\"w-full sm:w-56 h-9 text-sm font-medium input-premium rounded-lg\"\n                    />\n                    <p className=\"text-[10px] text-muted-foreground mt-1\">\n                      This date will be used for all rows in the uploaded file (daily template has no Date column per row).\n                    </p>\n                  </div>\n\n                  <div className=\"border-2 border-dashed border-border rounded-xl p-8 text-center hover:border-gold/50 transition-colors\">\n                    <input\n                      ref={fileInputRef}\n                      type=\"file\"\n                      accept=\".xlsx,.xls,.csv\"\n                      onChange={handleFileUpload}\n                      className=\"hidden\"\n                    />\n                    <FileSpreadsheet className=\"w-12 h-12 mx-auto mb-3 text-muted-foreground/50\" />\n                    <p className=\"text-sm text-muted-foreground mb-3\">\n                      Upload Excel (.xlsx, .xls) or CSV file with attendance data\n                    </p>\n                    <Button\n                      variant=\"outline\"\n                      onClick={() => fileInputRef.current?.click()}\n                      className=\"gap-1.5\"\n                    >\n                      <Upload className=\"w-4 h-4\" /> Choose File\n                    </Button>\n                    {importFile && (\n                      <p className=\"text-xs text-muted-foreground mt-2\">\n                        Selected: {importFile.name} ({(importFile.size / 1024).toFixed(1)} KB)\n                      </p>\n                    )}\n                  </div>\n                  <div className=\"mt-3 p-3 rounded-lg bg-gold/5 border border-gold/10\">\n                    <Info className=\"w-4 h-4 text-gold inline mr-1.5 -mt-0.5\" />\n                    <span className=\"text-xs text-muted-foreground\">\n                      <strong>Template format:</strong> SNo, E. Code, Name, Shift, InTime, OutTime, Work Dur., OT, Tot. Dur., Status, Remarks. \n                      The daily template has no Date column — set the <strong>Attendance Date</strong> above before uploading.\n                      Click <strong>\"Download Template\"</strong> to get the correct format with all employees pre-filled. \n                      The system auto-converts Excel dates/times and matches employees by E. Code or Name.\n                      Also supports the old format (Employee ID, Employee Name, Date, In Time, Out Time, Status).\n                    </span>\n                  </div>\n                </div>\n\n                {/* Preview Section */}\n                {importPreview.length > 0 && (\n                  <div>\n                    <h3 className=\"text-sm font-semibold mb-3 flex items-center gap-2\">\n                      <Search className=\"w-4 h-4 text-gold\" />\n                      Preview ({importPreview.length} records found)\n                      {!importPreview.some(r => r.date) && importDate && (\n                        <span className=\"text-[10px] text-muted-foreground font-normal ml-1\">\n                          — using date: {importDate}\n                        </span>\n                      )}\n                    </h3>\n                    <div className=\"max-h-[40vh] overflow-auto\" style={{ WebkitOverflowScrolling: 'touch' }}>\n                      <Table>\n                        <TableHeader>\n                          <TableRow className=\"hover:bg-transparent\">\n                            <TableHead className=\"text-xs\">E. Code</TableHead>\n                            <TableHead className=\"text-xs\">Name</TableHead>\n                            <TableHead className=\"text-xs\">Shift</TableHead>\n                            <TableHead className=\"text-xs\">InTime</TableHead>\n                            <TableHead className=\"text-xs\">OutTime</TableHead>\n                            <TableHead className=\"text-xs\">Status</TableHead>\n                            <TableHead className=\"text-xs\">Remarks</TableHead>\n                          </TableRow>\n                        </TableHeader>\n                        <TableBody>\n                          {importPreview.slice(0, 100).map((row, i) => (\n                            <TableRow key={i} className=\"hover:bg-muted/30\">\n                              <TableCell className=\"text-xs font-mono\">{row.employeeId || '—'}</TableCell>\n                              <TableCell className=\"text-xs\">{row.employeeName || '—'}</TableCell>\n                              <TableCell className=\"text-xs\">{row.shift || '—'}</TableCell>\n                              <TableCell className=\"text-xs font-mono\">{row.checkIn || '—'}</TableCell>\n                              <TableCell className=\"text-xs font-mono\">{row.checkOut || '—'}</TableCell>\n                              <TableCell className=\"text-xs\">{row.status || '—'}</TableCell>\n                              <TableCell className=\"text-xs\">{row.remarks || '—'}</TableCell>\n                            </TableRow>\n                          ))}\n                        </TableBody>\n                      </Table>\n                    </div>\n\n                    {/* Process Button */}\n                    <div className=\"flex items-center gap-3 mt-4 pt-4 border-t relative z-10 bg-background\">\n                      <Button\n                        className=\"gradient-laxree text-white gap-1.5 shrink-0\"\n                        onClick={handleProcessImport}\n                        disabled={importing}\n                      >\n                        {importing ? (\n                          <>\n                            <div className=\"w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin\" />\n                            Processing...\n                          </>\n                        ) : (\n                          <>\n                            <CheckCircle className=\"w-4 h-4\" /> Process Attendance\n                          </>\n                        )}\n                      </Button>\n                      <Button\n                        variant=\"outline\"\n                        className=\"shrink-0\"\n                        onClick={() => {\n                          setImportPreview([]);\n                          setImportFile(null);\n                          setImportResult(null);\n                          if (fileInputRef.current) fileInputRef.current.value = '';\n                        }}\n                      >\n                        Clear\n                      </Button>\n                      <span className=\"text-xs text-muted-foreground ml-auto\">{importPreview.length} records ready to process</span>\n                    </div>\n                  </div>\n                )}\n\n                {/* Import Result */}\n                {importResult && (\n                  <div className=\"p-4 rounded-lg bg-muted/30 border\">\n                    <h4 className=\"text-sm font-semibold mb-2\">Import Results</h4>\n                    <div className=\"flex gap-4 text-sm\">\n                      <span className=\"text-emerald-500 font-medium\">Success: {importResult.successCount}</span>\n                      {importResult.errorCount > 0 && (\n                        <span className=\"text-red-500 font-medium\">Errors: {importResult.errorCount}</span>\n                      )}\n                    </div>\n                    {importResult.results?.filter((r: any) => r.error).length > 0 && (\n                      <div className=\"mt-2 text-xs text-red-500\">\n                        {importResult.results.filter((r: any) => r.error).map((r: any, i: number) => (\n                          <p key={i}>{r.employeeId} ({r.date}): {r.error}</p>\n                        ))}\n                      </div>\n                    )}\n                  </div>\n                )}\n              </CardContent>\n            </Card>\n          </motion.div>\n        </TabsContent>\n      </Tabs>\n\n      {/* ── Mark Attendance Dialog ── */}\n      <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) { setForm({ employeeId: '', date: '', checkIn: '', checkOut: '' }); setEmployeeSearch(''); } }}>\n        <DialogContent className=\"sm:max-w-md max-h-[85vh] overflow-y-auto z-[100]\">\n          <DialogHeader>\n            <DialogTitle className=\"flex items-center gap-2\">\n              <Clock className=\"w-5 h-5 text-gold\" />\n              Mark Attendance\n            </DialogTitle>\n            <DialogDescription>Select an employee and enter attendance details</DialogDescription>\n          </DialogHeader>\n          <div className=\"space-y-4 py-2\">\n            {/* Employee Selection */}\n            <div className=\"space-y-2\">\n              <Label className=\"text-sm font-medium\">Employee *</Label>\n              {!form.employeeId ? (\n                <div className=\"space-y-2\">\n                  <div className=\"relative\">\n                    <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n                    <Input\n                      className=\"pl-9\"\n                      placeholder=\"Search employee by name or ID...\"\n                      value={employeeSearch}\n                      onChange={(e) => setEmployeeSearch(e.target.value)}\n                      autoFocus\n                    />\n                  </div>\n                  <div className=\"border rounded-lg max-h-48 overflow-y-auto\">\n                    {filteredEmployees.length === 0 ? (\n                      <p className=\"text-sm text-muted-foreground text-center py-4\">No employees found</p>\n                    ) : (\n                      filteredEmployees.slice(0, 20).map((e) => (\n                        <button\n                          key={e.employeeId}\n                          className=\"w-full text-left px-3 py-2.5 hover:bg-muted/80 text-sm flex items-center justify-between transition-colors border-b border-border/50 last:border-0 gap-2\"\n                          onClick={() => { setForm({ ...form, employeeId: e.employeeId }); setEmployeeSearch(''); }}\n                        >\n                          <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                            <FirmBadge firm={e.department} />\n                            <span className=\"truncate-fix\">{e.fullName}</span>\n                          </div>\n                          <span className=\"text-xs text-muted-foreground font-mono shrink-0\">{e.employeeId}</span>\n                        </button>\n                      ))\n                    )}\n                  </div>\n                </div>\n              ) : (\n                <div className=\"flex items-center justify-between px-3 py-2.5 bg-muted/50 rounded-lg gap-2\">\n                  <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                    <div className=\"w-7 h-7 rounded-full gradient-laxree flex items-center justify-center text-white text-[10px] font-bold shrink-0\">\n                      {selectedEmployee?.fullName?.charAt(0) || '?'}\n                    </div>\n                    <span className=\"text-sm font-medium truncate-fix\">{selectedEmployee?.fullName}</span>\n                    <FirmBadge firm={selectedEmployee?.department || ''} />\n                  </div>\n                  <Button variant=\"ghost\" size=\"sm\" className=\"h-7 text-xs shrink-0 px-2\" onClick={() => setForm({ ...form, employeeId: '' })}>\n                    <X className=\"w-3 h-3 mr-1\" /> Change\n                  </Button>\n                </div>\n              )}\n            </div>\n\n            <div className=\"space-y-2\">\n              <Label className=\"text-sm font-medium\">Date *</Label>\n              <Input type=\"date\" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} className=\"w-full\" />\n            </div>\n            <div className=\"grid grid-cols-2 gap-3\">\n              <div className=\"space-y-2\">\n                <Label className=\"text-sm font-medium\">Check-In Time</Label>\n                <Input type=\"time\" value={form.checkIn} onChange={(e) => setForm({ ...form, checkIn: e.target.value })} className=\"w-full\" />\n              </div>\n              <div className=\"space-y-2\">\n                <Label className=\"text-sm font-medium\">Check-Out Time</Label>\n                <Input type=\"time\" value={form.checkOut} onChange={(e) => setForm({ ...form, checkOut: e.target.value })} className=\"w-full\" />\n              </div>\n            </div>\n\n            <div className=\"flex items-start gap-2 p-3 rounded-lg bg-gold/5 border border-gold/10\">\n              <Info className=\"w-4 h-4 text-gold shrink-0 mt-0.5\" />\n              <p className=\"text-xs text-muted-foreground leading-relaxed\">\n                System auto-calculates working hours, late entry detection, overtime, Sunday hours, and public holiday tracking.\n              </p>\n            </div>\n\n            <Button className=\"w-full gradient-laxree text-white h-10\" onClick={handleSubmit}>\n              Save Attendance\n            </Button>\n          </div>\n        </DialogContent>\n      </Dialog>\n\n      {/* ── Edit Attendance Dialog ── */}\n      <Dialog open={editOpen} onOpenChange={setEditOpen}>\n        <DialogContent className=\"sm:max-w-md z-[100]\">\n          <DialogHeader>\n            <DialogTitle className=\"flex items-center gap-2\">\n              <Pencil className=\"w-5 h-5 text-gold\" />\n              Edit Attendance\n            </DialogTitle>\n            <DialogDescription>Update check-in and check-out times for this attendance record</DialogDescription>\n          </DialogHeader>\n          {editRecord && (\n            <div className=\"space-y-4 py-2\">\n              <div className=\"px-3 py-2.5 bg-muted/50 rounded-lg flex items-center gap-2\">\n                <div className=\"w-8 h-8 rounded-full gradient-laxree flex items-center justify-center text-white text-xs font-bold shrink-0\">\n                  {editRecord.employee?.fullName?.charAt(0) || '?'}\n                </div>\n                <div>\n                  <p className=\"text-sm font-medium\">{editRecord.employee?.fullName || editRecord.employeeId}</p>\n                  <p className=\"text-xs text-muted-foreground\">\n                    {editRecord.employeeId} • {new Date(editRecord.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}\n                  </p>\n                </div>\n                <StatusBadge status={editRecord.status} />\n              </div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div className=\"space-y-2\">\n                  <Label className=\"text-sm font-medium\">Check-In Time</Label>\n                  <Input type=\"time\" value={editForm.checkIn} onChange={(e) => setEditForm({ ...editForm, checkIn: e.target.value })} className=\"w-full\" />\n                </div>\n                <div className=\"space-y-2\">\n                  <Label className=\"text-sm font-medium\">Check-Out Time</Label>\n                  <Input type=\"time\" value={editForm.checkOut} onChange={(e) => setEditForm({ ...editForm, checkOut: e.target.value })} className=\"w-full\" />\n                </div>\n              </div>\n              <div className=\"flex items-start gap-2 p-3 rounded-lg bg-gold/5 border border-gold/10\">\n                <Info className=\"w-4 h-4 text-gold shrink-0 mt-0.5\" />\n                <p className=\"text-xs text-muted-foreground leading-relaxed\">\n                  Hours, OT, late entry, and status will be auto-recalculated when you save.\n                </p>\n              </div>\n              <Button className=\"w-full gradient-laxree text-white h-10\" onClick={handleEditSubmit}>\n                Update Attendance\n              </Button>\n            </div>\n          )}\n        </DialogContent>\n      </Dialog>\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback, useMemo } from 'react';\nimport { motion } from 'framer-motion';\nimport {\n  IndianRupee, Zap, DollarSign, Users, Info,\n  CalendarDays, Building2, Search, FileText, TrendingDown, Clock,\n  Download, Loader2,\n} from 'lucide-react';\nimport * as XLSX from 'xlsx-js-style';\nimport { Card, CardContent } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Input } from '@/components/ui/input';\nimport { Label } from '@/components/ui/label';\nimport { Badge } from '@/components/ui/badge';\nimport { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';\nimport { ScrollArea } from '@/components/ui/scroll-area';\nimport { useHRMSStore } from '@/lib/store';\nimport { toast } from 'sonner';\n\n// ── Constants ──\nconst FIRM_BADGE_CLASS: Record<string, string> = {\n  LAPL: 'firm-badge-lapl',\n  LRSL: 'firm-badge-lrsl',\n  SI: 'firm-badge-si',\n  SDF: 'firm-badge-sdf',\n  Roofing: 'firm-badge-roofing',\n};\n\n// ── Convert decimal hours to HH.MM display format ──\nfunction formatHours(decimal: number): string {\n  if (!decimal || decimal === 0) return '0:00';\n  const hours = Math.floor(decimal);\n  const minutes = Math.round((decimal - hours) * 60);\n  if (minutes >= 60) return `${hours + 1}:00`;\n  return `${hours}:${String(minutes).padStart(2, '0')}`;\n}\n\n// ── Format overtime in clear human-readable format ──\nfunction formatOT(decimal: number): string {\n  if (!decimal || decimal === 0) return '0m';\n  const totalMinutes = Math.round(decimal * 60);\n  if (totalMinutes < 60) return `${totalMinutes}m`;\n  const hours = Math.floor(totalMinutes / 60);\n  const minutes = totalMinutes % 60;\n  if (minutes === 0) return `${hours}h`;\n  return `${hours}h ${minutes}m`;\n}\n\n// ── Display a value that's already in HH:MM format ──\nfunction displayHHMM(value: number | undefined | null): string {\n  if (!value && value !== 0) return '0:00';\n  return formatHours(value);\n}\n\n// ── Get firm code from employee ID prefix ──\nfunction getFirmFromEmployeeId(employeeId: string): string {\n  const id = employeeId.toUpperCase();\n  if (id.startsWith('LAPL')) return 'LAPL';\n  if (id.startsWith('LRSL')) return 'LRSL';\n  if (id.startsWith('SI-') || id.startsWith('SI0')) return 'SI';\n  if (id.startsWith('SDF')) return 'SDF';\n  return ''; // fallback to existing department/firm\n}\n\nconst FIRMS = ['LAPL', 'LRSL', 'SI', 'SDF'];\nconst MONTHS = [\n  'January', 'February', 'March', 'April', 'May', 'June',\n  'July', 'August', 'September', 'October', 'November', 'December',\n];\n\n// ── Payroll Record Type ──\ninterface PayrollRecord {\n  id: string;\n  employeeId: string;\n  month: number;\n  year: number;\n  monthlySalary: number;\n  hourlyRate: number;\n  totalWorkedHrs: number;\n  otHours: number;\n  otRate: number;\n  otAmount: number;\n  sundayHrs: number;\n  sundayCount: number;\n  sundayEarnings: number;\n  earnedSundayHrs: number;\n  totalHrs: number;\n  presentDays: number;\n  absentDays: number;\n  holidayDays: number;\n  grossSalary: number;\n  tdsDeduction: number;\n  loanDeduction: number;\n  advanceDeduction: number;\n  securityDeposit: number;\n  otherDeductions: number;\n  totalDeductions: number;\n  arrear: number;\n  netSalary: number;\n  status: string;\n  employee?: {\n    fullName: string;\n    employeeId: string;\n    department: string;\n    designation: string;\n    location: string;\n    salaryType: string;\n  };\n  // Compat fields\n  baseSalary?: number;\n  perDaySalary?: number;\n  perDayRate?: number;\n  daysInMonth?: number;\n  basicSalary: number;\n  totalWorkHours: number;\n  salaryPerHour: number;\n  sundayDays: number;\n  phDays: number;\n  sundayAmount: number;\n  phAmount: number;\n  bonus: number;\n  incentive: number;\n  pfDeduction: number;\n  esiDeduction: number;\n}\n\n// ── Animated Counter ──\nfunction AnimatedCounter({ value, prefix = '', suffix = '', decimals = 0 }: {\n  value: number; prefix?: string; suffix?: string; decimals?: number;\n}) {\n  const [display, setDisplay] = useState(0);\n  useEffect(() => {\n    const duration = 1000;\n    const startTime = Date.now();\n    const step = () => {\n      const elapsed = Date.now() - startTime;\n      const progress = Math.min(elapsed / duration, 1);\n      const eased = 1 - Math.pow(1 - progress, 3);\n      setDisplay(value * eased);\n      if (progress < 1) requestAnimationFrame(step);\n    };\n    requestAnimationFrame(step);\n  }, [value]);\n\n  if (decimals > 0) {\n    return <span>{prefix}{display.toFixed(decimals)}{suffix}</span>;\n  }\n  return <span>{prefix}{Math.round(display).toLocaleString('en-IN')}{suffix}</span>;\n}\n\n// ── Status Badge ──\nfunction PayrollStatusBadge({ status }: { status: string }) {\n  const config: Record<string, { bg: string; text: string; label: string }> = {\n    generated: { bg: 'bg-cyan-500/15 border-cyan-500/20', text: 'text-cyan-600 dark:text-cyan-400', label: 'Generated' },\n    approved: { bg: 'bg-emerald-500/15 border-emerald-500/20', text: 'text-emerald-600 dark:text-emerald-400', label: 'Approved' },\n    paid: { bg: 'bg-green-500/15 border-green-500/20', text: 'text-green-600 dark:text-green-400', label: 'Paid' },\n  };\n  const s = config[status] || { bg: 'bg-muted border-border', text: 'text-muted-foreground', label: status };\n  return (\n    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border whitespace-nowrap shrink-0 ${s.bg} ${s.text}`}>\n      {s.label}\n    </span>\n  );\n}\n\n// ── Firm Badge ──\nfunction FirmBadge({ firm }: { firm: string }) {\n  return <span className={`${FIRM_BADGE_CLASS[firm] || 'firm-badge-lapl'} whitespace-nowrap shrink-0`}>{firm}</span>;\n}\n\nexport function PayrollAutomation() {\n  const [payrolls, setPayrolls] = useState<PayrollRecord[]>([]);\n  const [employees, setEmployees] = useState<{ employeeId: string; fullName: string; department: string; salaryType: string; basicSalary: number; shiftHours: number }[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [open, setOpen] = useState(false);\n  const [generatingAll, setGeneratingAll] = useState(false);\n  const [exporting, setExporting] = useState(false);\n  const [masterFirm, setMasterFirm] = useState('all');\n\n  // ── Advance Form ──\n  const [advanceOpen, setAdvanceOpen] = useState(false);\n  const [advanceForm, setAdvanceForm] = useState({\n    employeeId: '',\n    amount: '',\n    reason: '',\n    date: new Date().toISOString().split('T')[0],\n  });\n  const [advanceSearch, setAdvanceSearch] = useState('');\n  const [advances, setAdvances] = useState<any[]>([]);\n  const [addingAdvance, setAddingAdvance] = useState(false);\n\n  // ── Form for Generate One ──\n  const [form, setForm] = useState({\n    employeeId: '',\n    bonus: 0,\n    incentive: 0,\n    tdsDeduction: 0,\n    loanDeduction: 0,\n    advanceDeduction: 0,\n    securityDeposit: 0,\n    arrear: 0,\n  });\n  const [employeeSearch, setEmployeeSearch] = useState('');\n\n  // ── Filters ──\n  const now = new Date();\n  const [filterMonth, setFilterMonth] = useState(String(now.getMonth() + 1));\n  const [filterYear, setFilterYear] = useState(String(now.getFullYear()));\n  const [filterFirm, setFilterFirm] = useState('all');\n  const [searchEmployee, setSearchEmployee] = useState('');\n\n  const { setCurrentPage, setSelectedEmployeeId } = useHRMSStore();\n\n  // ── Load data ──\n  const loadData = useCallback(async () => {\n    setLoading(true);\n    try {\n      const params = new URLSearchParams();\n      params.set('month', filterMonth);\n      params.set('year', filterYear);\n      if (filterFirm !== 'all') params.set('firm', filterFirm);\n\n      const [payRes, empRes] = await Promise.all([\n        fetch(`/api/payroll?${params}`),\n        fetch('/api/employees?status=Yes'),\n      ]);\n      setPayrolls(await payRes.json());\n      const empData = await empRes.json();\n      setEmployees(empData.map((e: any) => ({\n        employeeId: e.employeeId,\n        fullName: e.fullName,\n        department: e.department,\n        salaryType: e.salaryType,\n        basicSalary: e.basicSalary || e.monthlySalary,\n        shiftHours: e.shiftHours,\n      })));\n    } catch {\n      toast.error('Failed to load payroll data');\n    }\n    setLoading(false);\n  }, [filterMonth, filterYear, filterFirm]);\n\n  useEffect(() => { loadData(); }, [loadData]);\n\n  // ── Summary calculations ──\n  const totalGross = payrolls.reduce((s, p) => s + p.grossSalary, 0);\n  const totalDeductions = payrolls.reduce((s, p) => s + p.totalDeductions, 0);\n  const totalNet = payrolls.reduce((s, p) => s + p.netSalary, 0);\n  const totalOTHours = payrolls.reduce((s, p) => s + (p.otHours || 0), 0);\n  const totalArrears = payrolls.reduce((s, p) => s + (p.arrear || 0), 0);\n\n  // ── Filtered records ──\n  const filteredRecords = useMemo(() => {\n    if (!searchEmployee) return payrolls;\n    const q = searchEmployee.toLowerCase();\n    return payrolls.filter((p) =>\n      p.employee?.fullName?.toLowerCase().includes(q) ||\n      p.employeeId.toLowerCase().includes(q)\n    );\n  }, [payrolls, searchEmployee]);\n\n  // ── Selected employee preview ──\n  const selectedEmp = useMemo(() => {\n    return employees.find((e) => e.employeeId === form.employeeId);\n  }, [employees, form.employeeId]);\n\n  // ── Salary preview calculation ──\n  // Gross = baseSalary + sundayEarnings + OT\n  // Net = grossSalary + bonus + incentive + arrear − totalDeductions\n  const salaryPreview = useMemo(() => {\n    if (!selectedEmp) return null;\n    const existing = payrolls.find((p) => p.employeeId === form.employeeId);\n    if (!existing) return null;\n\n    const daysInMonth = existing.daysInMonth || new Date(parseInt(filterYear), parseInt(filterMonth), 0).getDate();\n    const perDayRate = existing.perDayRate || (existing.monthlySalary / daysInMonth);\n    const earnedDays = (existing.presentDays || 0) + (existing.paidLeaves || 0);\n    const baseSalary = existing.baseSalary != null\n      ? existing.baseSalary\n      : Math.round((perDayRate * earnedDays) * 100) / 100;\n\n    // Sunday Earnings (paid weekly off)\n    const sundayEarnings = existing.sundayEarnings || 0;\n\n    // Gross includes baseSalary + sundayEarnings + OT\n    const grossSalary = existing.grossSalary;\n\n    // Deductions\n    const totalDeductions = Math.round((form.tdsDeduction + form.loanDeduction + form.advanceDeduction + form.securityDeposit) * 100) / 100;\n\n    // Net = grossSalary + bonus + incentive + arrear − totalDeductions\n    const net = Math.round((grossSalary + form.bonus + form.incentive + form.arrear - totalDeductions) * 100) / 100;\n\n    return {\n      baseSalary: Math.round(baseSalary * 100) / 100,\n      sundayEarnings,\n      grossSalary: Math.round(grossSalary * 100) / 100,\n      bonus: form.bonus,\n      incentive: form.incentive,\n      arrear: form.arrear,\n      deductions: totalDeductions,\n      net,\n    };\n  }, [selectedEmp, form, payrolls, filterMonth, filterYear]);\n\n  // ── Generate One ──\n  const handleGenerateOne = async () => {\n    if (!form.employeeId) { toast.error('Please select an employee'); return; }\n    try {\n      const res = await fetch('/api/payroll', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          employeeId: form.employeeId,\n          month: parseInt(filterMonth),\n          year: parseInt(filterYear),\n          bonus: form.bonus || 0,\n          incentive: form.incentive || 0,\n          tdsDeduction: form.tdsDeduction || 0,\n          loanDeduction: form.loanDeduction || 0,\n          advanceDeduction: form.advanceDeduction || 0,\n          securityDeposit: form.securityDeposit || 0,\n          arrear: form.arrear || 0,\n        }),\n      });\n      if (!res.ok) throw new Error('Failed to generate payroll');\n      toast.success('Payroll generated successfully');\n      setOpen(false);\n      setForm({ employeeId: '', bonus: 0, incentive: 0, tdsDeduction: 0, loanDeduction: 0, advanceDeduction: 0, securityDeposit: 0, arrear: 0 });\n      setEmployeeSearch('');\n      loadData();\n    } catch {\n      toast.error('Failed to generate payroll');\n    }\n  };\n\n  // ── Generate All ──\n  const handleGenerateAll = async () => {\n    setGeneratingAll(true);\n    try {\n      const body: any = { month: parseInt(filterMonth), year: parseInt(filterYear) };\n      if (filterFirm !== 'all') body.firm = filterFirm;\n      const res = await fetch('/api/payroll/generate-all', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(body),\n      });\n      const data = await res.json();\n      toast.success(`Payroll generated for ${data.successCount || data.generated || 0} employees`);\n      loadData();\n    } catch {\n      toast.error('Failed to generate payroll for all employees');\n    }\n    setGeneratingAll(false);\n  };\n\n  // ── Filtered employees for the dialog ──\n  const filteredEmployees = useMemo(() => {\n    if (!employeeSearch) return employees;\n    const q = employeeSearch.toLowerCase();\n    return employees.filter((e) =>\n      e.fullName.toLowerCase().includes(q) || e.employeeId.toLowerCase().includes(q)\n    );\n  }, [employees, employeeSearch]);\n\n  // ── Export Master Excel Sheet — via server-side API with firm-wise sheets ──\n  const handleExportSheet = async () => {\n    setExporting(true);\n    try {\n      const params = new URLSearchParams();\n      params.set('month', filterMonth);\n      params.set('year', filterYear);\n      if (masterFirm && masterFirm !== 'all') params.set('firm', masterFirm);\n\n      const res = await fetch(`/api/attendance/export-master?${params}`);\n      if (!res.ok) {\n        const errData = await res.json().catch(() => ({}));\n        toast.error(errData.error || 'Master sheet export failed');\n        setExporting(false);\n        return;\n      }\n      const blob = await res.blob();\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = `Master_Sheet_${MONTHS[parseInt(filterMonth) - 1]}_${filterYear}.xlsx`;\n      document.body.appendChild(a);\n      a.click();\n      document.body.removeChild(a);\n      window.URL.revokeObjectURL(url);\n      toast.success('Master Excel Sheet downloaded successfully!');\n    } catch (err) {\n      console.error('Master sheet export error:', err);\n      toast.error('Export failed. Please try again.');\n    }\n    setExporting(false);\n  };\n\n  // ── Load advances ──\n  const loadAdvances = useCallback(async () => {\n    try {\n      const params = new URLSearchParams();\n      params.set('month', filterMonth);\n      params.set('year', filterYear);\n      const res = await fetch(`/api/advances?${params}`);\n      if (res.ok) {\n        const data = await res.json();\n        setAdvances(data);\n      }\n    } catch {}\n  }, [filterMonth, filterYear]);\n\n  useEffect(() => { loadAdvances(); }, [loadAdvances]);\n\n  // ── Add Advance ──\n  const handleAddAdvance = async () => {\n    if (!advanceForm.employeeId || !advanceForm.amount || !advanceForm.reason) {\n      toast.error('Please fill employee, amount, and reason');\n      return;\n    }\n    setAddingAdvance(true);\n    try {\n      const res = await fetch('/api/advances', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          employeeId: advanceForm.employeeId,\n          amount: advanceForm.amount,\n          reason: advanceForm.reason,\n          date: advanceForm.date,\n          month: parseInt(filterMonth),\n          year: parseInt(filterYear),\n        }),\n      });\n      if (!res.ok) throw new Error('Failed to add advance');\n      toast.success('Advance added successfully! It will reflect in payroll.');\n      setAdvanceOpen(false);\n      setAdvanceForm({ employeeId: '', amount: '', reason: '', date: new Date().toISOString().split('T')[0] });\n      setAdvanceSearch('');\n      loadAdvances();\n      loadData();\n    } catch {\n      toast.error('Failed to add advance');\n    }\n    setAddingAdvance(false);\n  };\n\n  // ── Delete Advance ──\n  const handleDeleteAdvance = async (id: string) => {\n    try {\n      const res = await fetch(`/api/advances/${id}`, { method: 'DELETE' });\n      if (!res.ok) throw new Error('Failed');\n      toast.success('Advance deleted');\n      loadAdvances();\n      loadData();\n    } catch {\n      toast.error('Failed to delete advance');\n    }\n  };\n\n  // ── Selected advance employee ──\n  const selectedAdvEmp = useMemo(() => {\n    return employees.find((e) => e.employeeId === advanceForm.employeeId);\n  }, [employees, advanceForm.employeeId]);\n\n  // ── Filtered employees for advance dialog ──\n  const filteredAdvEmployees = useMemo(() => {\n    if (!advanceSearch) return employees;\n    const q = advanceSearch.toLowerCase();\n    return employees.filter((e) =>\n      e.fullName.toLowerCase().includes(q) || e.employeeId.toLowerCase().includes(q)\n    );\n  }, [employees, advanceSearch]);\n\n  // ── Summary cards ──\n  const statCards = [\n    {\n      title: 'Total Gross Salary',\n      value: totalGross,\n      icon: IndianRupee,\n      gradient: 'gradient-info',\n      color: 'text-cyan-500',\n      prefix: '₹',\n      format: 'currency',\n    },\n    {\n      title: 'Total OT Hours',\n      value: totalOTHours,\n      icon: Clock,\n      gradient: 'gradient-warning',\n      color: 'text-cyan-500',\n      isHours: true,\n    },\n    {\n      title: 'Total Deductions',\n      value: totalDeductions,\n      icon: TrendingDown,\n      gradient: 'gradient-danger',\n      color: 'text-red-500',\n      prefix: '₹',\n      format: 'currency',\n    },\n    {\n      title: 'Net Payroll',\n      value: totalNet,\n      icon: DollarSign,\n      gradient: 'gradient-success',\n      color: 'text-gold',\n      prefix: '₹',\n      format: 'currency',\n    },\n    {\n      title: 'Employees Processed',\n      value: payrolls.length,\n      icon: Users,\n      gradient: 'gradient-warning',\n      color: 'text-amber-500',\n    },\n  ];\n\n  return (\n    <div className=\"space-y-4\">\n      {/* ── Header ── */}\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\"\n      >\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <IndianRupee className=\"w-5 h-5 text-gold\" />\n            Payroll Automation\n          </h2>\n          <p className=\"text-sm text-muted-foreground\">\n            Hourly Rate = Monthly Salary ÷ (Days in Month × 9) | Sundays are paid weekly off\n          </p>\n        </div>\n        <div className=\"flex gap-2 flex-wrap\">\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            className=\"gap-1.5\"\n            onClick={() => setOpen(true)}\n          >\n            <DollarSign className=\"w-4 h-4\" /> Generate One\n          </Button>\n          <Button\n            className=\"gradient-laxree text-white gap-1.5\"\n            size=\"sm\"\n            onClick={handleGenerateAll}\n            disabled={generatingAll}\n          >\n            <Zap className=\"w-4 h-4\" /> {generatingAll ? 'Generating...' : 'Generate All'}\n          </Button>\n          <div className=\"flex items-center gap-2\">\n            <Select value={masterFirm} onValueChange={setMasterFirm}>\n              <SelectTrigger className=\"w-36 h-9 text-xs\">\n                <Building2 className=\"w-3.5 h-3.5 mr-1 text-muted-foreground\" />\n                <SelectValue placeholder=\"All Firms\" />\n              </SelectTrigger>\n              <SelectContent>\n                <SelectItem value=\"all\">All Firms</SelectItem>\n                {FIRMS.map((f) => (\n                  <SelectItem key={f} value={f}>{f}</SelectItem>\n                ))}\n              </SelectContent>\n            </Select>\n            <Button\n              variant=\"outline\"\n              size=\"sm\"\n              className=\"gap-1.5\"\n              onClick={handleExportSheet}\n              disabled={exporting}\n            >\n              {exporting ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <FileText className=\"w-4 h-4\" />}\n              {exporting ? 'Exporting...' : 'Master Excel Sheet'}\n            </Button>\n          </div>\n          <Button\n            variant=\"outline\"\n            size=\"sm\"\n            className=\"gap-1.5 border-amber-500/30 text-amber-600 hover:bg-amber-500/10\"\n            onClick={() => setAdvanceOpen(true)}\n          >\n            <IndianRupee className=\"w-4 h-4\" /> Add Advance\n          </Button>\n        </div>\n      </motion.div>\n\n      {/* ── Month/Year Selector + Firm Filter ── */}\n      <motion.div\n        initial={{ opacity: 0, y: -5 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.1 }}\n        className=\"glass-card p-3\"\n      >\n        <div className=\"flex flex-col sm:flex-row gap-3 flex-wrap\">\n          <Select value={filterMonth} onValueChange={setFilterMonth}>\n            <SelectTrigger className=\"w-full sm:w-36 h-9\">\n              <CalendarDays className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n              <SelectValue />\n            </SelectTrigger>\n            <SelectContent>\n              {MONTHS.map((m, i) => (\n                <SelectItem key={i + 1} value={String(i + 1)}>{m}</SelectItem>\n              ))}\n            </SelectContent>\n          </Select>\n          <Select value={filterYear} onValueChange={setFilterYear}>\n            <SelectTrigger className=\"w-full sm:w-24 h-9\">\n              <SelectValue />\n            </SelectTrigger>\n            <SelectContent>\n              {[2024, 2025, 2026, 2027].map((y) => (\n                <SelectItem key={y} value={String(y)}>{y}</SelectItem>\n              ))}\n            </SelectContent>\n          </Select>\n          <Select value={filterFirm} onValueChange={setFilterFirm}>\n            <SelectTrigger className=\"w-full sm:w-36 h-9\">\n              <Building2 className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n              <SelectValue placeholder=\"All Firms\" />\n            </SelectTrigger>\n            <SelectContent>\n              <SelectItem value=\"all\">All Firms</SelectItem>\n              {FIRMS.map((f) => (\n                <SelectItem key={f} value={f}>{f}</SelectItem>\n              ))}\n            </SelectContent>\n          </Select>\n          <div className=\"relative flex-1\">\n            <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n            <Input\n              className=\"pl-9 h-9\"\n              placeholder=\"Search employee...\"\n              value={searchEmployee}\n              onChange={(e) => setSearchEmployee(e.target.value)}\n            />\n          </div>\n        </div>\n      </motion.div>\n\n      {/* ── Summary Cards ── */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3\">\n        {statCards.map((card, i) => {\n          const Icon = card.icon;\n          return (\n            <motion.div\n              key={card.title}\n              initial={{ opacity: 0, y: 10 }}\n              animate={{ opacity: 1, y: 0 }}\n              transition={{ delay: i * 0.05 }}\n              className=\"kpi-card\"\n            >\n              <Card className=\"border-0 shadow-none bg-transparent\">\n                <CardContent className=\"p-4 flex items-center gap-3\">\n                  <div className={`w-10 h-10 rounded-xl ${card.gradient} flex items-center justify-center shrink-0 shadow-lg`}>\n                    <Icon className=\"w-5 h-5 text-white\" />\n                  </div>\n                  <div>\n                    <p className=\"text-xs text-muted-foreground font-medium truncate\">{card.title}</p>\n                    <p className=\"text-xl font-bold\">\n                      {card.format === 'currency' ? (\n                        <AnimatedCounter value={card.value} prefix=\"₹\" decimals={0} />\n                      ) : card.isHours ? (\n                        <span>{formatOT(card.value)}</span>\n                      ) : (\n                        <AnimatedCounter value={card.value} suffix={'suffix' in card ? (card as any).suffix : ''} decimals={'decimals' in card ? (card as any).decimals : 0} />\n                      )}\n                    </p>\n                  </div>\n                </CardContent>\n              </Card>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      {/* ── Salary Breakdown Info Card ── */}\n      <motion.div\n        initial={{ opacity: 0, y: 5 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.2 }}\n        className=\"glass-card p-4\"\n      >\n        <div className=\"flex items-start gap-3\">\n          <div className=\"w-9 h-9 rounded-lg bg-gold/10 flex items-center justify-center shrink-0\">\n            <Info className=\"w-4.5 h-4.5 text-gold\" />\n          </div>\n          <div className=\"space-y-1.5\">\n            <p className=\"text-sm font-semibold\">Laxree Payroll Formula</p>\n            <div className=\"space-y-1 text-xs text-muted-foreground\">\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Rate</Badge>\n                <span>Per Day Rate = Monthly Salary ÷ Days in Month (31, 30, or 28)</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Hourly</Badge>\n                <span>Hourly Rate = Monthly Salary ÷ (Days in Month × 9)</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Base</Badge>\n                <span>Base Salary = Per Day Rate × Earned Days (Late/Early-Out deducted by actual hours)</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Sunday</Badge>\n                <span>Sunday Earnings = Per Day Rate × Sunday Count (e.g., 5 Sun × 9 = 45 hrs earned)</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">OT</Badge>\n                <span>OT Amount = OT Hours × Hourly Rate (1x normal rate, NOT 1.5x)</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Gross</Badge>\n                <span>Gross = Base Salary + Sunday Earnings + OT Amount</span>\n              </p>\n              <p className=\"flex items-center gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5\">Net</Badge>\n                <span>Net = Gross + Bonus + Incentive + Arrear − Total Deductions</span>\n              </p>\n            </div>\n            <p className=\"text-[10px] text-muted-foreground\">\n              Full attendance = Full monthly salary + OT &nbsp;|&nbsp; Sundays are paid weekly off &nbsp;|&nbsp; Late/Early-Out: pay deducted based on actual hours worked\n            </p>\n          </div>\n        </div>\n      </motion.div>\n\n      {/* ── Payroll Table ── */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.25 }}\n      >\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardContent className=\"p-0\">\n            <div className=\"overflow-auto max-h-[65vh]\" style={{ WebkitOverflowScrolling: 'touch' }}>\n              <Table>\n                <TableHeader>\n                  <TableRow className=\"hover:bg-transparent\">\n                    <TableHead>Employee</TableHead>\n                    <TableHead className=\"hidden md:table-cell\">Firm</TableHead>\n                    <TableHead className=\"hidden lg:table-cell\">Worked Hrs</TableHead>\n                    <TableHead className=\"hidden xl:table-cell\">Hourly Rate</TableHead>\n                    <TableHead className=\"hidden lg:table-cell\">OT Hrs</TableHead>\n                    <TableHead className=\"hidden sm:table-cell\">OT Amount</TableHead>\n                    <TableHead className=\"hidden lg:table-cell\">Earn Sunday</TableHead>\n\n                    <TableHead>Gross</TableHead>\n                    <TableHead className=\"hidden md:table-cell\">Deductions</TableHead>\n                    <TableHead className=\"hidden xl:table-cell\">Arrear</TableHead>\n                    <TableHead>Net Salary</TableHead>\n                    <TableHead>Status</TableHead>\n                  </TableRow>\n                </TableHeader>\n                <TableBody>\n                  {loading ? (\n                    Array.from({ length: 5 }).map((_, i) => (\n                      <TableRow key={i}>\n                        {Array.from({ length: 12 }).map((_, j) => (\n                          <TableCell key={j}>\n                            <div className=\"h-4 bg-muted/50 rounded animate-pulse\" />\n                          </TableCell>\n                        ))}\n                      </TableRow>\n                    ))\n                  ) : filteredRecords.length === 0 ? (\n                    <TableRow>\n                      <TableCell colSpan={12} className=\"text-center py-12 text-muted-foreground\">\n                        <FileText className=\"w-8 h-8 mx-auto mb-2 opacity-30\" />\n                        <p>No payroll records for this period.</p>\n                        <p className=\"text-xs mt-1\">Click &quot;Generate All&quot; to create payroll records.</p>\n                      </TableCell>\n                    </TableRow>\n                  ) : (\n                    filteredRecords.map((p, idx) => (\n                      <TableRow\n                        key={p.id}\n                        className=\"hover:bg-muted/30 cursor-pointer transition-colors\"\n                        onClick={() => {\n                          setSelectedEmployeeId(p.employeeId);\n                          setCurrentPage('salary-slip');\n                        }}\n                      >\n                        <TableCell>\n                          <motion.div\n                            className=\"flex items-center gap-2\"\n                            initial={{ opacity: 0, x: -8 }}\n                            animate={{ opacity: 1, x: 0 }}\n                            transition={{ delay: idx * 0.02 }}\n                          >\n                            <div className=\"w-7 h-7 rounded-full gradient-laxree flex items-center justify-center text-white text-[10px] font-bold shrink-0\">\n                              {p.employee?.fullName?.charAt(0) || '?'}\n                            </div>\n                            <div className=\"min-w-0 overflow-hidden\">\n                              <p className=\"text-sm font-medium truncate\">{p.employee?.fullName || p.employeeId}</p>\n                              <p className=\"text-[10px] text-muted-foreground font-mono whitespace-nowrap\">{p.employeeId}</p>\n                            </div>\n                          </motion.div>\n                        </TableCell>\n                        <TableCell className=\"hidden md:table-cell\">\n                          <FirmBadge firm={getFirmFromEmployeeId(p.employeeId) || p.employee?.department || ''} />\n                        </TableCell>\n                        <TableCell className=\"hidden lg:table-cell text-sm whitespace-nowrap\">\n                          {(p.totalWorkedHrs || p.totalWorkHours || 0) > 0 ? `${displayHHMM(p.totalWorkedHrs || p.totalWorkHours || 0)}h` : '—'}\n                        </TableCell>\n                        <TableCell className=\"hidden xl:table-cell text-sm font-mono whitespace-nowrap\">\n                          {(p.hourlyRate || p.salaryPerHour || 0) > 0 ? `₹${p.hourlyRate || p.salaryPerHour}` : '—'}\n                        </TableCell>\n                        <TableCell className=\"hidden lg:table-cell text-sm whitespace-nowrap\">\n                          {(p.otHours || 0) > 0 ? (\n                            <span className=\"text-cyan-600 dark:text-cyan-400 font-medium\">{displayHHMM(p.otHours)}h</span>\n                          ) : '—'}\n                        </TableCell>\n                        <TableCell className=\"hidden sm:table-cell text-sm whitespace-nowrap\">\n                          {(p.otAmount || 0) > 0 ? (\n                            <span className=\"text-cyan-600 dark:text-cyan-400\">₹{p.otAmount.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</span>\n                          ) : '—'}\n                        </TableCell>\n                        <TableCell className=\"hidden lg:table-cell text-sm whitespace-nowrap\">\n                          {(p.sundayCount || 0) > 0 ? (\n                            <div className=\"flex flex-col\">\n                              <span className=\"text-blue-600 dark:text-blue-400 font-medium\">{p.sundayCount} Sun × 9 = {p.earnedSundayHrs || p.sundayCount * 9}h</span>\n                              <span className=\"text-[10px] text-muted-foreground\">₹{(p.sundayEarnings || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}</span>\n                            </div>\n                          ) : '—'}\n                        </TableCell>\n\n                        <TableCell className=\"text-sm whitespace-nowrap\">\n                          ₹{p.grossSalary.toLocaleString('en-IN', { maximumFractionDigits: 0 })}\n                        </TableCell>\n                        <TableCell className=\"hidden md:table-cell text-sm text-red-500 whitespace-nowrap\">\n                          ₹{p.totalDeductions.toLocaleString('en-IN', { maximumFractionDigits: 0 })}\n                        </TableCell>\n                        <TableCell className=\"hidden xl:table-cell text-sm whitespace-nowrap\">\n                          {(p.arrear || 0) > 0 ? (\n                            <span className=\"text-amber-600 dark:text-amber-400\">₹{p.arrear.toLocaleString('en-IN', { maximumFractionDigits: 0 })}</span>\n                          ) : '—'}\n                        </TableCell>\n                        <TableCell className=\"text-sm font-bold text-gold whitespace-nowrap\">\n                          ₹{p.netSalary.toLocaleString('en-IN', { maximumFractionDigits: 0 })}\n                        </TableCell>\n                        <TableCell>\n                          <PayrollStatusBadge status={p.status} />\n                        </TableCell>\n                      </TableRow>\n                    ))\n                  )}\n                </TableBody>\n              </Table>\n            </div>\n          </CardContent>\n        </Card>\n      </motion.div>\n\n      {/* ── Generate One Dialog ── */}\n      <Dialog open={open} onOpenChange={(v) => {\n        setOpen(v);\n        if (!v) {\n          setForm({ employeeId: '', bonus: 0, incentive: 0, tdsDeduction: 0, loanDeduction: 0, advanceDeduction: 0, securityDeposit: 0, arrear: 0 });\n          setEmployeeSearch('');\n        }\n      }}>\n        <DialogContent className=\"max-w-lg max-h-[90vh] overflow-y-auto\">\n          <DialogHeader>\n            <DialogTitle className=\"flex items-center gap-2\">\n              <DollarSign className=\"w-5 h-5 text-gold\" />\n              Generate Payroll\n            </DialogTitle>\n          </DialogHeader>\n          <div className=\"space-y-4 py-4\">\n            {/* Employee Search */}\n            <div>\n              <Label>Employee *</Label>\n              <div className=\"space-y-2\">\n                <div className=\"relative\">\n                  <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n                  <Input\n                    className=\"pl-9\"\n                    placeholder=\"Search employee...\"\n                    value={employeeSearch}\n                    onChange={(e) => setEmployeeSearch(e.target.value)}\n                  />\n                </div>\n                {!form.employeeId ? (\n                  <div className=\"max-h-40 border rounded-lg overflow-y-auto\">\n                    <div className=\"p-1\">\n                      {filteredEmployees.slice(0, 20).map((e) => (\n                        <button\n                          key={e.employeeId}\n                          className=\"w-full text-left px-3 py-2 rounded-md hover:bg-muted/80 text-sm flex items-center justify-between transition-colors gap-2\"\n                          onClick={() => { setForm({ ...form, employeeId: e.employeeId }); setEmployeeSearch(''); }}\n                        >\n                          <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                            <FirmBadge firm={e.department} />\n                            <span className=\"truncate\">{e.fullName}</span>\n                          </div>\n                          <span className=\"text-xs text-muted-foreground font-mono whitespace-nowrap shrink-0\">{e.employeeId}</span>\n                        </button>\n                      ))}\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"flex items-center justify-between px-3 py-2 bg-muted/50 rounded-lg\">\n                    <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                      <FirmBadge firm={selectedEmp?.department || ''} />\n                      <span className=\"text-sm font-medium truncate\">{selectedEmp?.fullName}</span>\n                    </div>\n                    <div className=\"flex items-center gap-2\">\n                      <span className=\"text-xs font-mono text-muted-foreground\">{form.employeeId}</span>\n                      <Button variant=\"ghost\" size=\"sm\" className=\"h-6 text-xs\" onClick={() => setForm({ ...form, employeeId: '' })}>\n                        Change\n                      </Button>\n                    </div>\n                  </div>\n                )}\n              </div>\n            </div>\n\n            {/* Salary info for selected employee */}\n            {selectedEmp && (\n              <div className=\"flex items-center gap-2 p-2.5 rounded-lg bg-gold/5 border border-gold/10 text-xs\">\n                <Info className=\"w-3.5 h-3.5 text-gold shrink-0\" />\n                <span>\n                  <strong>{selectedEmp.salaryType}</strong> worker &middot; Monthly: ₹{selectedEmp.basicSalary.toLocaleString('en-IN')}\n                  {selectedEmp.salaryType === 'Hourly' && ` · Shift: ${displayHHMM(selectedEmp.shiftHours)}h`}\n                </span>\n              </div>\n            )}\n\n            {/* Earnings & Deductions */}\n            <div className=\"grid grid-cols-2 gap-3\">\n              <div>\n                <Label className=\"text-xs\">Bonus (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.bonus || ''}\n                  onChange={(e) => setForm({ ...form, bonus: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">Incentive (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.incentive || ''}\n                  onChange={(e) => setForm({ ...form, incentive: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">Arrear (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.arrear || ''}\n                  onChange={(e) => setForm({ ...form, arrear: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">TDS (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.tdsDeduction || ''}\n                  onChange={(e) => setForm({ ...form, tdsDeduction: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">Loan (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.loanDeduction || ''}\n                  onChange={(e) => setForm({ ...form, loanDeduction: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">Advance (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.advanceDeduction || ''}\n                  onChange={(e) => setForm({ ...form, advanceDeduction: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n              <div>\n                <Label className=\"text-xs\">Security Deposit (₹)</Label>\n                <Input\n                  type=\"number\"\n                  value={form.securityDeposit || ''}\n                  onChange={(e) => setForm({ ...form, securityDeposit: Number(e.target.value) || 0 })}\n                  placeholder=\"0\"\n                />\n              </div>\n            </div>\n\n            {/* Salary Preview */}\n            {salaryPreview && (\n              <div className=\"p-3 rounded-lg bg-muted/50 border space-y-1.5\">\n                <p className=\"text-xs font-semibold text-muted-foreground\">Calculated Salary Preview</p>\n                <div className=\"grid grid-cols-4 sm:grid-cols-7 gap-2 text-center\">\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Base Salary</p>\n                    <p className=\"text-sm font-bold text-cyan-600 dark:text-cyan-400\">₹{salaryPreview.baseSalary.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Gross</p>\n                    <p className=\"text-sm font-bold text-cyan-600 dark:text-cyan-400\">₹{salaryPreview.grossSalary.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Bonus</p>\n                    <p className=\"text-sm font-bold text-emerald-600 dark:text-emerald-400\">₹{salaryPreview.bonus.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Incentive</p>\n                    <p className=\"text-sm font-bold text-emerald-600 dark:text-emerald-400\">₹{salaryPreview.incentive.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Arrear</p>\n                    <p className=\"text-sm font-bold text-amber-600 dark:text-amber-400\">₹{salaryPreview.arrear.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Deductions</p>\n                    <p className=\"text-sm font-bold text-red-500\">₹{salaryPreview.deductions.toLocaleString('en-IN')}</p>\n                  </div>\n                  <div>\n                    <p className=\"text-[10px] text-muted-foreground\">Net Salary</p>\n                    <p className=\"text-sm font-bold text-gold\">₹{salaryPreview.net.toLocaleString('en-IN')}</p>\n                  </div>\n                </div>\n                <p className=\"text-[9px] text-muted-foreground text-center\">Base = Monthly − (PerDay × Absent) | PerDay = Monthly ÷ Days in Month | OT = OT Hrs × Hourly Rate (1x) | Net = Gross + Bonus + Incentive + Arrear − Deductions</p>\n              </div>\n            )}\n\n            <Button className=\"w-full gradient-laxree text-white\" onClick={handleGenerateOne}>\n              Generate Payroll\n            </Button>\n          </div>\n        </DialogContent>\n      </Dialog>\n\n      {/* ── Add Advance Dialog ── */}\n      <Dialog open={advanceOpen} onOpenChange={(v) => {\n        setAdvanceOpen(v);\n        if (!v) {\n          setAdvanceForm({ employeeId: '', amount: '', reason: '', date: new Date().toISOString().split('T')[0] });\n          setAdvanceSearch('');\n        }\n      }}>\n        <DialogContent className=\"max-w-md max-h-[90vh] overflow-y-auto\">\n          <DialogHeader>\n            <DialogTitle className=\"flex items-center gap-2\">\n              <IndianRupee className=\"w-5 h-5 text-amber-500\" />\n              Add Advance\n            </DialogTitle>\n          </DialogHeader>\n          <div className=\"space-y-4 py-4\">\n            {/* Employee Search */}\n            <div>\n              <Label>Select Employee *</Label>\n              <div className=\"space-y-2\">\n                <div className=\"relative\">\n                  <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n                  <Input\n                    className=\"pl-9\"\n                    placeholder=\"Search employee...\"\n                    value={advanceSearch}\n                    onChange={(e) => setAdvanceSearch(e.target.value)}\n                  />\n                </div>\n                {!advanceForm.employeeId ? (\n                  <div className=\"max-h-40 border rounded-lg overflow-y-auto\">\n                    <div className=\"p-1\">\n                      {filteredAdvEmployees.slice(0, 20).map((e) => (\n                        <button\n                          key={e.employeeId}\n                          className=\"w-full text-left px-3 py-2 rounded-md hover:bg-muted/80 text-sm flex items-center justify-between transition-colors gap-2\"\n                          onClick={() => { setAdvanceForm({ ...advanceForm, employeeId: e.employeeId }); setAdvanceSearch(''); }}\n                        >\n                          <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                            <FirmBadge firm={e.department} />\n                            <span className=\"truncate\">{e.fullName}</span>\n                          </div>\n                          <span className=\"text-xs text-muted-foreground font-mono whitespace-nowrap shrink-0\">{e.employeeId}</span>\n                        </button>\n                      ))}\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"flex items-center justify-between px-3 py-2 bg-muted/50 rounded-lg\">\n                    <div className=\"flex items-center gap-2 min-w-0 overflow-hidden\">\n                      <FirmBadge firm={selectedAdvEmp?.department || ''} />\n                      <span className=\"text-sm font-medium truncate\">{selectedAdvEmp?.fullName}</span>\n                    </div>\n                    <div className=\"flex items-center gap-2\">\n                      <span className=\"text-xs font-mono text-muted-foreground\">{advanceForm.employeeId}</span>\n                      <Button variant=\"ghost\" size=\"sm\" className=\"h-6 text-xs\" onClick={() => setAdvanceForm({ ...advanceForm, employeeId: '' })}>\n                        Change\n                      </Button>\n                    </div>\n                  </div>\n                )}\n              </div>\n            </div>\n\n            {/* Amount */}\n            <div>\n              <Label>Advance Amount (₹) *</Label>\n              <Input\n                type=\"number\"\n                value={advanceForm.amount}\n                onChange={(e) => setAdvanceForm({ ...advanceForm, amount: e.target.value })}\n                placeholder=\"Enter amount\"\n              />\n            </div>\n\n            {/* Reason */}\n            <div>\n              <Label>Reason *</Label>\n              <Input\n                value={advanceForm.reason}\n                onChange={(e) => setAdvanceForm({ ...advanceForm, reason: e.target.value })}\n                placeholder=\"Reason for advance\"\n              />\n            </div>\n\n            {/* Date */}\n            <div>\n              <Label>Date</Label>\n              <Input\n                type=\"date\"\n                value={advanceForm.date}\n                onChange={(e) => setAdvanceForm({ ...advanceForm, date: e.target.value })}\n              />\n            </div>\n\n            <Button\n              className=\"w-full gradient-laxree text-white\"\n              onClick={handleAddAdvance}\n              disabled={addingAdvance}\n            >\n              {addingAdvance ? <Loader2 className=\"w-4 h-4 animate-spin mr-2\" /> : null}\n              {addingAdvance ? 'Adding...' : 'Add Advance'}\n            </Button>\n          </div>\n        </DialogContent>\n      </Dialog>\n\n      {/* ── Advances List ── */}\n      {advances.length > 0 && (\n        <motion.div\n          initial={{ opacity: 0, y: 10 }}\n          animate={{ opacity: 1, y: 0 }}\n          transition={{ delay: 0.3 }}\n        >\n          <Card className=\"glass-card border-0\">\n            <CardContent className=\"p-0\">\n              <div className=\"px-4 py-3 border-b border-amber-500/10 bg-amber-500/5\">\n                <h3 className=\"text-sm font-bold flex items-center gap-2 text-amber-600\">\n                  <IndianRupee className=\"w-4 h-4\" />\n                  Advances Taken — {MONTHS[parseInt(filterMonth) - 1]} {filterYear}\n                </h3>\n              </div>\n              <ScrollArea className=\"max-h-[30vh]\">\n                <Table>\n                  <TableHeader>\n                    <TableRow className=\"hover:bg-transparent\">\n                      <TableHead>Employee</TableHead>\n                      <TableHead>Amount</TableHead>\n                      <TableHead>Reason</TableHead>\n                      <TableHead>Date</TableHead>\n                      <TableHead className=\"w-10\"></TableHead>\n                    </TableRow>\n                  </TableHeader>\n                  <TableBody>\n                    {advances.map((adv: any) => (\n                      <TableRow key={adv.id} className=\"hover:bg-muted/30\">\n                        <TableCell>\n                          <div className=\"flex items-center gap-2\">\n                            <div className=\"w-6 h-6 rounded-full gradient-laxree flex items-center justify-center text-white text-[9px] font-bold shrink-0\">\n                              {adv.employee?.fullName?.charAt(0) || '?'}\n                            </div>\n                            <div className=\"min-w-0\">\n                              <p className=\"text-sm font-medium truncate\">{adv.employee?.fullName || adv.employeeId}</p>\n                              <p className=\"text-[10px] text-muted-foreground font-mono\">{adv.employeeId}</p>\n                            </div>\n                          </div>\n                        </TableCell>\n                        <TableCell className=\"text-sm font-bold text-amber-600 whitespace-nowrap\">\n                          ₹{Number(adv.amount).toLocaleString('en-IN')}\n                        </TableCell>\n                        <TableCell className=\"text-sm text-muted-foreground max-w-[200px] truncate\">\n                          {adv.reason}\n                        </TableCell>\n                        <TableCell className=\"text-xs text-muted-foreground whitespace-nowrap\">\n                          {new Date(adv.date).toLocaleDateString('en-IN')}\n                        </TableCell>\n                        <TableCell>\n                          <Button\n                            variant=\"ghost\"\n                            size=\"sm\"\n                            className=\"h-7 w-7 p-0 text-red-500 hover:text-red-700 hover:bg-red-500/10\"\n                            onClick={() => handleDeleteAdvance(adv.id)}\n                          >\n                            ×\n                          </Button>\n                        </TableCell>\n                      </TableRow>\n                    ))}\n                  </TableBody>\n                </Table>\n              </ScrollArea>\n            </CardContent>\n          </Card>\n        </motion.div>\n      )}\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback } from 'react';\nimport { CalendarDays, Check, X, Clock, RefreshCw } from 'lucide-react';\nimport { Card, CardContent } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Input } from '@/components/ui/input';\nimport { Label } from '@/components/ui/label';\nimport { Badge } from '@/components/ui/badge';\nimport { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';\nimport { ScrollArea } from '@/components/ui/scroll-area';\nimport { toast } from 'sonner';\nimport { motion } from 'framer-motion';\n\ninterface LeaveRequest {\n  id: string;\n  employeeId: string;\n  type: string;\n  startDate: string;\n  endDate: string;\n  days: number;\n  reason: string | null;\n  status: string;\n  employee?: { fullName: string; employeeId: string; department: string };\n}\n\nexport function LeaveManagement() {\n  const [leaves, setLeaves] = useState<LeaveRequest[]>([]);\n  const [employees, setEmployees] = useState<{ employeeId: string; fullName: string }[]>([]);\n  const [open, setOpen] = useState(false);\n  const [syncingErp, setSyncingErp] = useState(false);\n  const [form, setForm] = useState({ employeeId: '', type: 'Casual Leave', startDate: '', endDate: '', days: 1, reason: '' });\n\n  const loadData = useCallback(async () => {\n    const [lRes, eRes] = await Promise.all([fetch('/api/leaves'), fetch('/api/employees')]);\n    setLeaves(await lRes.json());\n    const empData = await eRes.json();\n    setEmployees(empData.map((e: any) => ({ employeeId: e.employeeId, fullName: e.fullName })));\n  }, []);\n\n  useEffect(() => { loadData(); }, [loadData]);\n\n  // ─── ERP Integration: Pull pending leaves from ERP into HRMS ───\n  // SAFE: only inserts new records; existing HRMS leaves are not touched\n  const handleSyncErp = async () => {\n    setSyncingErp(true);\n    try {\n      const res = await fetch('/api/leaves/erp-pull');\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || 'Sync failed');\n      toast.success(\n        `Synced ${data.summary?.synced || 0} new ERP leaves (skipped ${data.summary?.skipped || 0}, errors ${data.summary?.errors || 0})`\n      );\n      loadData();\n    } catch (err: any) {\n      toast.error(`ERP sync failed: ${err.message}`);\n    } finally {\n      setSyncingErp(false);\n    }\n  };\n\n  const handleSubmit = async () => {\n    if (!form.employeeId || !form.startDate || !form.endDate) { toast.error('Fill required fields'); return; }\n    await fetch('/api/leaves', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(form),\n    });\n    toast.success('Leave request submitted');\n    setOpen(false);\n    loadData();\n  };\n\n  // ─── ERP Integration: When approving/rejecting, also push status back to ERP ───\n  // SAFE: if the leave is not ERP-originated, erp-push returns success with synced=false\n  const handleAction = async (id: string, status: string) => {\n    // 1. Update HRMS Leave status (existing flow — UNCHANGED)\n    await fetch('/api/leaves', {\n      method: 'PUT',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ id, status }),\n    });\n    toast.success(`Leave ${status}`);\n\n    // 2. Best-effort push to ERP (non-blocking — won't break HRMS flow if ERP is down)\n    try {\n      const pushRes = await fetch('/api/leaves/erp-push', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ leaveId: id, status, approvedBy: 'HR' }),\n      });\n      const pushData = await pushRes.json();\n      if (pushData.synced) {\n        toast.success(`ERP updated: ${pushData.message || 'synced'}`);\n      }\n    } catch {\n      // Silent fail — ERP sync is best-effort\n    }\n    loadData();\n  };\n\n  const pending = leaves.filter(l => l.status === 'pending').length;\n  const approved = leaves.filter(l => l.status === 'approved').length;\n  const rejected = leaves.filter(l => l.status === 'rejected').length;\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n        <div>\n          <h2 className=\"text-xl font-bold\">Leave Management</h2>\n          <p className=\"text-sm text-muted-foreground\">{pending} pending approvals</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <Button variant=\"outline\" onClick={handleSyncErp} disabled={syncingErp}>\n            <RefreshCw className={`w-4 h-4 mr-2 ${syncingErp ? 'animate-spin' : ''}`} />\n            {syncingErp ? 'Syncing...' : 'Sync ERP Leaves'}\n          </Button>\n          <Dialog open={open} onOpenChange={setOpen}>\n            <DialogTrigger asChild>\n              <Button className=\"bg-gold text-white\"><CalendarDays className=\"w-4 h-4 mr-2\" /> Apply Leave</Button>\n            </DialogTrigger>\n          <DialogContent className=\"max-h-[90vh] overflow-y-auto\">\n            <DialogHeader><DialogTitle>Apply Leave</DialogTitle></DialogHeader>\n            <div className=\"space-y-4 py-4\">\n              <div><Label>Employee</Label><Select value={form.employeeId} onValueChange={v => setForm({ ...form, employeeId: v })}><SelectTrigger><SelectValue placeholder=\"Select\" /></SelectTrigger><SelectContent>{employees.map(e => <SelectItem key={e.employeeId} value={e.employeeId}>{e.fullName}</SelectItem>)}</SelectContent></Select></div>\n              <div><Label>Leave Type</Label><Select value={form.type} onValueChange={v => setForm({ ...form, type: v })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value=\"Casual Leave\">Casual Leave</SelectItem><SelectItem value=\"Sick Leave\">Sick Leave</SelectItem><SelectItem value=\"Earned Leave\">Earned Leave</SelectItem><SelectItem value=\"Maternity Leave\">Maternity Leave</SelectItem></SelectContent></Select></div>\n              <div className=\"grid grid-cols-2 gap-3\">\n                <div><Label>Start Date</Label><Input type=\"date\" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} /></div>\n                <div><Label>End Date</Label><Input type=\"date\" value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} /></div>\n              </div>\n              <div><Label>Days</Label><Input type=\"number\" value={form.days} onChange={e => setForm({ ...form, days: Number(e.target.value) })} /></div>\n              <div><Label>Reason</Label><Input value={form.reason} onChange={e => setForm({ ...form, reason: e.target.value })} placeholder=\"Reason for leave\" /></div>\n              <Button className=\"w-full bg-gold text-white\" onClick={handleSubmit}>Submit Leave</Button>\n            </div>\n          </DialogContent>\n          </Dialog>\n        </div>\n      </div>\n\n      <div className=\"grid grid-cols-3 gap-3\">\n        {[\n          { title: 'Pending', value: pending, color: 'text-yellow-500', icon: Clock },\n          { title: 'Approved', value: approved, color: 'text-green-500', icon: Check },\n          { title: 'Rejected', value: rejected, color: 'text-red-500', icon: X },\n        ].map((c, i) => (\n          <motion.div key={c.title} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-4 flex items-center gap-3\">\n                <c.icon className={`w-8 h-8 ${c.color}`} />\n                <div className=\"min-w-0 overflow-hidden\"><p className=\"text-xs text-muted-foreground truncate\">{c.title}</p><p className=\"text-xl font-bold\">{c.value}</p></div>\n              </CardContent>\n            </Card>\n          </motion.div>\n        ))}\n      </div>\n\n      <Card className=\"glass-card card-gold-hover border-0\">\n        <CardContent className=\"p-0\">\n          <ScrollArea className=\"max-h-[55vh]\">\n            <Table>\n              <TableHeader><TableRow><TableHead>Employee</TableHead><TableHead>Type</TableHead><TableHead>Duration</TableHead><TableHead>Days</TableHead><TableHead>Status</TableHead><TableHead>Actions</TableHead></TableRow></TableHeader>\n              <TableBody>\n                {leaves.map((l) => {\n                  const isErpOriginated = !!(l.reason && l.reason.includes('[ERP:'));\n                  return (\n                  <TableRow key={l.id} className=\"hover:bg-muted/30\">\n                    <TableCell><div className=\"min-w-0 overflow-hidden\"><p className=\"text-sm font-medium truncate flex items-center gap-1.5\">{l.employee?.fullName || l.employeeId}{isErpOriginated && <span className=\"text-[9px] px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 font-bold\">ERP</span>}</p><p className=\"text-xs text-muted-foreground truncate\">{l.employee?.department}</p></div></TableCell>\n                    <TableCell className=\"text-sm whitespace-nowrap\">{l.type}</TableCell>\n                    <TableCell className=\"text-sm whitespace-nowrap\">{new Date(l.startDate).toLocaleDateString()} - {new Date(l.endDate).toLocaleDateString()}</TableCell>\n                    <TableCell className=\"text-sm whitespace-nowrap\">{l.days}</TableCell>\n                    <TableCell>\n                      <Badge variant={l.status === 'approved' ? 'default' : l.status === 'rejected' ? 'destructive' : 'secondary'} className=\"text-[10px] whitespace-nowrap shrink-0\">{l.status}</Badge>\n                    </TableCell>\n                    <TableCell>\n                      {l.status === 'pending' && (\n                        <div className=\"flex gap-1\">\n                          <Button size=\"icon\" variant=\"ghost\" className=\"h-7 w-7 text-green-500\" onClick={() => handleAction(l.id, 'approved')}><Check className=\"w-4 h-4\" /></Button>\n                          <Button size=\"icon\" variant=\"ghost\" className=\"h-7 w-7 text-red-500\" onClick={() => handleAction(l.id, 'rejected')}><X className=\"w-4 h-4\" /></Button>\n                        </div>\n                      )}\n                    </TableCell>\n                  </TableRow>\n                  );\n                })}\n              </TableBody>\n            </Table>\n          </ScrollArea>\n        </CardContent>\n      </Card>\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback } from 'react';\nimport { Palmtree, Plus, Trash2 } from 'lucide-react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Input } from '@/components/ui/input';\nimport { Label } from '@/components/ui/label';\nimport { Badge } from '@/components/ui/badge';\nimport { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { toast } from 'sonner';\nimport { motion } from 'framer-motion';\n\ninterface Holiday {\n  id: string;\n  name: string;\n  date: string;\n  type: string;\n  description: string | null;\n}\n\nexport function HolidayCalendar() {\n  const [holidays, setHolidays] = useState<Holiday[]>([]);\n  const [open, setOpen] = useState(false);\n  const [form, setForm] = useState({ name: '', date: '', type: 'national', description: '' });\n\n  const loadData = useCallback(async () => {\n    const res = await fetch('/api/holidays');\n    setHolidays(await res.json());\n  }, []);\n\n  useEffect(() => { loadData(); }, [loadData]);\n\n  const handleSubmit = async () => {\n    if (!form.name || !form.date) { toast.error('Fill required fields'); return; }\n    await fetch('/api/holidays', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(form),\n    });\n    toast.success('Holiday added');\n    setOpen(false);\n    setForm({ name: '', date: '', type: 'national', description: '' });\n    loadData();\n  };\n\n  const handleDelete = async (id: string) => {\n    await fetch(`/api/holidays?id=${id}`, { method: 'DELETE' });\n    toast.success('Holiday removed');\n    loadData();\n  };\n\n  const typeColors: Record<string, string> = {\n    national: 'bg-red-500/10 text-red-500 border-red-500/20',\n    festival: 'bg-purple-500/10 text-purple-500 border-purple-500/20',\n    optional: 'bg-yellow-500/10 text-yellow-500 border-yellow-500/20',\n    company: 'bg-blue-500/10 text-blue-500 border-blue-500/20',\n  };\n\n  const grouped = holidays.reduce((acc, h) => {\n    const month = new Date(h.date).toLocaleString('default', { month: 'long', year: 'numeric' });\n    if (!acc[month]) acc[month] = [];\n    acc[month].push(h);\n    return acc;\n  }, {} as Record<string, Holiday[]>);\n\n  return (\n    <div className=\"space-y-4\">\n      <div className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n        <div>\n          <h2 className=\"text-xl font-bold\">Holiday Calendar</h2>\n          <p className=\"text-sm text-muted-foreground\">{holidays.length} holidays configured &middot; Sundays auto-marked as weekly off</p>\n        </div>\n        <Dialog open={open} onOpenChange={setOpen}>\n          <DialogTrigger asChild>\n            <Button className=\"bg-gold text-white\"><Plus className=\"w-4 h-4 mr-2\" /> Add Holiday</Button>\n          </DialogTrigger>\n          <DialogContent>\n            <DialogHeader><DialogTitle>Add Holiday</DialogTitle></DialogHeader>\n            <div className=\"space-y-4 py-4\">\n              <div><Label>Holiday Name *</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder=\"e.g. Republic Day\" /></div>\n              <div><Label>Date *</Label><Input type=\"date\" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} /></div>\n              <div><Label>Type</Label><Select value={form.type} onValueChange={v => setForm({ ...form, type: v })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value=\"national\">National Holiday</SelectItem><SelectItem value=\"festival\">Festival</SelectItem><SelectItem value=\"optional\">Optional Holiday</SelectItem><SelectItem value=\"company\">Company Holiday</SelectItem></SelectContent></Select></div>\n              <div><Label>Description</Label><Input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder=\"Optional description\" /></div>\n              <Button className=\"w-full bg-gold text-white\" onClick={handleSubmit}>Add Holiday</Button>\n            </div>\n          </DialogContent>\n        </Dialog>\n      </div>\n\n      {Object.entries(grouped).map(([month, items]) => (\n        <motion.div key={month} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>\n          <Card className=\"glass-card card-gold-hover border-0 mb-4\">\n            <CardHeader className=\"pb-2\">\n              <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                <Palmtree className=\"w-4 h-4 text-gold\" /> {month}\n              </CardTitle>\n            </CardHeader>\n            <CardContent>\n              <div className=\"space-y-2\">\n                {items.map((h) => (\n                  <div key={h.id} className=\"flex items-center justify-between p-3 rounded-lg hover:bg-muted/50 transition-colors\">\n                    <div className=\"flex items-center gap-3\">\n                      <div className=\"text-center w-12\">\n                        <p className=\"text-lg font-bold\">{new Date(h.date).getDate()}</p>\n                        <p className=\"text-[10px] text-muted-foreground\">{new Date(h.date).toLocaleString('default', { weekday: 'short' })}</p>\n                      </div>\n                      <div>\n                        <p className=\"text-sm font-medium\">{h.name}</p>\n                        <Badge className={`text-[10px] ${typeColors[h.type] || ''}`} variant=\"outline\">{h.type}</Badge>\n                      </div>\n                    </div>\n                    <Button variant=\"ghost\" size=\"icon\" className=\"h-7 w-7 text-destructive\" onClick={() => handleDelete(h.id)}>\n                      <Trash2 className=\"w-3.5 h-3.5\" />\n                    </Button>\n                  </div>\n                ))}\n              </div>\n            </CardContent>\n          </Card>\n        </motion.div>\n      ))}\n\n      {holidays.length === 0 && (\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardContent className=\"p-8 text-center text-muted-foreground\">\n            <Palmtree className=\"w-12 h-12 mx-auto mb-3 opacity-30\" />\n            <p>No holidays configured. Add holidays to get started.</p>\n          </CardContent>\n        </Card>\n      )}\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback, useMemo } from 'react';\nimport {\n  BarChart3, TrendingUp, Users, DollarSign, Clock, Building2, MapPin,\n  CalendarDays, UserCheck, UserX, AlertTriangle, Timer, Activity,\n  Cake, PartyPopper, Palmtree, ChevronRight, Search, X, ArrowUpRight, ArrowDownRight,\n} from 'lucide-react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Input } from '@/components/ui/input';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';\nimport { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';\nimport { Badge } from '@/components/ui/badge';\nimport { ScrollArea } from '@/components/ui/scroll-area';\nimport { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';\nimport { motion } from 'framer-motion';\nimport {\n  AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis,\n  CartesianGrid, Tooltip, ResponsiveContainer, Legend, RadarChart, PolarGrid,\n  PolarAngleAxis, PolarRadiusAxis, Radar, RadialBarChart, RadialBar,\n} from 'recharts';\n\nconst LAXREE_COLORS = {\n  gold: '#D4A843',\n  teal: '#14b8a6',\n  cyan: '#06b6d4',\n  amber: '#f59e0b',\n  rose: '#f43f5e',\n  violet: '#8b5cf6',\n  emerald: '#10b981',\n  sky: '#0ea5e9',\n  lime: '#84cc16',\n  pink: '#ec4899',\n};\n\nconst FIRM_COLORS: Record<string, string> = {\n  LAPL: LAXREE_COLORS.gold,\n  LRSL: LAXREE_COLORS.cyan,\n  SI: LAXREE_COLORS.amber,\n  SDF: LAXREE_COLORS.violet,\n};\n\nconst FIRM_BADGE_CLASS: Record<string, string> = {\n  LAPL: 'firm-badge-lapl',\n  LRSL: 'firm-badge-lrsl',\n  SI: 'firm-badge-si',\n  SDF: 'firm-badge-sdf',\n};\n\nconst STATUS_COLORS: Record<string, string> = {\n  present: LAXREE_COLORS.emerald,\n  absent: LAXREE_COLORS.rose,\n  late: LAXREE_COLORS.amber,\n  'early-out': LAXREE_COLORS.sky,\n  'half-day': LAXREE_COLORS.orange || '#f97316',\n  holiday: LAXREE_COLORS.violet,\n  'weekly-off': LAXREE_COLORS.cyan,\n};\n\nfunction formatHours(decimal: number): string {\n  if (!decimal || decimal === 0) return '0:00';\n  const hours = Math.floor(decimal);\n  const minutes = Math.round((decimal - hours) * 60);\n  if (minutes >= 60) return `${hours + 1}:00`;\n  return `${hours}:${String(minutes).padStart(2, '0')}`;\n}\n\n// Format overtime in clear human-readable format (e.g., \"7m\", \"1h 30m\")\nfunction formatOT(decimal: number): string {\n  if (!decimal || decimal === 0) return '0m';\n  const totalMinutes = Math.round(decimal * 60);\n  if (totalMinutes < 60) return `${totalMinutes}m`;\n  const hours = Math.floor(totalMinutes / 60);\n  const minutes = totalMinutes % 60;\n  if (minutes === 0) return `${hours}h`;\n  return `${hours}h ${minutes}m`;\n}\n\nconst FIRMS = ['LAPL', 'LRSL', 'SI', 'SDF'];\nconst MONTHS_FULL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];\nconst MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\n\n// ── Animated Counter ──\nfunction AnimatedCounter({ value, prefix = '', suffix = '', decimals = 0 }: {\n  value: number; prefix?: string; suffix?: string; decimals?: number;\n}) {\n  const [display, setDisplay] = useState(0);\n  useEffect(() => {\n    const duration = 800;\n    const startTime = Date.now();\n    const step = () => {\n      const elapsed = Date.now() - startTime;\n      const progress = Math.min(elapsed / duration, 1);\n      const eased = 1 - Math.pow(1 - progress, 3);\n      setDisplay(value * eased);\n      if (progress < 1) requestAnimationFrame(step);\n    };\n    requestAnimationFrame(step);\n  }, [value]);\n\n  if (decimals > 0) return <span>{prefix}{display.toFixed(decimals)}{suffix}</span>;\n  return <span>{prefix}{Math.round(display).toLocaleString('en-IN')}{suffix}</span>;\n}\n\nexport function ReportsAnalytics() {\n  const now = new Date();\n  const [month, setMonth] = useState(now.getMonth() + 1);\n  const [year, setYear] = useState(now.getFullYear());\n  const [selectedFirm, setSelectedFirm] = useState('all');\n\n  // ── Data states ──\n  const [attReport, setAttReport] = useState<any>(null);\n  const [payReport, setPayReport] = useState<any>(null);\n  const [dashboardData, setDashboardData] = useState<any>(null);\n  const [analyticsData, setAnalyticsData] = useState<any>(null);\n  const [eventsData, setEventsData] = useState<any>(null);\n\n  // ── Attendance tab filters ──\n  const [attEmployeeSearch, setAttEmployeeSearch] = useState('');\n  const [attStatusFilter, setAttStatusFilter] = useState('all');\n  const [attDate, setAttDate] = useState(() => {\n    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;\n  });\n\n  // ── Day detail dialog ──\n  const [dayDetailOpen, setDayDetailOpen] = useState(false);\n  const [dayDetailType, setDayDetailType] = useState('');\n  const [dayDetailRecords, setDayDetailRecords] = useState<any[]>([]);\n\n  // ── Load data ──\n  const loadData = useCallback(async () => {\n    try {\n      const [aRes, pRes, dRes, anRes, evRes] = await Promise.all([\n        fetch(`/api/reports/attendance?month=${month}&year=${year}`),\n        fetch(`/api/reports/payroll?month=${month}&year=${year}`),\n        fetch('/api/dashboard'),\n        fetch(`/api/reports/analytics?month=${month}&year=${year}`),\n        fetch('/api/reports/events'),\n      ]);\n      setAttReport(await aRes.json());\n      setPayReport(await pRes.json());\n      setDashboardData(await dRes.json());\n      if (anRes.ok) setAnalyticsData(await anRes.json());\n      if (evRes.ok) setEventsData(await evRes.json());\n    } catch (err) {\n      console.error('Failed to load report data:', err);\n    }\n  }, [month, year]);\n\n  useEffect(() => { loadData(); }, [loadData]);\n\n  const FirmBadge = ({ firm }: { firm: string }) => (\n    <span className={`${FIRM_BADGE_CLASS[firm] || 'firm-badge-lapl'} whitespace-nowrap shrink-0`}>{firm}</span>\n  );\n\n  // ── Filtered payroll ──\n  const filteredPayrolls = selectedFirm !== 'all' && payReport?.payrolls\n    ? payReport.payrolls.filter((p: any) => p.employee?.department === selectedFirm)\n    : payReport?.payrolls || [];\n\n  // ── Filtered attendance records ──\n  const filteredAttRecords = useMemo(() => {\n    if (!attReport?.records) return [];\n    let records = attReport.records;\n    if (attStatusFilter !== 'all') {\n      records = records.filter((r: any) => {\n        if (attStatusFilter === 'late') return r.lateEntry;\n        if (attStatusFilter === 'early-out') return r.earlyOut;\n        if (attStatusFilter === 'absent') return r.status === 'absent';\n        if (attStatusFilter === 'present') return ['present', 'late', 'early-out'].includes(r.status);\n        if (attStatusFilter === 'half-day') return r.halfDay;\n        return true;\n      });\n    }\n    if (attEmployeeSearch) {\n      const q = attEmployeeSearch.toLowerCase();\n      records = records.filter((r: any) =>\n        r.employee?.fullName?.toLowerCase().includes(q) || r.employeeId?.toLowerCase().includes(q)\n      );\n    }\n    return records;\n  }, [attReport, attStatusFilter, attEmployeeSearch]);\n\n  // ── Day summary click handler ──\n  const handleDaySummaryClick = (type: string) => {\n    if (!attReport?.records) return;\n    let records: any[] = [];\n    if (type === 'present') records = attReport.records.filter((r: any) => ['present', 'late', 'early-out'].includes(r.status));\n    else if (type === 'absent') records = attReport.records.filter((r: any) => r.status === 'absent');\n    else if (type === 'late') records = attReport.records.filter((r: any) => r.lateEntry);\n    else if (type === 'early-out') records = attReport.records.filter((r: any) => r.earlyOut);\n    else if (type === 'on-time') records = attReport.records.filter((r: any) => !r.lateEntry && ['present', 'early-out'].includes(r.status));\n\n    setDayDetailType(type);\n    setDayDetailRecords(records);\n    setDayDetailOpen(true);\n  };\n\n  const firmPayrollData = dashboardData?.firmWiseCount?.map((f: any) => ({\n    firm: f.firm,\n    employees: f.count,\n    payroll: dashboardData?.firmPayrollBreakdown?.[f.firm]?.totalNet || 0,\n    fill: FIRM_COLORS[f.firm] || LAXREE_COLORS.gold,\n  })) || [];\n\n  // ── Gender pie data ──\n  const genderPieData = analyticsData?.genderRatio ? [\n    { name: 'Male', value: analyticsData.genderRatio.male || 0, fill: LAXREE_COLORS.cyan },\n    { name: 'Female', value: analyticsData.genderRatio.female || 0, fill: LAXREE_COLORS.rose },\n    { name: 'Other', value: analyticsData.genderRatio.other || 0, fill: LAXREE_COLORS.violet },\n  ].filter(d => d.value > 0) : [];\n\n  // ── On-time vs Late pie data ──\n  const onTimePieData = analyticsData?.attendanceAnalytics ? [\n    { name: 'On Time', value: parseFloat((analyticsData.attendanceAnalytics.onTimeArrivalPct || 0).toFixed(1)), fill: LAXREE_COLORS.emerald },\n    { name: 'Late', value: parseFloat((analyticsData.attendanceAnalytics.lateArrivalPct || 0).toFixed(1)), fill: LAXREE_COLORS.amber },\n  ] : [];\n\n  // ── Employment type chart data ──\n  const empTypeData = analyticsData?.employmentTypeBreakdown || [];\n\n  // ── Shift distribution chart data ──\n  const shiftData = analyticsData?.shiftDistribution || [];\n\n  // ── Weekly trend data ──\n  const weeklyTrendData = analyticsData?.weeklyTrend || [];\n\n  return (\n    <div className=\"space-y-4\">\n      {/* ── Header ── */}\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\"\n      >\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <BarChart3 className=\"w-5 h-5 text-gold\" />\n            Reports & Analytics\n          </h2>\n          <p className=\"text-sm text-muted-foreground\">Professional HR analytics & insights for Laxree Group</p>\n        </div>\n        <div className=\"flex gap-2 flex-wrap\">\n          <Select value={String(month)} onValueChange={v => setMonth(Number(v))}>\n            <SelectTrigger className=\"w-28\"><SelectValue /></SelectTrigger>\n            <SelectContent>{MONTHS_SHORT.map((m, i) => <SelectItem key={i} value={String(i + 1)}>{m}</SelectItem>)}</SelectContent>\n          </Select>\n          <Select value={String(year)} onValueChange={v => setYear(Number(v))}>\n            <SelectTrigger className=\"w-24\"><SelectValue /></SelectTrigger>\n            <SelectContent>{[2024, 2025, 2026, 2027].map(y => <SelectItem key={y} value={String(y)}>{y}</SelectItem>)}</SelectContent>\n          </Select>\n        </div>\n      </motion.div>\n\n      <Tabs defaultValue=\"overview\">\n        <TabsList className=\"flex-wrap\">\n          <TabsTrigger value=\"overview\">Overview</TabsTrigger>\n          <TabsTrigger value=\"attendance\">Attendance</TabsTrigger>\n          <TabsTrigger value=\"analytics\">Analytics</TabsTrigger>\n          <TabsTrigger value=\"events\">Events</TabsTrigger>\n          <TabsTrigger value=\"payroll\">Payroll</TabsTrigger>\n          <TabsTrigger value=\"firm-wise\">Firm-wise</TabsTrigger>\n        </TabsList>\n\n        {/* ════════════════════════════════════════════\n            OVERVIEW TAB\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"overview\" className=\"space-y-4 mt-4\">\n          {/* KPI Summary */}\n          {dashboardData && (\n            <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3\">\n              {[\n                { title: 'Total Employees', value: dashboardData.totalEmployees, icon: Users, color: 'text-gold', gradient: 'gradient-laxree' },\n                { title: 'Present Today', value: dashboardData.presentToday, icon: UserCheck, color: 'text-teal-500', gradient: 'gradient-success' },\n                { title: 'Monthly Payroll', value: `₹${dashboardData.monthlyPayrollCost?.toLocaleString('en-IN') || 0}`, icon: DollarSign, color: 'text-violet-500', gradient: 'gradient-info' },\n                { title: 'Pending Leaves', value: dashboardData.pendingLeaves, icon: TrendingUp, color: 'text-amber-500', gradient: 'gradient-warning' },\n              ].map((c, i) => (\n                <motion.div key={c.title} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>\n                  <Card className=\"glass-card card-gold-hover border-0\">\n                    <CardContent className=\"p-4 flex items-center gap-3\">\n                      <div className={`w-10 h-10 rounded-xl ${c.gradient} flex items-center justify-center shrink-0 shadow-lg`}>\n                        <c.icon className=\"w-5 h-5 text-white\" />\n                      </div>\n                      <div className=\"min-w-0 overflow-hidden\">\n                        <p className=\"text-xs text-muted-foreground truncate\">{c.title}</p>\n                        <p className=\"text-lg font-bold\">{c.value}</p>\n                      </div>\n                    </CardContent>\n                  </Card>\n                </motion.div>\n              ))}\n            </div>\n          )}\n\n          {/* Quick Day Summary Cards - clickable */}\n          {analyticsData?.dailySummary && (\n            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>\n              <Card className=\"glass-card border-gold/20 border\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm flex items-center gap-2\">\n                    <Activity className=\"w-4 h-4 text-gold\" />\n                    Today&apos;s Snapshot — {new Date().toLocaleDateString('en-IN', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })}\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"grid grid-cols-3 sm:grid-cols-6 gap-3\">\n                    {[\n                      { label: 'Present', value: analyticsData.dailySummary.present, icon: UserCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', type: 'present' },\n                      { label: 'Absent', value: analyticsData.dailySummary.absent, icon: UserX, color: 'text-red-500', bg: 'bg-red-500/10', type: 'absent' },\n                      { label: 'Late', value: analyticsData.dailySummary.late, icon: AlertTriangle, color: 'text-amber-500', bg: 'bg-amber-500/10', type: 'late' },\n                      { label: 'Early Out', value: analyticsData.dailySummary.earlyOut, icon: Clock, color: 'text-sky-500', bg: 'bg-sky-500/10', type: 'early-out' },\n                      { label: 'On Time', value: analyticsData.dailySummary.onTime, icon: UserCheck, color: 'text-teal-500', bg: 'bg-teal-500/10', type: 'on-time' },\n                      { label: 'Half Day', value: analyticsData.dailySummary.halfDay, icon: Timer, color: 'text-orange-500', bg: 'bg-orange-500/10', type: 'half-day' },\n                    ].map((item) => (\n                      <div\n                        key={item.label}\n                        className={`cursor-pointer rounded-xl p-3 ${item.bg} border border-transparent hover:border-gold/30 transition-all duration-200 hover:shadow-md`}\n                        onClick={() => handleDaySummaryClick(item.type)}\n                      >\n                        <div className=\"flex items-center gap-1.5 mb-1\">\n                          <item.icon className={`w-3.5 h-3.5 ${item.color}`} />\n                          <span className=\"text-[10px] font-medium text-muted-foreground\">{item.label}</span>\n                          <ChevronRight className=\"w-3 h-3 text-muted-foreground/50 ml-auto\" />\n                        </div>\n                        <p className={`text-xl font-bold ${item.color}`}>{item.value}</p>\n                      </div>\n                    ))}\n                  </div>\n                  <p className=\"text-[10px] text-muted-foreground mt-2\">Click any card to see employee details</p>\n                </CardContent>\n              </Card>\n            </motion.div>\n          )}\n\n          {/* Charts */}\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n            {dashboardData?.attendanceTrend && (\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\"><CardTitle className=\"text-sm\">Attendance Trend (7 Days)</CardTitle></CardHeader>\n                <CardContent>\n                  <div className=\"h-52\">\n                    <ResponsiveContainer width=\"100%\" height=\"100%\">\n                      <AreaChart data={dashboardData.attendanceTrend}>\n                        <defs>\n                          <linearGradient id=\"attPresentGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                            <stop offset=\"5%\" stopColor={LAXREE_COLORS.gold} stopOpacity={0.3} />\n                            <stop offset=\"95%\" stopColor={LAXREE_COLORS.gold} stopOpacity={0} />\n                          </linearGradient>\n                        </defs>\n                        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                        <XAxis dataKey=\"date\" tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" tickFormatter={(v) => v.slice(5)} />\n                        <YAxis tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" />\n                        <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                        <Area type=\"monotone\" dataKey=\"present\" stroke={LAXREE_COLORS.gold} fill=\"url(#attPresentGrad)\" name=\"Present\" />\n                        <Area type=\"monotone\" dataKey=\"absent\" stroke={LAXREE_COLORS.rose} fill=\"transparent\" strokeDasharray=\"5 5\" name=\"Absent\" />\n                        <Legend />\n                      </AreaChart>\n                    </ResponsiveContainer>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {dashboardData?.firmWiseCount && (\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\"><CardTitle className=\"text-sm\">Firm Distribution</CardTitle></CardHeader>\n                <CardContent>\n                  <div className=\"h-52\">\n                    <ResponsiveContainer width=\"100%\" height=\"100%\">\n                      <PieChart>\n                        <Pie data={dashboardData.firmWiseCount} dataKey=\"count\" nameKey=\"firm\" cx=\"50%\" cy=\"50%\" outerRadius={70} innerRadius={35} paddingAngle={2}>\n                          {dashboardData.firmWiseCount.map((entry: any, i: number) => (\n                            <Cell key={i} fill={FIRM_COLORS[entry.firm] || LAXREE_COLORS.gold} />\n                          ))}\n                        </Pie>\n                        <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                        <Legend iconType=\"circle\" iconSize={8} wrapperStyle={{ fontSize: '11px' }} />\n                      </PieChart>\n                    </ResponsiveContainer>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n          </div>\n        </TabsContent>\n\n        {/* ════════════════════════════════════════════\n            ATTENDANCE TAB (Enhanced with dropdowns)\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"attendance\" className=\"mt-4\">\n          {attReport && (\n            <div className=\"space-y-4\">\n              {/* ── Filter Row ── */}\n              <Card className=\"glass-card border-0\">\n                <CardContent className=\"p-3\">\n                  <div className=\"flex flex-col sm:flex-row gap-3 flex-wrap\">\n                    {/* Employee Search */}\n                    <div className=\"relative flex-1 min-w-[200px]\">\n                      <Search className=\"absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground\" />\n                      <Input\n                        className=\"pl-9 h-9\"\n                        placeholder=\"Search employee...\"\n                        value={attEmployeeSearch}\n                        onChange={(e) => setAttEmployeeSearch(e.target.value)}\n                      />\n                    </div>\n                    {/* Month Filter */}\n                    <Select value={String(month)} onValueChange={v => setMonth(Number(v))}>\n                      <SelectTrigger className=\"w-36 h-9\">\n                        <CalendarDays className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n                        <SelectValue />\n                      </SelectTrigger>\n                      <SelectContent>\n                        {MONTHS_FULL.map((m, i) => <SelectItem key={i} value={String(i + 1)}>{m}</SelectItem>)}\n                      </SelectContent>\n                    </Select>\n                    {/* Status Filter */}\n                    <Select value={attStatusFilter} onValueChange={setAttStatusFilter}>\n                      <SelectTrigger className=\"w-40 h-9\">\n                        <Activity className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n                        <SelectValue placeholder=\"All Status\" />\n                      </SelectTrigger>\n                      <SelectContent>\n                        <SelectItem value=\"all\">All Status</SelectItem>\n                        <SelectItem value=\"present\">Present</SelectItem>\n                        <SelectItem value=\"absent\">Absent</SelectItem>\n                        <SelectItem value=\"late\">Late Coming</SelectItem>\n                        <SelectItem value=\"early-out\">Early Out</SelectItem>\n                        <SelectItem value=\"half-day\">Half Day</SelectItem>\n                      </SelectContent>\n                    </Select>\n                    {/* Firm Filter */}\n                    <Select value={selectedFirm} onValueChange={setSelectedFirm}>\n                      <SelectTrigger className=\"w-32 h-9\">\n                        <Building2 className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n                        <SelectValue placeholder=\"All Firms\" />\n                      </SelectTrigger>\n                      <SelectContent>\n                        <SelectItem value=\"all\">All Firms</SelectItem>\n                        {FIRMS.map(f => <SelectItem key={f} value={f}>{f}</SelectItem>)}\n                      </SelectContent>\n                    </Select>\n                    {attStatusFilter !== 'all' && (\n                      <Badge variant=\"outline\" className=\"h-9 px-3 flex items-center gap-1.5 cursor-pointer\" onClick={() => setAttStatusFilter('all')}>\n                        {attStatusFilter === 'late' ? 'Late Coming' : attStatusFilter === 'early-out' ? 'Early Out' : attStatusFilter.charAt(0).toUpperCase() + attStatusFilter.slice(1)}\n                        <X className=\"w-3 h-3\" />\n                      </Badge>\n                    )}\n                  </div>\n                </CardContent>\n              </Card>\n\n              {/* ── Summary Cards (clickable) ── */}\n              <div className=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3\">\n                {[\n                  { title: 'Present', value: attReport.summary?.present || 0, color: 'text-emerald-500', gradient: 'gradient-success', type: 'present' },\n                  { title: 'Absent', value: attReport.summary?.absent || 0, color: 'text-red-500', gradient: 'gradient-danger', type: 'absent' },\n                  { title: 'Late Coming', value: attReport.summary?.late || 0, color: 'text-amber-500', gradient: 'gradient-warning', type: 'late' },\n                  { title: 'Early Out', value: attReport.summary?.earlyOuts || 0, color: 'text-sky-500', gradient: 'gradient-rose', type: 'early-out' },\n                  { title: 'Half Day', value: attReport.summary?.halfDay || 0, color: 'text-orange-500', gradient: 'gradient-info', type: 'half-day' },\n                  { title: 'OT Hours', value: (attReport.summary?.totalOvertimeHours || 0).toFixed(2), color: 'text-cyan-500', gradient: 'gradient-laxree', type: '' },\n                ].map((c, i) => (\n                  <motion.div\n                    key={c.title}\n                    initial={{ opacity: 0, y: 10 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    transition={{ delay: i * 0.03 }}\n                    className={`cursor-pointer ${c.type ? 'hover:shadow-lg hover:border-gold/30' : ''} transition-all duration-200`}\n                    onClick={() => c.type && handleDaySummaryClick(c.type)}\n                  >\n                    <Card className=\"glass-card card-gold-hover border-0\">\n                      <CardContent className=\"p-3 text-center min-w-0\">\n                        <p className=\"text-[10px] text-muted-foreground truncate\">{c.title}</p>\n                        <p className={`text-xl font-bold ${c.color}`}>\n                          {c.title === 'OT Hours' ? `${c.value}h` : c.value}\n                        </p>\n                        {c.type && <ChevronRight className=\"w-3 h-3 text-muted-foreground/50 mx-auto mt-0.5\" />}\n                      </CardContent>\n                    </Card>\n                  </motion.div>\n                ))}\n              </div>\n\n              {/* ── Attendance Table ── */}\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardContent className=\"p-0\">\n                  <ScrollArea className=\"max-h-[50vh]\">\n                    <Table>\n                      <TableHeader>\n                        <TableRow>\n                          <TableHead>Employee</TableHead>\n                          <TableHead>Firm</TableHead>\n                          <TableHead>Date</TableHead>\n                          <TableHead>Check In</TableHead>\n                          <TableHead>Check Out</TableHead>\n                          <TableHead>Status</TableHead>\n                          <TableHead>Hours</TableHead>\n                          <TableHead>OT</TableHead>\n                        </TableRow>\n                      </TableHeader>\n                      <TableBody>\n                        {filteredAttRecords.length === 0 ? (\n                          <TableRow>\n                            <TableCell colSpan={8} className=\"text-center py-12 text-muted-foreground\">\n                              <Clock className=\"w-8 h-8 mx-auto mb-2 opacity-30\" />\n                              <p>No records found for selected filters</p>\n                            </TableCell>\n                          </TableRow>\n                        ) : (\n                          filteredAttRecords.slice(0, 100).map((r: any) => (\n                            <TableRow key={r.id} className=\"hover:bg-muted/30\">\n                              <TableCell className=\"text-sm\">\n                                <div>\n                                  <p className=\"font-medium truncate max-w-[150px]\">{r.employee?.fullName || r.employeeId}</p>\n                                  <p className=\"text-[10px] text-muted-foreground\">{r.employeeId}</p>\n                                </div>\n                              </TableCell>\n                              <TableCell><FirmBadge firm={r.employee?.department || ''} /></TableCell>\n                              <TableCell className=\"text-sm whitespace-nowrap\">{new Date(r.date).toLocaleDateString('en-IN')}</TableCell>\n                              <TableCell className=\"text-sm font-mono\">{r.checkIn || '-'}</TableCell>\n                              <TableCell className=\"text-sm font-mono\">{r.checkOut || '-'}</TableCell>\n                              <TableCell>\n                                <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border whitespace-nowrap ${\n                                  r.status === 'present' ? 'bg-emerald-500/15 text-emerald-600 border-emerald-500/20' :\n                                  r.status === 'absent' ? 'bg-red-500/15 text-red-600 border-red-500/20' :\n                                  r.status === 'late' ? 'bg-amber-500/15 text-amber-600 border-amber-500/20' :\n                                  r.status === 'early-out' ? 'bg-sky-500/15 text-sky-600 border-sky-500/20' :\n                                  r.status === 'half-day' ? 'bg-orange-500/15 text-orange-600 border-orange-500/20' :\n                                  r.status === 'holiday' ? 'bg-purple-500/15 text-purple-600 border-purple-500/20' :\n                                  'bg-muted text-muted-foreground border-border'\n                                }`}>\n                                  {r.status === 'late' ? 'Late Coming' : r.status === 'early-out' ? 'Early Out' : r.status.charAt(0).toUpperCase() + r.status.slice(1)}\n                                </span>\n                              </TableCell>\n                              <TableCell className=\"text-sm whitespace-nowrap\">{formatHours(r.totalHours)}h</TableCell>\n                              <TableCell className=\"text-sm whitespace-nowrap\">{r.overtimeHours > 0 ? formatOT(r.overtimeHours) : '-'}</TableCell>\n                            </TableRow>\n                          ))\n                        )}\n                      </TableBody>\n                    </Table>\n                  </ScrollArea>\n                </CardContent>\n              </Card>\n            </div>\n          )}\n        </TabsContent>\n\n        {/* ════════════════════════════════════════════\n            ANALYTICS TAB (Professional HR Analytics)\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"analytics\" className=\"mt-4 space-y-4\">\n          {analyticsData ? (\n            <>\n              {/* ── Row 1: Key Metrics ── */}\n              <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-3\">\n                {[\n                  { title: 'Avg Check-In', value: analyticsData.attendanceAnalytics?.avgCheckInTime || 'N/A', icon: Clock, color: 'text-emerald-500', gradient: 'gradient-success', suffix: '' },\n                  { title: 'Avg Check-Out', value: analyticsData.attendanceAnalytics?.avgCheckOutTime || 'N/A', icon: Clock, color: 'text-sky-500', gradient: 'gradient-info', suffix: '' },\n                  { title: 'On-Time Arrival', value: analyticsData.attendanceAnalytics?.onTimeArrivalPct?.toFixed(1) || '0', icon: UserCheck, color: 'text-teal-500', gradient: 'gradient-success', suffix: '%' },\n                  { title: 'Attendance Rate', value: analyticsData.attendanceAnalytics?.attendanceRate?.toFixed(1) || '0', icon: Activity, color: 'text-gold', gradient: 'gradient-laxree', suffix: '%' },\n                ].map((c, i) => (\n                  <motion.div key={c.title} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>\n                    <Card className=\"glass-card card-gold-hover border-0\">\n                      <CardContent className=\"p-4 flex items-center gap-3\">\n                        <div className={`w-10 h-10 rounded-xl ${c.gradient} flex items-center justify-center shrink-0 shadow-lg`}>\n                          <c.icon className=\"w-5 h-5 text-white\" />\n                        </div>\n                        <div>\n                          <p className=\"text-[10px] text-muted-foreground font-medium\">{c.title}</p>\n                          <p className={`text-xl font-bold ${c.color}`}>\n                            {c.value}{c.suffix}\n                          </p>\n                        </div>\n                      </CardContent>\n                    </Card>\n                  </motion.div>\n                ))}\n              </div>\n\n              {/* ── Row 2: More Metrics ── */}\n              <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-3\">\n                {[\n                  { title: 'Late Arrival %', value: (analyticsData.attendanceAnalytics?.lateArrivalPct || 0).toFixed(1), icon: AlertTriangle, color: 'text-amber-500', isNegative: true },\n                  { title: 'Early Out %', value: (analyticsData.attendanceAnalytics?.earlyOutPct || 0).toFixed(1), icon: ArrowDownRight, color: 'text-sky-500', isNegative: true },\n                  { title: 'Avg Work Hours', value: (analyticsData.attendanceAnalytics?.avgWorkHours || 0).toFixed(2), icon: Timer, color: 'text-cyan-500', isNegative: false },\n                  { title: 'Absenteeism Rate', value: (analyticsData.attendanceAnalytics?.absenteeismRate || 0).toFixed(1), icon: UserX, color: 'text-red-500', isNegative: true },\n                ].map((c, i) => (\n                  <motion.div key={c.title} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: (i + 4) * 0.05 }}>\n                    <Card className=\"glass-card card-gold-hover border-0\">\n                      <CardContent className=\"p-4\">\n                        <div className=\"flex items-center justify-between mb-1\">\n                          <p className=\"text-[10px] text-muted-foreground font-medium\">{c.title}</p>\n                          <c.icon className={`w-4 h-4 ${c.color}`} />\n                        </div>\n                        <div className=\"flex items-end gap-1\">\n                          <p className={`text-2xl font-bold ${c.color}`}>{c.value}</p>\n                          <span className=\"text-xs text-muted-foreground mb-0.5\">%</span>\n                          {c.isNegative ? (\n                            <ArrowDownRight className={`w-4 h-4 ${c.color} mb-0.5`} />\n                          ) : (\n                            <ArrowUpRight className={`w-4 h-4 ${c.color} mb-0.5`} />\n                          )}\n                        </div>\n                      </CardContent>\n                    </Card>\n                  </motion.div>\n                ))}\n              </div>\n\n              {/* ── Row 3: Charts ── */}\n              <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n                {/* Gender Ratio Pie */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <Users className=\"w-4 h-4 text-gold\" />\n                      Gender Distribution\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-56\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <PieChart>\n                          <Pie\n                            data={genderPieData}\n                            dataKey=\"value\"\n                            nameKey=\"name\"\n                            cx=\"50%\"\n                            cy=\"50%\"\n                            outerRadius={80}\n                            innerRadius={45}\n                            paddingAngle={3}\n                            label={({ name, value }) => `${name}: ${value}`}\n                          >\n                            {genderPieData.map((entry: any, i: number) => (\n                              <Cell key={i} fill={entry.fill} />\n                            ))}\n                          </Pie>\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Legend iconType=\"circle\" iconSize={8} wrapperStyle={{ fontSize: '11px' }} />\n                        </PieChart>\n                      </ResponsiveContainer>\n                    </div>\n                    <div className=\"flex items-center justify-center gap-6 mt-2\">\n                      {genderPieData.map((d: any) => (\n                        <div key={d.name} className=\"text-center\">\n                          <div className=\"flex items-center gap-1.5\">\n                            <div className=\"w-2.5 h-2.5 rounded-full\" style={{ backgroundColor: d.fill }} />\n                            <span className=\"text-xs text-muted-foreground\">{d.name}</span>\n                          </div>\n                          <p className=\"text-sm font-bold\">{d.value}</p>\n                        </div>\n                      ))}\n                    </div>\n                  </CardContent>\n                </Card>\n\n                {/* On-Time vs Late Pie */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <UserCheck className=\"w-4 h-4 text-gold\" />\n                      On-Time vs Late Arrival\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-56\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <PieChart>\n                          <Pie\n                            data={onTimePieData}\n                            dataKey=\"value\"\n                            nameKey=\"name\"\n                            cx=\"50%\"\n                            cy=\"50%\"\n                            outerRadius={80}\n                            innerRadius={45}\n                            paddingAngle={3}\n                            label={({ name, value }) => `${value}%`}\n                          >\n                            {onTimePieData.map((entry: any, i: number) => (\n                              <Cell key={i} fill={entry.fill} />\n                            ))}\n                          </Pie>\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Legend iconType=\"circle\" iconSize={8} wrapperStyle={{ fontSize: '11px' }} />\n                        </PieChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n              </div>\n\n              {/* ── Row 4: Weekly Trend + Firm Analytics ── */}\n              <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n                {/* Weekly Attendance Trend */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <TrendingUp className=\"w-4 h-4 text-gold\" />\n                      Weekly Attendance Trend — {MONTHS_FULL[month - 1]} {year}\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-56\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <BarChart data={weeklyTrendData} barCategoryGap=\"20%\">\n                          <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                          <XAxis dataKey=\"week\" tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" />\n                          <YAxis tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" />\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Bar dataKey=\"present\" fill={LAXREE_COLORS.emerald} radius={[4, 4, 0, 0]} name=\"Present\" />\n                          <Bar dataKey=\"absent\" fill={LAXREE_COLORS.rose} radius={[4, 4, 0, 0]} name=\"Absent\" />\n                          <Bar dataKey=\"late\" fill={LAXREE_COLORS.amber} radius={[4, 4, 0, 0]} name=\"Late\" />\n                          <Bar dataKey=\"earlyOut\" fill={LAXREE_COLORS.sky} radius={[4, 4, 0, 0]} name=\"Early Out\" />\n                          <Legend wrapperStyle={{ fontSize: '10px' }} />\n                        </BarChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n\n                {/* Firm-wise Attendance */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <Building2 className=\"w-4 h-4 text-gold\" />\n                      Firm-wise Attendance Rate\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-56\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <BarChart data={analyticsData.firmAnalytics || []} barCategoryGap=\"25%\">\n                          <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                          <XAxis dataKey=\"firm\" tick={{ fontSize: 11 }} stroke=\"var(--muted-foreground)\" />\n                          <YAxis tick={{ fontSize: 11 }} stroke=\"var(--muted-foreground)\" domain={[0, 100]} tickFormatter={(v) => `${v}%`} />\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} formatter={(v: number) => `${v.toFixed(1)}%`} />\n                          <Bar dataKey=\"attendanceRate\" radius={[6, 6, 0, 0]} name=\"Attendance Rate\">\n                            {(analyticsData.firmAnalytics || []).map((entry: any, i: number) => (\n                              <Cell key={i} fill={FIRM_COLORS[entry.firm] || LAXREE_COLORS.gold} />\n                            ))}\n                          </Bar>\n                          <Legend wrapperStyle={{ fontSize: '10px' }} />\n                        </BarChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n              </div>\n\n              {/* ── Row 5: Employment Type + Shift Distribution ── */}\n              <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-4\">\n                {/* Employment Type */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <Users className=\"w-4 h-4 text-gold\" />\n                      Employment Type Breakdown\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-48\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <PieChart>\n                          <Pie\n                            data={empTypeData}\n                            dataKey=\"count\"\n                            nameKey=\"type\"\n                            cx=\"50%\"\n                            cy=\"50%\"\n                            outerRadius={70}\n                            innerRadius={40}\n                            paddingAngle={3}\n                          >\n                            {empTypeData.map((_: any, i: number) => (\n                              <Cell key={i} fill={[LAXREE_COLORS.gold, LAXREE_COLORS.cyan, LAXREE_COLORS.emerald, LAXREE_COLORS.violet][i % 4]} />\n                            ))}\n                          </Pie>\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Legend iconType=\"circle\" iconSize={8} wrapperStyle={{ fontSize: '11px' }} />\n                        </PieChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n\n                {/* Shift Distribution */}\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm flex items-center gap-2\">\n                      <Clock className=\"w-4 h-4 text-gold\" />\n                      Shift Distribution\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"h-48\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <BarChart data={shiftData} barCategoryGap=\"25%\">\n                          <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                          <XAxis dataKey=\"shift\" tick={{ fontSize: 9 }} stroke=\"var(--muted-foreground)\" />\n                          <YAxis tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" />\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Bar dataKey=\"count\" fill={LAXREE_COLORS.gold} radius={[6, 6, 0, 0]} name=\"Employees\" />\n                        </BarChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n              </div>\n\n              {/* ── Row 6: Avg Shift Hours Radial ── */}\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm flex items-center gap-2\">\n                    <Timer className=\"w-4 h-4 text-gold\" />\n                    Average Shift & Work Hours Summary\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-4\">\n                    <div className=\"text-center p-3 rounded-xl bg-emerald-500/10 border border-emerald-500/20\">\n                      <p className=\"text-xs text-muted-foreground mb-1\">Avg Shift Hours</p>\n                      <p className=\"text-2xl font-bold text-emerald-500\">{formatHours(analyticsData.attendanceAnalytics?.avgShiftHours || 0)}h</p>\n                      <p className=\"text-[10px] text-muted-foreground mt-1\">Scheduled</p>\n                    </div>\n                    <div className=\"text-center p-3 rounded-xl bg-cyan-500/10 border border-cyan-500/20\">\n                      <p className=\"text-xs text-muted-foreground mb-1\">Avg Work Hours</p>\n                      <p className=\"text-2xl font-bold text-cyan-500\">{formatHours(analyticsData.attendanceAnalytics?.avgWorkHours || 0)}h</p>\n                      <p className=\"text-[10px] text-muted-foreground mt-1\">Actual</p>\n                    </div>\n                    <div className=\"text-center p-3 rounded-xl bg-amber-500/10 border border-amber-500/20\">\n                      <p className=\"text-xs text-muted-foreground mb-1\">Avg Check-In</p>\n                      <p className=\"text-2xl font-bold text-amber-500\">{analyticsData.attendanceAnalytics?.avgCheckInTime || 'N/A'}</p>\n                      <p className=\"text-[10px] text-muted-foreground mt-1\">Arrival Time</p>\n                    </div>\n                    <div className=\"text-center p-3 rounded-xl bg-sky-500/10 border border-sky-500/20\">\n                      <p className=\"text-xs text-muted-foreground mb-1\">Avg Check-Out</p>\n                      <p className=\"text-2xl font-bold text-sky-500\">{analyticsData.attendanceAnalytics?.avgCheckOutTime || 'N/A'}</p>\n                      <p className=\"text-[10px] text-muted-foreground mt-1\">Departure Time</p>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n            </>\n          ) : (\n            <Card className=\"glass-card border-0\">\n              <CardContent className=\"p-12 text-center text-muted-foreground\">\n                <Activity className=\"w-10 h-10 mx-auto mb-3 opacity-30\" />\n                <p>Loading analytics data...</p>\n              </CardContent>\n            </Card>\n          )}\n        </TabsContent>\n\n        {/* ════════════════════════════════════════════\n            EVENTS TAB (Birthdays, Anniversaries, Holidays)\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"events\" className=\"mt-4 space-y-4\">\n          {eventsData ? (\n            <>\n              {/* ── Upcoming Birthdays ── */}\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm flex items-center gap-2\">\n                    <Cake className=\"w-4 h-4 text-pink-500\" />\n                    Upcoming Birthdays\n                    <Badge variant=\"outline\" className=\"text-[9px] h-4 ml-1\">{eventsData.upcomingBirthdays?.length || 0} upcoming</Badge>\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  {eventsData.upcomingBirthdays?.length > 0 ? (\n                    <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3\">\n                      {eventsData.upcomingBirthdays.map((b: any, i: number) => (\n                        <motion.div\n                          key={b.employeeId}\n                          initial={{ opacity: 0, x: -10 }}\n                          animate={{ opacity: 1, x: 0 }}\n                          transition={{ delay: i * 0.05 }}\n                          className=\"flex items-center gap-3 p-3 rounded-xl bg-gradient-to-r from-pink-500/10 to-purple-500/10 border border-pink-500/20 hover:shadow-md transition-shadow\"\n                        >\n                          <div className=\"w-10 h-10 rounded-full bg-pink-500/20 flex items-center justify-center shrink-0\">\n                            <Cake className=\"w-5 h-5 text-pink-500\" />\n                          </div>\n                          <div className=\"min-w-0 flex-1\">\n                            <p className=\"text-sm font-medium truncate\">{b.fullName}</p>\n                            <div className=\"flex items-center gap-2\">\n                              <span className=\"text-[10px] text-muted-foreground\">{b.firm}</span>\n                              {b.designation && <span className=\"text-[10px] text-muted-foreground\">· {b.designation}</span>}\n                            </div>\n                            <p className=\"text-xs text-pink-500 font-medium\">\n                              {new Date(b.birthday).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })} · {b.daysAway === 0 ? 'Today!' : `${b.daysAway} days away`}\n                            </p>\n                          </div>\n                        </motion.div>\n                      ))}\n                    </div>\n                  ) : (\n                    <p className=\"text-sm text-muted-foreground text-center py-6\">No upcoming birthdays in the next 30 days</p>\n                  )}\n                </CardContent>\n              </Card>\n\n              {/* ── Work Anniversaries ── */}\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm flex items-center gap-2\">\n                    <PartyPopper className=\"w-4 h-4 text-amber-500\" />\n                    Work Anniversaries\n                    <Badge variant=\"outline\" className=\"text-[9px] h-4 ml-1\">{eventsData.upcomingAnniversaries?.length || 0} upcoming</Badge>\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  {eventsData.upcomingAnniversaries?.length > 0 ? (\n                    <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3\">\n                      {eventsData.upcomingAnniversaries.map((a: any, i: number) => (\n                        <motion.div\n                          key={a.employeeId}\n                          initial={{ opacity: 0, x: -10 }}\n                          animate={{ opacity: 1, x: 0 }}\n                          transition={{ delay: i * 0.05 }}\n                          className=\"flex items-center gap-3 p-3 rounded-xl bg-gradient-to-r from-amber-500/10 to-gold/10 border border-amber-500/20 hover:shadow-md transition-shadow\"\n                        >\n                          <div className=\"w-10 h-10 rounded-full bg-amber-500/20 flex items-center justify-center shrink-0\">\n                            <PartyPopper className=\"w-5 h-5 text-amber-500\" />\n                          </div>\n                          <div className=\"min-w-0 flex-1\">\n                            <p className=\"text-sm font-medium truncate\">{a.fullName}</p>\n                            <div className=\"flex items-center gap-2\">\n                              <span className=\"text-[10px] text-muted-foreground\">{a.firm}</span>\n                              {a.designation && <span className=\"text-[10px] text-muted-foreground\">· {a.designation}</span>}\n                            </div>\n                            <p className=\"text-xs text-amber-500 font-medium\">\n                              {a.yearsCompleted} year{a.yearsCompleted !== 1 ? 's' : ''} · {new Date(a.anniversary).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}\n                              {a.daysAway === 0 ? ' — Today!' : ` · ${a.daysAway} days away`}\n                            </p>\n                          </div>\n                        </motion.div>\n                      ))}\n                    </div>\n                  ) : (\n                    <p className=\"text-sm text-muted-foreground text-center py-6\">No upcoming work anniversaries in the next 30 days</p>\n                  )}\n                </CardContent>\n              </Card>\n\n              {/* ── Upcoming Holidays ── */}\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm flex items-center gap-2\">\n                    <Palmtree className=\"w-4 h-4 text-emerald-500\" />\n                    Upcoming Holidays\n                    <Badge variant=\"outline\" className=\"text-[9px] h-4 ml-1\">{eventsData.upcomingHolidays?.length || 0} upcoming</Badge>\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  {eventsData.upcomingHolidays?.length > 0 ? (\n                    <div className=\"space-y-2\">\n                      {eventsData.upcomingHolidays.map((h: any, i: number) => (\n                        <motion.div\n                          key={i}\n                          initial={{ opacity: 0, x: -10 }}\n                          animate={{ opacity: 1, x: 0 }}\n                          transition={{ delay: i * 0.05 }}\n                          className=\"flex items-center gap-3 p-3 rounded-xl bg-emerald-500/5 border border-emerald-500/15 hover:shadow-md transition-shadow\"\n                        >\n                          <div className=\"w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center shrink-0\">\n                            <Palmtree className=\"w-5 h-5 text-emerald-500\" />\n                          </div>\n                          <div className=\"min-w-0 flex-1\">\n                            <p className=\"text-sm font-medium\">{h.name}</p>\n                            <div className=\"flex items-center gap-2\">\n                              <span className=\"text-xs text-muted-foreground\">{new Date(h.date).toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</span>\n                              <Badge variant=\"outline\" className=\"text-[9px] h-4\">{h.type}</Badge>\n                            </div>\n                          </div>\n                          <div className=\"text-right shrink-0\">\n                            <p className=\"text-sm font-bold text-emerald-500\">{h.daysAway === 0 ? 'Today!' : `${h.daysAway} days`}</p>\n                          </div>\n                        </motion.div>\n                      ))}\n                    </div>\n                  ) : (\n                    <p className=\"text-sm text-muted-foreground text-center py-6\">No upcoming holidays in the next 60 days</p>\n                  )}\n                </CardContent>\n              </Card>\n            </>\n          ) : (\n            <Card className=\"glass-card border-0\">\n              <CardContent className=\"p-12 text-center text-muted-foreground\">\n                <CalendarDays className=\"w-10 h-10 mx-auto mb-3 opacity-30\" />\n                <p>Loading events data...</p>\n              </CardContent>\n            </Card>\n          )}\n        </TabsContent>\n\n        {/* ════════════════════════════════════════════\n            PAYROLL TAB\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"payroll\" className=\"mt-4\">\n          {payReport && (\n            <div className=\"space-y-4\">\n              <div className=\"flex items-center gap-2\">\n                <Select value={selectedFirm} onValueChange={setSelectedFirm}>\n                  <SelectTrigger className=\"w-36 h-9\">\n                    <Building2 className=\"w-3.5 h-3.5 mr-1.5 text-muted-foreground\" />\n                    <SelectValue placeholder=\"All Firms\" />\n                  </SelectTrigger>\n                  <SelectContent>\n                    <SelectItem value=\"all\">All Firms</SelectItem>\n                    {FIRMS.map((f) => (<SelectItem key={f} value={f}>{f}</SelectItem>))}\n                  </SelectContent>\n                </Select>\n              </div>\n              <div className=\"grid grid-cols-3 gap-3\">\n                {[\n                  { title: 'Gross Total', value: `₹${(payReport.totals?.totalGross || 0).toLocaleString('en-IN')}`, color: 'text-cyan-500' },\n                  { title: 'Deductions', value: `₹${(payReport.totals?.totalDeductions || 0).toLocaleString('en-IN')}`, color: 'text-red-500' },\n                  { title: 'Net Total', value: `₹${(payReport.totals?.totalNet || 0).toLocaleString('en-IN')}`, color: 'text-gold' },\n                ].map((c, i) => (\n                  <Card key={c.title} className=\"glass-card card-gold-hover border-0\">\n                    <CardContent className=\"p-3 text-center min-w-0\"><p className=\"text-xs text-muted-foreground truncate\">{c.title}</p><p className={`text-xl font-bold ${c.color}`}>{c.value}</p></CardContent>\n                  </Card>\n                ))}\n              </div>\n\n              {payReport.deptBreakdown && Object.keys(payReport.deptBreakdown).length > 0 && (\n                <Card className=\"glass-card card-gold-hover border-0\">\n                  <CardHeader className=\"pb-2\"><CardTitle className=\"text-sm\">Firm-wise Payroll Breakdown</CardTitle></CardHeader>\n                  <CardContent>\n                    <div className=\"h-52\">\n                      <ResponsiveContainer width=\"100%\" height=\"100%\">\n                        <BarChart data={Object.entries(payReport.deptBreakdown).map(([dept, data]: [string, any]) => ({ department: dept, net: data.totalNet, fill: FIRM_COLORS[dept] || LAXREE_COLORS.gold }))}>\n                          <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                          <XAxis dataKey=\"department\" tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" />\n                          <YAxis tick={{ fontSize: 10 }} stroke=\"var(--muted-foreground)\" tickFormatter={(v) => `₹${(v / 1000).toFixed(0)}k`} />\n                          <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                          <Bar dataKey=\"net\" radius={[4, 4, 0, 0]} name=\"Net Payroll\">\n                            {Object.entries(payReport.deptBreakdown).map(([dept], i) => (\n                              <Cell key={i} fill={FIRM_COLORS[dept] || LAXREE_COLORS.gold} />\n                            ))}\n                          </Bar>\n                        </BarChart>\n                      </ResponsiveContainer>\n                    </div>\n                  </CardContent>\n                </Card>\n              )}\n\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardContent className=\"p-0\">\n                  <ScrollArea className=\"max-h-[40vh]\">\n                    <Table>\n                      <TableHeader><TableRow><TableHead>Employee</TableHead><TableHead>Firm</TableHead><TableHead>Gross</TableHead><TableHead>Deductions</TableHead><TableHead>Net</TableHead></TableRow></TableHeader>\n                      <TableBody>\n                        {filteredPayrolls.map((p: any) => (\n                          <TableRow key={p.id} className=\"hover:bg-muted/30\">\n                            <TableCell className=\"text-sm truncate max-w-[150px]\">{p.employee?.fullName || p.employeeId}</TableCell>\n                            <TableCell><FirmBadge firm={p.employee?.department || ''} /></TableCell>\n                            <TableCell className=\"text-sm whitespace-nowrap\">₹{p.grossSalary.toLocaleString('en-IN')}</TableCell>\n                            <TableCell className=\"text-sm text-red-500 whitespace-nowrap\">₹{p.totalDeductions.toLocaleString('en-IN')}</TableCell>\n                            <TableCell className=\"text-sm font-bold text-gold whitespace-nowrap\">₹{p.netSalary.toLocaleString('en-IN')}</TableCell>\n                          </TableRow>\n                        ))}\n                      </TableBody>\n                    </Table>\n                  </ScrollArea>\n                </CardContent>\n              </Card>\n            </div>\n          )}\n        </TabsContent>\n\n        {/* ════════════════════════════════════════════\n            FIRM-WISE TAB\n        ════════════════════════════════════════════ */}\n        <TabsContent value=\"firm-wise\" className=\"mt-4 space-y-4\">\n          {dashboardData && (\n            <>\n              <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-3\">\n                {dashboardData.firmWiseCount?.map((f: any, i: number) => (\n                  <motion.div key={f.firm} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }}>\n                    <Card className=\"glass-card card-gold-hover border-0\">\n                      <CardContent className=\"p-4\">\n                        <div className=\"flex items-center gap-2 mb-2\">\n                          <div className=\"w-3 h-3 rounded-full\" style={{ backgroundColor: FIRM_COLORS[f.firm] || LAXREE_COLORS.gold }} />\n                          <FirmBadge firm={f.firm} />\n                        </div>\n                        <div className=\"text-2xl font-bold\">{f.count}</div>\n                        <p className=\"text-xs text-muted-foreground\">employees</p>\n                        <div className=\"mt-2 text-sm font-medium\">\n                          Payroll: ₹{(dashboardData.firmPayrollBreakdown?.[f.firm]?.totalNet || 0).toLocaleString('en-IN')}\n                        </div>\n                      </CardContent>\n                    </Card>\n                  </motion.div>\n                ))}\n              </div>\n\n              <Card className=\"glass-card card-gold-hover border-0\">\n                <CardHeader className=\"pb-2\"><CardTitle className=\"text-sm flex items-center gap-2\"><Building2 className=\"w-4 h-4 text-gold\" /> Firm-wise Employee & Payroll Distribution</CardTitle></CardHeader>\n                <CardContent>\n                  <div className=\"h-64\">\n                    <ResponsiveContainer width=\"100%\" height=\"100%\">\n                      <BarChart data={firmPayrollData} barCategoryGap=\"20%\">\n                        <CartesianGrid strokeDasharray=\"3 3\" stroke=\"var(--border)\" />\n                        <XAxis dataKey=\"firm\" tick={{ fontSize: 11 }} stroke=\"var(--muted-foreground)\" />\n                        <YAxis yAxisId=\"left\" tick={{ fontSize: 11 }} stroke=\"var(--muted-foreground)\" />\n                        <YAxis yAxisId=\"right\" orientation=\"right\" tick={{ fontSize: 11 }} stroke=\"var(--muted-foreground)\" tickFormatter={(v) => `₹${(v / 1000).toFixed(0)}k`} />\n                        <Tooltip contentStyle={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: 12 }} />\n                        <Bar yAxisId=\"left\" dataKey=\"employees\" fill={LAXREE_COLORS.gold} radius={[4, 4, 0, 0]} name=\"Employees\" />\n                        <Bar yAxisId=\"right\" dataKey=\"payroll\" radius={[4, 4, 0, 0]} name=\"Payroll (₹)\">\n                          {firmPayrollData.map((entry: any, i: number) => (<Cell key={i} fill={entry.fill} />))}\n                        </Bar>\n     