tle } from '@/components/ui/card';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';\nimport { useHRMSStore } from '@/lib/store';\nimport { toast } from 'sonner';\n\n// ── Color System ──\nconst COLORS = {\n  gold: '#D4A849',\n  teal: '#14B8A6',\n  cyan: '#06B6D4',\n  amber: '#F59E0B',\n  rose: '#F43F5E',\n  violet: '#8B5CF6',\n  emerald: '#10B981',\n  sky: '#0EA5E9',\n  lime: '#84CC16',\n  pink: '#EC4899',\n};\n\nconst FIRM_COLORS: Record<string, string> = {\n  LAPL: COLORS.gold,\n  LRSL: COLORS.cyan,\n  SI: COLORS.amber,\n  SDF: COLORS.violet,\n};\n\nconst MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];\n\n// ── Types ──\ninterface EmployeePerf {\n  employeeId: string;\n  fullName: string;\n  firm: string;\n  location: string;\n  designation: string;\n  shiftHours: number;\n  totalDays: number;\n  presentDays: number;\n  absentDays: number;\n  lateDays: number;\n  halfDays: number;\n  earlyOutDays: number;\n  onTimeDays: number;\n  overtimeDays: number;\n  totalOvertimeHours: number;\n  totalWorkHours: number;\n  attendanceRate: number;\n  punctualityRate: number;\n  consistencyScore: number;\n  avgWorkHours: number;\n  weeklyData: { week: number; present: number; absent: number; late: number; onTime: number }[];\n  variance?: number;\n}\n\ninterface AnalyticsData {\n  month: number;\n  year: number;\n  workingDays: number;\n  totalEmployees: number;\n  summary: {\n    avgAttendanceRate: number;\n    avgPunctualityRate: number;\n    avgConsistencyScore: number;\n    totalAbsenteeism: number;\n  };\n  topPerformers: EmployeePerf[];\n  mostPunctual: EmployeePerf[];\n  irregularEmployees: EmployeePerf[];\n  inconsistentEmployees: EmployeePerf[];\n  mostOvertime: EmployeePerf[];\n  weeklyTrend: { week: string; weekNum: number; period: string; present: number; absent: number; late: number; onTime: number; halfDay: number }[];\n  firmWisePerformance: { firm: string; employees: number; avgAttendance: number; avgPunctuality: number; avgConsistency: number }[];\n  allEmployees: EmployeePerf[];\n}\n\n// ── Score Badge Component ──\nfunction ScoreBadge({ score, size = 'md' }: { score: number; size?: 'sm' | 'md' | 'lg' }) {\n  const sizeClasses = { sm: 'text-xs px-1.5 py-0.5', md: 'text-xs px-2 py-1', lg: 'text-sm px-3 py-1.5' };\n  let bg = 'bg-emerald-500/20 text-emerald-400';\n  if (score < 50) bg = 'bg-rose-500/20 text-rose-400';\n  else if (score < 75) bg = 'bg-amber-500/20 text-amber-400';\n  return <span className={`rounded-full font-bold ${sizeClasses[size]} ${bg}`}>{score.toFixed(0)}%</span>;\n}\n\n// ── Rank Badge ──\nfunction RankBadge({ rank }: { rank: number }) {\n  if (rank === 1) return <span className=\"text-lg\">🥇</span>;\n  if (rank === 2) return <span className=\"text-lg\">🥈</span>;\n  if (rank === 3) return <span className=\"text-lg\">🥉</span>;\n  return <span className=\"text-xs text-muted-foreground font-bold\">#{rank}</span>;\n}\n\n// ── Progress Bar ──\nfunction ProgressBar({ value, max = 100, color = COLORS.gold }: { value: number; max?: number; color?: string }) {\n  const pct = Math.min((value / max) * 100, 100);\n  return (\n    <div className=\"w-full h-2 bg-white/5 rounded-full overflow-hidden\">\n      <motion.div\n        initial={{ width: 0 }}\n        animate={{ width: `${pct}%` }}\n        transition={{ duration: 0.8, ease: 'easeOut' }}\n        className=\"h-full rounded-full\"\n        style={{ backgroundColor: color }}\n      />\n    </div>\n  );\n}\n\nexport function AnalyticsDashboard() {\n  const { selectedFirm } = useHRMSStore();\n  const [data, setData] = useState<AnalyticsData | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [month, setMonth] = useState(new Date().getMonth() + 1);\n  const [year, setYear] = useState(new Date().getFullYear());\n  const [activeTab, setActiveTab] = useState('overview');\n\n  const fetchData = useCallback(async () => {\n    setLoading(true);\n    try {\n      const params = new URLSearchParams({ month: String(month), year: String(year) });\n      if (selectedFirm && selectedFirm !== '__all__') params.set('firm', selectedFirm);\n      const res = await fetch(`/api/analytics/performance?${params}`);\n      if (res.ok) {\n        const json = await res.json();\n        setData(json);\n      } else {\n        toast.error('Failed to load analytics');\n      }\n    } catch {\n      toast.error('Network error');\n    } finally {\n      setLoading(false);\n    }\n  }, [month, year, selectedFirm]);\n\n  useEffect(() => { fetchData(); }, [fetchData]);\n\n  if (loading || !data) {\n    return (\n      <div className=\"flex items-center justify-center h-[60vh]\">\n        <div className=\"flex flex-col items-center gap-3\">\n          <div className=\"w-8 h-8 border-2 border-gold border-t-transparent rounded-full animate-spin\" />\n          <span className=\"text-sm text-muted-foreground\">Loading Analytics...</span>\n        </div>\n      </div>\n    );\n  }\n\n  const { summary, workingDays } = data;\n\n  return (\n    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className=\"space-y-6\">\n      {/* Header */}\n      <div className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n        <div>\n          <h1 className=\"text-2xl font-bold flex items-center gap-2\">\n            <TrendingUp className=\"w-6 h-6 text-gold\" />\n            Attendance Analytics\n          </h1>\n          <p className=\"text-sm text-muted-foreground mt-1\">\n            Track performance, punctuality & consistency — {MONTHS[month - 1]} {year} ({workingDays} working days)\n          </p>\n        </div>\n        <div className=\"flex gap-2 flex-wrap\">\n          <Select value={String(month)} onValueChange={(v) => setMonth(Number(v))}>\n            <SelectTrigger className=\"w-[140px]\"><SelectValue /></SelectTrigger>\n            <SelectContent>\n              {MONTHS.map((m, i) => <SelectItem key={i} value={String(i + 1)}>{m}</SelectItem>)}\n            </SelectContent>\n          </Select>\n          <Select value={String(year)} onValueChange={(v) => setYear(Number(v))}>\n            <SelectTrigger className=\"w-[100px]\"><SelectValue /></SelectTrigger>\n            <SelectContent>\n              {[2025, 2026, 2027].map(y => <SelectItem key={y} value={String(y)}>{y}</SelectItem>)}\n            </SelectContent>\n          </Select>\n        </div>\n      </div>\n\n      {/* KPI Cards */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-4 gap-4\">\n        {[\n          { label: 'Avg Attendance', value: `${summary.avgAttendanceRate}%`, icon: Users, color: COLORS.emerald, sub: `${data.totalEmployees} employees` },\n          { label: 'Avg Punctuality', value: `${summary.avgPunctualityRate}%`, icon: Target, color: COLORS.teal, sub: 'On-time arrival' },\n          { label: 'Consistency Score', value: `${summary.avgConsistencyScore}%`, icon: Zap, color: COLORS.gold, sub: 'Attendance × Punctuality' },\n          { label: 'Total Absenteeism', value: `${summary.totalAbsenteeism}`, icon: AlertTriangle, color: COLORS.rose, sub: 'Absence instances' },\n        ].map((kpi, i) => (\n          <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.1 }}>\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-4\">\n                <div className=\"flex items-center justify-between mb-2\">\n                  <span className=\"text-xs text-muted-foreground font-medium\">{kpi.label}</span>\n                  <div className=\"p-1.5 rounded-lg\" style={{ backgroundColor: `${kpi.color}20` }}>\n                    <kpi.icon className=\"w-4 h-4\" style={{ color: kpi.color }} />\n                  </div>\n                </div>\n                <p className=\"text-2xl font-bold\" style={{ color: kpi.color }}>{kpi.value}</p>\n                <p className=\"text-xs text-muted-foreground mt-1\">{kpi.sub}</p>\n              </CardContent>\n            </Card>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Main Tabs */}\n      <Tabs value={activeTab} onValueChange={setActiveTab}>\n        <TabsList className=\"bg-white/5 border border-white/10\">\n          <TabsTrigger value=\"overview\">Overview</TabsTrigger>\n          <TabsTrigger value=\"top-performers\">Top Performers</TabsTrigger>\n          <TabsTrigger value=\"punctuality\">Punctuality</TabsTrigger>\n          <TabsTrigger value=\"irregular\">Irregular</TabsTrigger>\n          <TabsTrigger value=\"inconsistent\">Inconsistency</TabsTrigger>\n          <TabsTrigger value=\"overtime\">Overtime</TabsTrigger>\n        </TabsList>\n\n        {/* ── Overview Tab ── */}\n        <TabsContent value=\"overview\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Weekly Trend Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <BarChart3 className=\"w-4 h-4 text-gold\" />\n                  Weekly Attendance Trend\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <ResponsiveContainer width=\"100%\" height={280}>\n                  <BarChart data={data.weeklyTrend}>\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                    <XAxis dataKey=\"week\" tick={{ fill: '#888', fontSize: 11 }} />\n                    <YAxis tick={{ fill: '#888', fontSize: 11 }} />\n                    <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    <Bar dataKey=\"onTime\" name=\"On Time\" stackId=\"a\" fill={COLORS.emerald} radius={[0, 0, 0, 0]} />\n                    <Bar dataKey=\"late\" name=\"Late\" stackId=\"a\" fill={COLORS.amber} />\n                    <Bar dataKey=\"absent\" name=\"Absent\" stackId=\"a\" fill={COLORS.rose} radius={[4, 4, 0, 0]} />\n                    <Legend />\n                  </BarChart>\n                </ResponsiveContainer>\n              </CardContent>\n            </Card>\n\n            {/* Firm-wise Performance */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Award className=\"w-4 h-4 text-gold\" />\n                  Firm-wise Performance\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                {data.firmWisePerformance.length > 0 ? (\n                  <ResponsiveContainer width=\"100%\" height={280}>\n                    <RadarChart data={data.firmWisePerformance}>\n                      <PolarGrid stroke=\"rgba(255,255,255,0.1)\" />\n                      <PolarAngleAxis dataKey=\"firm\" tick={{ fill: '#aaa', fontSize: 12 }} />\n                      <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fill: '#888', fontSize: 10 }} />\n                      <Radar name=\"Attendance\" dataKey=\"avgAttendance\" stroke={COLORS.emerald} fill={COLORS.emerald} fillOpacity={0.2} />\n                      <Radar name=\"Punctuality\" dataKey=\"avgPunctuality\" stroke={COLORS.teal} fill={COLORS.teal} fillOpacity={0.2} />\n                      <Radar name=\"Consistency\" dataKey=\"avgConsistency\" stroke={COLORS.gold} fill={COLORS.gold} fillOpacity={0.2} />\n                      <Legend />\n                      <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    </RadarChart>\n                  </ResponsiveContainer>\n                ) : (\n                  <div className=\"flex items-center justify-center h-[280px] text-sm text-muted-foreground\">No firm data available</div>\n                )}\n              </CardContent>\n            </Card>\n\n            {/* Top 5 Performers Quick View */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Trophy className=\"w-4 h-4 text-gold\" />\n                  Top 5 Performers\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-3\">\n                {data.topPerformers.slice(0, 5).map((emp, i) => (\n                  <div key={emp.employeeId} className=\"flex items-center gap-3\">\n                    <RankBadge rank={i + 1} />\n                    <div className=\"flex-1 min-w-0\">\n                      <div className=\"flex items-center justify-between\">\n                        <span className=\"text-sm font-medium truncate\">{emp.fullName}</span>\n                        <ScoreBadge score={emp.consistencyScore} />\n                      </div>\n                      <ProgressBar value={emp.consistencyScore} color={COLORS.gold} />\n                      <div className=\"flex gap-3 mt-1 text-[10px] text-muted-foreground\">\n                        <span>Attendance: {emp.attendanceRate}%</span>\n                        <span>Punctual: {emp.punctualityRate}%</span>\n                        <span className=\"text-muted-foreground/60\">{emp.firm}</span>\n                      </div>\n                    </div>\n                  </div>\n                ))}\n              </CardContent>\n            </Card>\n\n            {/* Attendance vs Punctuality Distribution */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Target className=\"w-4 h-4 text-gold\" />\n                  Employee Distribution\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                {(() => {\n                  const excellent = data.allEmployees.filter(e => e.consistencyScore >= 80).length;\n                  const good = data.allEmployees.filter(e => e.consistencyScore >= 60 && e.consistencyScore < 80).length;\n                  const average = data.allEmployees.filter(e => e.consistencyScore >= 40 && e.consistencyScore < 60).length;\n                  const poor = data.allEmployees.filter(e => e.consistencyScore < 40).length;\n                  const pieData = [\n                    { name: 'Excellent (80+)', value: excellent, color: COLORS.emerald },\n                    { name: 'Good (60-79)', value: good, color: COLORS.teal },\n                    { name: 'Average (40-59)', value: average, color: COLORS.amber },\n                    { name: 'Poor (<40)', value: poor, color: COLORS.rose },\n                  ].filter(d => d.value > 0);\n                  return pieData.length > 0 ? (\n                    <ResponsiveContainer width=\"100%\" height={280}>\n                      <PieChart>\n                        <Pie data={pieData} cx=\"50%\" cy=\"50%\" innerRadius={60} outerRadius={100} dataKey=\"value\" label={({ name, value }) => `${name}: ${value}`}>\n                          {pieData.map((entry, i) => <Cell key={i} fill={entry.color} />)}\n                        </Pie>\n                        <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                        <Legend />\n                      </PieChart>\n                    </ResponsiveContainer>\n                  ) : (\n                    <div className=\"flex items-center justify-center h-[280px] text-sm text-muted-foreground\">No data available</div>\n                  );\n                })()}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n\n        {/* ── Top Performers Tab ── */}\n        <TabsContent value=\"top-performers\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Top Performers Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Trophy className=\"w-4 h-4 text-gold\" />\n                  Top 10 — Consistency Score\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <ResponsiveContainer width=\"100%\" height={350}>\n                  <BarChart data={data.topPerformers.map(e => ({ name: e.fullName.split(' ')[0], score: e.consistencyScore, attendance: e.attendanceRate, punctuality: e.punctualityRate }))} layout=\"vertical\">\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                    <XAxis type=\"number\" domain={[0, 100]} tick={{ fill: '#888', fontSize: 11 }} />\n                    <YAxis type=\"category\" dataKey=\"name\" width={80} tick={{ fill: '#ccc', fontSize: 11 }} />\n                    <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    <Bar dataKey=\"score\" name=\"Consistency\" fill={COLORS.gold} radius={[0, 4, 4, 0]} />\n                    <Bar dataKey=\"attendance\" name=\"Attendance\" fill={COLORS.emerald} radius={[0, 4, 4, 0]} />\n                    <Bar dataKey=\"punctuality\" name=\"Punctuality\" fill={COLORS.teal} radius={[0, 4, 4, 0]} />\n                    <Legend />\n                  </BarChart>\n                </ResponsiveContainer>\n              </CardContent>\n            </Card>\n\n            {/* Top Performers List */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Award className=\"w-4 h-4 text-gold\" />\n                  Top Performers — Detailed\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-2 max-h-[400px] overflow-y-auto\">\n                {data.topPerformers.map((emp, i) => (\n                  <motion.div key={emp.employeeId} initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.05 }}\n                    className=\"flex items-center gap-3 p-3 rounded-xl bg-white/[0.03] hover:bg-white/[0.06] transition-colors\"\n                  >\n                    <RankBadge rank={i + 1} />\n                    <div className=\"flex-1 min-w-0\">\n                      <div className=\"flex items-center justify-between\">\n                        <div>\n                          <span className=\"text-sm font-semibold\">{emp.fullName}</span>\n                          <span className=\"text-xs text-muted-foreground ml-2\">{emp.employeeId}</span>\n                        </div>\n                        <ScoreBadge score={emp.consistencyScore} />\n                      </div>\n                      <ProgressBar value={emp.consistencyScore} color={COLORS.gold} />\n                      <div className=\"flex gap-4 mt-1.5 text-[10px] text-muted-foreground\">\n                        <span className=\"flex items-center gap-1\"><ArrowUpRight className=\"w-3 h-3 text-emerald-400\" />Present: {emp.presentDays}/{emp.totalDays}</span>\n                        <span className=\"flex items-center gap-1\"><Clock className=\"w-3 h-3 text-teal-400\" />On-time: {emp.onTimeDays}</span>\n                        <span className=\"flex items-center gap-1\"><AlertTriangle className=\"w-3 h-3 text-amber-400\" />Late: {emp.lateDays}</span>\n                        <span>{emp.firm}</span>\n                      </div>\n                    </div>\n                  </motion.div>\n                ))}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n\n        {/* ── Punctuality Tab ── */}\n        <TabsContent value=\"punctuality\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Punctuality Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Clock className=\"w-4 h-4 text-teal\" />\n                  Most Punctual Employees\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <ResponsiveContainer width=\"100%\" height={350}>\n                  <BarChart data={data.mostPunctual.map(e => ({ name: e.fullName.split(' ')[0], onTime: e.punctualityRate, late: 100 - e.punctualityRate }))}>\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                    <XAxis dataKey=\"name\" tick={{ fill: '#888', fontSize: 11 }} />\n                    <YAxis domain={[0, 100]} tick={{ fill: '#888', fontSize: 11 }} />\n                    <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    <Bar dataKey=\"onTime\" name=\"On Time %\" stackId=\"a\" fill={COLORS.teal} radius={[4, 4, 0, 0]} />\n                    <Bar dataKey=\"late\" name=\"Late %\" stackId=\"a\" fill={COLORS.rose} radius={[4, 4, 0, 0]} />\n                    <Legend />\n                  </BarChart>\n                </ResponsiveContainer>\n              </CardContent>\n            </Card>\n\n            {/* Punctual List */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Timer className=\"w-4 h-4 text-teal\" />\n                  Punctuality Rankings\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-2 max-h-[400px] overflow-y-auto\">\n                {data.mostPunctual.map((emp, i) => (\n                  <div key={emp.employeeId} className=\"flex items-center gap-3 p-3 rounded-xl bg-white/[0.03] hover:bg-white/[0.06] transition-colors\">\n                    <RankBadge rank={i + 1} />\n                    <div className=\"flex-1 min-w-0\">\n                      <div className=\"flex items-center justify-between\">\n                        <div>\n                          <span className=\"text-sm font-semibold\">{emp.fullName}</span>\n                          <span className=\"text-xs text-muted-foreground ml-2\">{emp.employeeId}</span>\n                        </div>\n                        <ScoreBadge score={emp.punctualityRate} />\n                      </div>\n                      <ProgressBar value={emp.punctualityRate} color={COLORS.teal} />\n                      <div className=\"flex gap-4 mt-1.5 text-[10px] text-muted-foreground\">\n                        <span className=\"text-emerald-400\">On-time: {emp.onTimeDays} days</span>\n                        <span className=\"text-amber-400\">Late: {emp.lateDays} days</span>\n                        <span>Present: {emp.presentDays}/{emp.totalDays}</span>\n                        <span>{emp.firm}</span>\n                      </div>\n                    </div>\n                  </div>\n                ))}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n\n        {/* ── Irregular / Absentees Tab ── */}\n        <TabsContent value=\"irregular\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Absenteeism Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <UserX className=\"w-4 h-4 text-rose\" />\n                  Most Absent Employees\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <ResponsiveContainer width=\"100%\" height={350}>\n                  <BarChart data={data.irregularEmployees.map(e => ({ name: e.fullName.split(' ')[0], absent: e.absentDays, present: e.presentDays }))} layout=\"vertical\">\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                    <XAxis type=\"number\" tick={{ fill: '#888', fontSize: 11 }} />\n                    <YAxis type=\"category\" dataKey=\"name\" width={80} tick={{ fill: '#ccc', fontSize: 11 }} />\n                    <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    <Bar dataKey=\"present\" name=\"Present\" stackId=\"a\" fill={COLORS.emerald} />\n                    <Bar dataKey=\"absent\" name=\"Absent\" stackId=\"a\" fill={COLORS.rose} radius={[0, 4, 4, 0]} />\n                    <Legend />\n                  </BarChart>\n                </ResponsiveContainer>\n              </CardContent>\n            </Card>\n\n            {/* Irregular List */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <AlertTriangle className=\"w-4 h-4 text-rose\" />\n                  Irregular Attendance — Detailed\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-2 max-h-[400px] overflow-y-auto\">\n                {data.irregularEmployees.map((emp, i) => (\n                  <div key={emp.employeeId} className=\"flex items-center gap-3 p-3 rounded-xl bg-white/[0.03] hover:bg-white/[0.06] transition-colors\">\n                    <div className=\"flex flex-col items-center w-8\">\n                      <span className=\"text-rose-400 text-lg font-bold\">{emp.absentDays}</span>\n                      <span className=\"text-[9px] text-muted-foreground\">absent</span>\n                    </div>\n                    <div className=\"flex-1 min-w-0\">\n                      <div className=\"flex items-center justify-between\">\n                        <div>\n                          <span className=\"text-sm font-semibold\">{emp.fullName}</span>\n                          <span className=\"text-xs text-muted-foreground ml-2\">{emp.employeeId}</span>\n                        </div>\n                        <ScoreBadge score={emp.attendanceRate} />\n                      </div>\n                      <ProgressBar value={emp.attendanceRate} color={COLORS.rose} />\n                      <div className=\"flex gap-4 mt-1.5 text-[10px] text-muted-foreground\">\n                        <span className=\"text-emerald-400\">Present: {emp.presentDays}</span>\n                        <span className=\"text-rose-400\">Absent: {emp.absentDays}</span>\n                        <span className=\"text-amber-400\">Late: {emp.lateDays}</span>\n                        <span>Rate: {emp.attendanceRate}%</span>\n                        <span>{emp.firm}</span>\n                      </div>\n                    </div>\n                  </div>\n                ))}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n\n        {/* ── Inconsistency Tab ── */}\n        <TabsContent value=\"inconsistent\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Weekly Variance Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Zap className=\"w-4 h-4 text-amber\" />\n                  Attendance Inconsistency\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <ResponsiveContainer width=\"100%\" height={350}>\n                  <BarChart data={data.inconsistentEmployees.map(e => ({ name: e.fullName.split(' ')[0], variance: e.variance || 0 }))}>\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                    <XAxis dataKey=\"name\" tick={{ fill: '#888', fontSize: 11 }} />\n                    <YAxis tick={{ fill: '#888', fontSize: 11 }} label={{ value: 'Variance', angle: -90, position: 'insideLeft', fill: '#888', fontSize: 11 }} />\n                    <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                    <Bar dataKey=\"variance\" name=\"Weekly Variance\" fill={COLORS.amber} radius={[4, 4, 0, 0]} />\n                  </BarChart>\n                </ResponsiveContainer>\n              </CardContent>\n            </Card>\n\n            {/* Inconsistent List with Weekly Trend */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Zap className=\"w-4 h-4 text-amber\" />\n                  Inconsistent Employees — Weekly Breakdown\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-3 max-h-[400px] overflow-y-auto\">\n                {data.inconsistentEmployees.map((emp, i) => (\n                  <div key={emp.employeeId} className=\"p-3 rounded-xl bg-white/[0.03] hover:bg-white/[0.06] transition-colors\">\n                    <div className=\"flex items-center justify-between mb-2\">\n                      <div>\n                        <span className=\"text-sm font-semibold\">{emp.fullName}</span>\n                        <span className=\"text-xs text-muted-foreground ml-2\">{emp.employeeId} · {emp.firm}</span>\n                      </div>\n                      <span className=\"text-xs px-2 py-1 rounded-full bg-amber-500/20 text-amber-400 font-bold\">Variance: {emp.variance}</span>\n                    </div>\n                    {/* Mini weekly trend */}\n                    {emp.weeklyData.length > 1 && (\n                      <div className=\"mt-2\">\n                        <ResponsiveContainer width=\"100%\" height={60}>\n                          <AreaChart data={emp.weeklyData.map(w => ({ week: `W${w.week}`, days: w.present }))}>\n                            <XAxis dataKey=\"week\" tick={{ fill: '#888', fontSize: 9 }} axisLine={false} tickLine={false} />\n                            <Area type=\"monotone\" dataKey=\"days\" stroke={COLORS.amber} fill={`${COLORS.amber}30`} strokeWidth={2} />\n                          </AreaChart>\n                        </ResponsiveContainer>\n                        <div className=\"flex gap-3 text-[9px] text-muted-foreground mt-1\">\n                          {emp.weeklyData.map(w => (\n                            <span key={w.week}>W{w.week}: {w.present}P / {w.absent}A</span>\n                          ))}\n                        </div>\n                      </div>\n                    )}\n                  </div>\n                ))}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n\n        {/* ── Overtime Tab ── */}\n        <TabsContent value=\"overtime\" className=\"space-y-6 mt-4\">\n          <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n            {/* Overtime Chart */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Clock className=\"w-4 h-4 text-violet\" />\n                  Most Overtime Hours\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                {data.mostOvertime.length > 0 ? (\n                  <ResponsiveContainer width=\"100%\" height={350}>\n                    <BarChart data={data.mostOvertime.map(e => ({ name: e.fullName.split(' ')[0], otHours: e.totalOvertimeHours, otDays: e.overtimeDays }))} layout=\"vertical\">\n                      <CartesianGrid strokeDasharray=\"3 3\" stroke=\"rgba(255,255,255,0.05)\" />\n                      <XAxis type=\"number\" tick={{ fill: '#888', fontSize: 11 }} />\n                      <YAxis type=\"category\" dataKey=\"name\" width={80} tick={{ fill: '#ccc', fontSize: 11 }} />\n                      <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                      <Bar dataKey=\"otHours\" name=\"OT Hours\" fill={COLORS.violet} radius={[0, 4, 4, 0]} />\n                      <Legend />\n                    </BarChart>\n                  </ResponsiveContainer>\n                ) : (\n                  <div className=\"flex items-center justify-center h-[350px] text-sm text-muted-foreground\">No overtime data this month</div>\n                )}\n              </CardContent>\n            </Card>\n\n            {/* Overtime List */}\n            <Card className=\"glass-card border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <Clock className=\"w-4 h-4 text-violet\" />\n                  Overtime Rankings\n                </CardTitle>\n              </CardHeader>\n              <CardContent className=\"space-y-2 max-h-[400px] overflow-y-auto\">\n                {data.mostOvertime.length > 0 ? data.mostOvertime.map((emp, i) => (\n                  <div key={emp.employeeId} className=\"flex items-center gap-3 p-3 rounded-xl bg-white/[0.03] hover:bg-white/[0.06] transition-colors\">\n                    <RankBadge rank={i + 1} />\n                    <div className=\"flex-1 min-w-0\">\n                      <div className=\"flex items-center justify-between\">\n                        <div>\n                          <span className=\"text-sm font-semibold\">{emp.fullName}</span>\n                          <span className=\"text-xs text-muted-foreground ml-2\">{emp.employeeId}</span>\n                        </div>\n                        <span className=\"text-xs px-2 py-1 rounded-full bg-violet-500/20 text-violet-400 font-bold\">{emp.totalOvertimeHours}h OT</span>\n                      </div>\n                      <div className=\"flex gap-4 mt-1.5 text-[10px] text-muted-foreground\">\n                        <span>OT Days: {emp.overtimeDays}</span>\n                        <span>Avg Hours: {emp.avgWorkHours}h</span>\n                        <span>Present: {emp.presentDays}/{emp.totalDays}</span>\n                        <span>{emp.firm}</span>\n                      </div>\n                    </div>\n                  </div>\n                )) : (\n                  <div className=\"text-sm text-muted-foreground text-center py-8\">No overtime data this month</div>\n                )}\n              </CardContent>\n            </Card>\n          </div>\n        </TabsContent>\n      </Tabs>\n    </motion.div>\n  );\n}\n","'use client';\n\nimport { useState, useEffect, useCallback } from 'react';\nimport { motion } from 'framer-motion';\nimport {\n  CreditCard, Trophy, AlertTriangle, CheckCircle, Shield, Star,\n  Clock, Users, TrendingUp, ChevronDown, ChevronUp, Award,\n  ShieldCheck, ShieldAlert, ShieldX, Info, ArrowLeft\n} from 'lucide-react';\nimport {\n  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,\n  PieChart, Pie, Cell, Legend, RadarChart, PolarGrid, PolarAngleAxis,\n  PolarRadiusAxis, Radar,\n} from 'recharts';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Input } from '@/components/ui/input';\nimport { useHRMSStore } from '@/lib/store';\nimport { toast } from 'sonner';\n\nconst COLORS = {\n  gold: '#D4A849', teal: '#14B8A6', cyan: '#06B6D4', amber: '#F59E0B',\n  rose: '#F43F5E', violet: '#8B5CF6', emerald: '#10B981', sky: '#0EA5E9',\n};\n\nconst RATING_COLORS: Record<number, string> = {\n  5: COLORS.emerald, 4: COLORS.teal, 3: COLORS.amber, 2: COLORS.rose, 1: '#EF4444',\n};\n\nconst MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];\n\ninterface Scorecard {\n  employeeId: string; fullName: string; firm: string; location: string; designation: string;\n  shiftStart: string; shiftEnd: string; workingDays: number; presentDays: number;\n  absentDays: number; onTimeDays: number; lateDays: number; halfDays: number;\n  earlyOutDays: number; uninformedLeaveDays: number; overtimeDays: number;\n  totalOvertimeHours: number; totalWorkHours: number; sundayWorkingDays: number;\n  attendanceRate: number; punctualityRate: number; disciplineRating: number;\n  overallRating: number; isExcellenceEligible: boolean;\n  lateInstances: { date: string; checkIn: string; minutesLate: number }[];\n  earlyOutInstances: { date: string; checkOut: string }[];\n  alerts: { type: 'danger' | 'warning' | 'success' | 'info'; message: string }[];\n  insights: string[];\n}\n\ninterface ScorecardData {\n  month: number; year: number; workingDays: number; totalWorkingDays: number; isLiveMonth: boolean; dataUptoDay: number; officialTime: string; graceMinutes: number;\n  summary: { totalEmployees: number; avgRating: number; perfectAttendance: number; atRisk: number; excellenceEligible: number };\n  deptCompliance: { firm: string; employees: number; punctualityCompliance: number; attendanceCompliance: number; avgRating: number }[];\n  scorecards: Scorecard[];\n}\n\n// ── Rating Stars ──\nfunction RatingStars({ rating, size = 20 }: { rating: number; size?: number }) {\n  return (\n    <div className=\"flex items-center gap-0.5\">\n      {[1, 2, 3, 4, 5].map(i => (\n        <Star key={i} size={size} className={i <= rating ? 'fill-current' : ''} style={{ color: i <= rating ? RATING_COLORS[rating] : '#333' }} />\n      ))}\n    </div>\n  );\n}\n\n// ── Rating Badge ──\nfunction RatingBadge({ rating }: { rating: number }) {\n  const colors: Record<number, string> = {\n    5: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',\n    4: 'bg-teal-500/20 text-teal-400 border-teal-500/30',\n    3: 'bg-amber-500/20 text-amber-400 border-amber-500/30',\n    2: 'bg-rose-500/20 text-rose-400 border-rose-500/30',\n    1: 'bg-red-500/20 text-red-400 border-red-500/30',\n  };\n  const labels: Record<number, string> = { 5: 'Excellent', 4: 'Good', 3: 'Average', 2: 'Poor', 1: 'Critical' };\n  return (\n    <span className={`text-xs font-bold px-2.5 py-1 rounded-full border ${colors[rating] || colors[3]}`}>\n      {rating}/5 — {labels[rating]}\n    </span>\n  );\n}\n\n// ── Alert Icon ──\nfunction AlertIcon({ type }: { type: string }) {\n  if (type === 'danger') return <AlertTriangle className=\"w-4 h-4 text-rose-400 shrink-0\" />;\n  if (type === 'warning') return <AlertTriangle className=\"w-4 h-4 text-amber-400 shrink-0\" />;\n  if (type === 'success') return <CheckCircle className=\"w-4 h-4 text-emerald-400 shrink-0\" />;\n  return <Info className=\"w-4 h-4 text-sky-400 shrink-0\" />;\n}\n\nexport function ScorecardDashboard() {\n  const { selectedFirm } = useHRMSStore();\n  const [data, setData] = useState<ScorecardData | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [month, setMonth] = useState(new Date().getMonth() + 1);\n  const [year, setYear] = useState(new Date().getFullYear());\n  const [selectedEmpId, setSelectedEmpId] = useState('');\n  const [searchName, setSearchName] = useState('');\n  const [grace, setGrace] = useState('15');\n  const [firmFilter, setFirmFilter] = useState('__all__');\n  const [locationFilter, setLocationFilter] = useState('__all__');\n  const [expandedEmp, setExpandedEmp] = useState<string | null>(null);\n\n  const fetchData = useCallback(async () => {\n    setLoading(true);\n    try {\n      // Always fetch ALL employees — selectedEmpId is used only locally for UI display\n      const params = new URLSearchParams({ month: String(month), year: String(year), grace });\n      if (firmFilter && firmFilter !== '__all__') params.set('firm', firmFilter);\n      else if (selectedFirm && selectedFirm !== '__all__') params.set('firm', selectedFirm);\n      if (locationFilter && locationFilter !== '__all__') params.set('location', locationFilter);\n      const res = await fetch(`/api/scorecard?${params}`);\n      if (res.ok) {\n        const json = await res.json();\n        setData(json);\n      } else {\n        toast.error('Failed to load scorecard');\n      }\n    } catch {\n      toast.error('Network error');\n    } finally {\n      setLoading(false);\n    }\n  }, [month, year, selectedFirm, firmFilter, locationFilter, grace]);\n\n  useEffect(() => { fetchData(); }, [fetchData]);\n\n  // Extract unique firms and locations from scorecard data for dropdowns\n  const uniqueFirms = [...new Set(data?.scorecards.map(sc => sc.firm).filter(Boolean))].sort();\n  const uniqueLocations = [...new Set(data?.scorecards.map(sc => sc.location).filter(Boolean))].sort();\n\n  // Filter by search name\n  const filteredScorecards = data?.scorecards.filter(sc =>\n    !searchName || sc.fullName.toLowerCase().includes(searchName.toLowerCase()) || sc.employeeId.toLowerCase().includes(searchName.toLowerCase())\n  ) || [];\n\n  const selectedEmp = selectedEmpId ? filteredScorecards.find(sc => sc.employeeId === selectedEmpId) : null;\n\n  if (loading || !data) {\n    return (\n      <div className=\"flex items-center justify-center h-[60vh]\">\n        <div className=\"flex flex-col items-center gap-3\">\n          <div className=\"w-8 h-8 border-2 border-gold border-t-transparent rounded-full animate-spin\" />\n          <span className=\"text-sm text-muted-foreground\">Loading Scorecard...</span>\n        </div>\n      </div>\n    );\n  }\n\n  const { summary, workingDays, totalWorkingDays, isLiveMonth, dataUptoDay, officialTime, graceMinutes } = data;\n\n  return (\n    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className=\"space-y-6\">\n      {/* Header */}\n      <div className=\"space-y-3\">\n        <div className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\">\n          <div>\n            <h1 className=\"text-2xl font-bold flex items-center gap-2\">\n              <CreditCard className=\"w-6 h-6 text-gold\" />\n              Attendance Scorecard\n            </h1>\n            <div className=\"text-xs text-muted-foreground mt-1 flex flex-wrap items-center gap-x-2 gap-y-0.5\">\n              <span>Official: <span className=\"text-gold font-bold\">{officialTime} AM</span></span>\n              <span className=\"text-white/20\">|</span>\n              <span>Grace: <span className=\"text-gold font-bold\">{graceMinutes} min</span></span>\n              <span className=\"text-white/20\">|</span>\n              <span>Late After: <span className=\"text-rose-400 font-bold\">{(() => { const [h,m] = officialTime.split(':').map(Number); const totalMin = h*60+m+graceMinutes; const rh = Math.floor(totalMin/60); const rm = totalMin%60; return `${String(rh).padStart(2,'0')}:${String(rm).padStart(2,'0')} AM`; })()}</span></span>\n              <span className=\"text-white/20\">|</span>\n              <span>{MONTHS[month - 1]} {year}</span>\n              {isLiveMonth && (\n                <>\n                  <span className=\"text-white/20\">|</span>\n                  <span className=\"text-emerald-400 font-bold\">LIVE</span>\n                  <span>{workingDays}/{totalWorkingDays} working days</span>\n                  <span className=\"text-muted-foreground\">(data upto {dataUptoDay}th)</span>\n                </>\n              )}\n            </div>\n          </div>\n        </div>\n        {/* Filter Row */}\n        <div className=\"flex gap-2 flex-wrap items-center\">\n          <Select value={String(month)} onValueChange={(v) => setMonth(Number(v))}>\n            <SelectTrigger className=\"w-[120px] h-8 text-xs\"><SelectValue /></SelectTrigger>\n            <SelectContent>\n              {MONTHS.map((m, i) => <SelectItem key={i} value={String(i + 1)}>{m}</SelectItem>)}\n            </SelectContent>\n          </Select>\n          <Select value={String(year)} onValueChange={(v) => setYear(Number(v))}>\n            <SelectTrigger className=\"w-[80px] h-8 text-xs\"><SelectValue /></SelectTrigger>\n            <SelectContent>\n              {[2025, 2026, 2027].map(y => <SelectItem key={y} value={String(y)}>{y}</SelectItem>)}\n            </SelectContent>\n          </Select>\n          <Select value={firmFilter} onValueChange={setFirmFilter}>\n            <SelectTrigger className=\"w-[130px] h-8 text-xs\"><SelectValue placeholder=\"All Firms\" /></SelectTrigger>\n            <SelectContent>\n              <SelectItem value=\"__all__\">All Firms</SelectItem>\n              {uniqueFirms.map(f => <SelectItem key={f} value={f}>{f}</SelectItem>)}\n            </SelectContent>\n          </Select>\n          <Select value={locationFilter} onValueChange={setLocationFilter}>\n            <SelectTrigger className=\"w-[140px] h-8 text-xs\"><SelectValue placeholder=\"All Locations\" /></SelectTrigger>\n            <SelectContent>\n              <SelectItem value=\"__all__\">All Locations</SelectItem>\n              {uniqueLocations.map(l => <SelectItem key={l} value={l}>{l}</SelectItem>)}\n            </SelectContent>\n          </Select>\n          <Select value={grace} onValueChange={setGrace}>\n            <SelectTrigger className=\"w-[120px] h-8 text-xs\"><SelectValue /></SelectTrigger>\n            <SelectContent>\n              <SelectItem value=\"0\">No grace</SelectItem>\n              <SelectItem value=\"5\">5 min grace</SelectItem>\n              <SelectItem value=\"10\">10 min grace</SelectItem>\n              <SelectItem value=\"15\">15 min (Default)</SelectItem>\n              <SelectItem value=\"30\">30 min grace</SelectItem>\n            </SelectContent>\n          </Select>\n        </div>\n      </div>\n\n      {/* Summary KPIs */}\n      <div className=\"grid grid-cols-2 lg:grid-cols-5 gap-4\">\n        {[\n          { label: 'Total Employees', value: summary.totalEmployees, icon: Users, color: COLORS.sky },\n          { label: 'Avg Rating', value: `${summary.avgRating}/5`, icon: Star, color: COLORS.gold },\n          { label: 'Perfect Score (5/5)', value: summary.perfectAttendance, icon: ShieldCheck, color: COLORS.emerald },\n          { label: 'At Risk (≤2)', value: summary.atRisk, icon: ShieldAlert, color: COLORS.rose },\n          { label: 'Excellence Eligible', value: summary.excellenceEligible, icon: Trophy, color: COLORS.violet },\n        ].map((kpi, i) => (\n          <motion.div key={i} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}>\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-4\">\n                <div className=\"flex items-center justify-between mb-1\">\n                  <span className=\"text-[10px] text-muted-foreground font-medium uppercase tracking-wider\">{kpi.label}</span>\n                  <div className=\"p-1 rounded-lg\" style={{ backgroundColor: `${kpi.color}20` }}>\n                    <kpi.icon className=\"w-3.5 h-3.5\" style={{ color: kpi.color }} />\n                  </div>\n                </div>\n                <p className=\"text-xl font-bold\" style={{ color: kpi.color }}>{kpi.value}</p>\n              </CardContent>\n            </Card>\n          </motion.div>\n        ))}\n      </div>\n\n      <div className=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n        {/* Left: Employee List */}\n        <div className=\"lg:col-span-1 space-y-4\">\n          <Card className=\"glass-card border-0\">\n            <CardHeader className=\"pb-2\">\n              <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                <Users className=\"w-4 h-4 text-gold\" />\n                Select Employee\n              </CardTitle>\n            </CardHeader>\n            <CardContent>\n              <Input placeholder=\"Search by name or code...\" value={searchName} onChange={(e) => setSearchName(e.target.value)} className=\"mb-3\" />\n              <div className=\"space-y-1 max-h-[500px] overflow-y-auto\">\n                {filteredScorecards.map(sc => (\n                  <div\n                    key={sc.employeeId}\n                    onClick={() => { setSelectedEmpId(sc.employeeId); setExpandedEmp(sc.employeeId); }}\n                    className={`flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-all duration-150 ${selectedEmpId === sc.employeeId ? 'bg-gold/10 border border-gold/30 ring-1 ring-gold/20' : 'hover:bg-white/5 border border-transparent'}`}\n                  >\n                    <div className=\"flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold\" style={{ backgroundColor: `${RATING_COLORS[sc.overallRating]}20`, color: RATING_COLORS[sc.overallRating] }}>\n                      {sc.overallRating}\n                    </div>\n                    <div className=\"flex-1 min-w-0\">\n                      <p className=\"text-xs font-semibold truncate\">{sc.fullName}</p>\n                      <p className=\"text-[10px] text-muted-foreground\">{sc.employeeId} · {sc.firm}</p>\n                    </div>\n                    {sc.isExcellenceEligible && <Trophy className=\"w-3.5 h-3.5 text-violet-400\" />}\n                  </div>\n                ))}\n              </div>\n            </CardContent>\n          </Card>\n\n          {/* Rating Distribution */}\n          <Card className=\"glass-card border-0\">\n            <CardHeader className=\"pb-2\">\n              <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                <Shield className=\"w-4 h-4 text-gold\" />\n                Rating Distribution\n              </CardTitle>\n            </CardHeader>\n            <CardContent>\n              {(() => {\n                const dist = [5, 4, 3, 2, 1].map(r => ({ rating: r, count: filteredScorecards.filter(s => s.overallRating === r).length, color: RATING_COLORS[r] })).filter(d => d.count > 0);\n                return dist.length > 0 ? (\n                  <ResponsiveContainer width=\"100%\" height={220}>\n                    <PieChart>\n                      <Pie data={dist} cx=\"50%\" cy=\"50%\" innerRadius={50} outerRadius={85} dataKey=\"count\" nameKey=\"rating\">\n                        {dist.map((entry, i) => <Cell key={i} fill={entry.color} />)}\n                      </Pie>\n                      <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8, fontSize: 12 }} />\n                      <Legend formatter={(v) => `Rating ${v}/5 (${dist.find(d => String(d.rating) === String(v))?.count || 0})`} />\n                    </PieChart>\n                  </ResponsiveContainer>\n                ) : <div className=\"text-center text-sm text-muted-foreground py-8\">No data</div>;\n              })()}\n            </CardContent>\n          </Card>\n        </div>\n\n        {/* Right: Employee Detail */}\n        <div className=\"lg:col-span-2 space-y-4\">\n          {selectedEmp ? (\n            <>\n              {/* Back to All button */}\n              <button\n                onClick={() => setSelectedEmpId('')}\n                className=\"flex items-center gap-2 text-sm text-gold hover:text-gold/80 transition-colors mb-1\"\n              >\n                <ArrowLeft className=\"w-4 h-4\" />\n                Back to All Employees\n              </button>\n              {/* Employee Scorecard Header */}\n              <Card className=\"glass-card border-0 overflow-hidden\">\n                <div className=\"p-5\">\n                  <div className=\"flex items-center justify-between mb-4\">\n                    <div>\n                      <h2 className=\"text-lg font-bold\">{selectedEmp.fullName}</h2>\n                      <p className=\"text-xs text-muted-foreground\">{selectedEmp.employeeId} · {selectedEmp.firm} · {selectedEmp.designation || 'N/A'}</p>\n                      <p className=\"text-xs text-muted-foreground\">Shift: {selectedEmp.shiftStart} - {selectedEmp.shiftEnd}</p>\n                    </div>\n                    <div className=\"text-center\">\n                      <div className=\"text-3xl font-black\" style={{ color: RATING_COLORS[selectedEmp.overallRating] }}>\n                        {selectedEmp.overallRating}/5\n                      </div>\n                      <RatingStars rating={selectedEmp.overallRating} size={16} />\n                      {selectedEmp.isExcellenceEligible && (\n                        <div className=\"mt-2 px-2 py-1 rounded-full bg-violet-500/20 text-violet-400 text-[10px] font-bold border border-violet-500/30 flex items-center gap-1\">\n                          <Trophy className=\"w-3 h-3\" /> Attendance Champion\n                        </div>\n                      )}\n                    </div>\n                  </div>\n\n                  {/* Score Breakdown */}\n                  <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4\">\n                    {[\n                      { label: 'Present Days', value: selectedEmp.presentDays, max: workingDays, color: COLORS.emerald },\n                      { label: 'On Time', value: selectedEmp.onTimeDays, max: selectedEmp.presentDays || 1, color: COLORS.teal },\n                      { label: 'Late Coming', value: selectedEmp.lateDays, color: COLORS.rose },\n                      { label: 'Absent Days', value: selectedEmp.absentDays, color: COLORS.amber },\n                    ].map((m, i) => (\n                      <div key={i} className=\"p-3 rounded-xl bg-white/[0.03]\">\n                        <p className=\"text-[10px] text-muted-foreground uppercase tracking-wider\">{m.label}</p>\n                        <p className=\"text-lg font-bold\" style={{ color: m.color }}>{m.value}{m.max ? `/${m.max}` : ''}</p>\n                      </div>\n                    ))}\n                  </div>\n\n                  {/* Detailed Metrics */}\n                  <div className=\"grid grid-cols-3 sm:grid-cols-6 gap-2 mb-4\">\n                    {[\n                      { label: 'Attendance %', value: `${selectedEmp.attendanceRate}%` },\n                      { label: 'Punctuality %', value: `${selectedEmp.punctualityRate}%` },\n                      { label: 'Half Days', value: selectedEmp.halfDays },\n                      { label: 'Early Out', value: selectedEmp.earlyOutDays },\n                      { label: 'Uninformed Leave', value: selectedEmp.uninformedLeaveDays },\n                      { label: 'Sunday Work', value: selectedEmp.sundayWorkingDays },\n                    ].map((m, i) => (\n                      <div key={i} className=\"p-2 rounded-lg bg-white/[0.03] text-center\">\n                        <p className=\"text-[9px] text-muted-foreground\">{m.label}</p>\n                        <p className=\"text-sm font-bold\">{m.value}</p>\n                      </div>\n                    ))}\n                  </div>\n\n                  {/* Discipline Rating Breakdown */}\n                  <div className=\"p-4 rounded-xl bg-white/[0.03] border border-white/5\">\n                    <h3 className=\"text-xs font-semibold text-gold mb-3 uppercase tracking-wider\">Strict Attendance Discipline Score <span className=\"text-rose-400\">(Late = after {(() => { const [h,m] = data.officialTime.split(':').map(Number); const totalMin = h*60+m+data.graceMinutes; const rh = Math.floor(totalMin/60); const rm = totalMin%60; return `${String(rh).padStart(2,'0')}:${String(rm).padStart(2,'0')}`; })()} AM)</span></h3>\n                    <div className=\"grid grid-cols-5 gap-2\">\n                      {[\n                        { condition: '100% On-Time', rating: 5, current: selectedEmp.lateDays === 0 },\n                        { condition: '1 Late Mark', rating: 4, current: selectedEmp.lateDays === 1 },\n                        { condition: '2-3 Late Marks', rating: 3, current: selectedEmp.lateDays >= 2 && selectedEmp.lateDays <= 3 },\n                        { condition: '4-5 Late Marks', rating: 2, current: selectedEmp.lateDays >= 4 && selectedEmp.lateDays <= 5 },\n                        { condition: '5+ Late Marks', rating: 1, current: selectedEmp.lateDays > 5 },\n                      ].map((row, i) => (\n                        <div key={i} className={`p-2 rounded-lg text-center border transition-all ${row.current ? 'border-gold/50 bg-gold/10' : 'border-white/5 bg-white/[0.02]'}`}>\n                          <p className=\"text-lg font-black\" style={{ color: RATING_COLORS[row.rating] }}>{row.rating}</p>\n                          <p className=\"text-[9px] text-muted-foreground mt-1\">{row.condition}</p>\n                          {row.current && <div className=\"mt-1 text-[9px] text-gold font-bold\">← Current</div>}\n                        </div>\n                      ))}\n                    </div>\n                  </div>\n                </div>\n              </Card>\n\n              {/* Late Instances Detail */}\n              {selectedEmp.lateInstances.length > 0 && (\n                <Card className=\"glass-card border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                      <Clock className=\"w-4 h-4 text-rose\" />\n                      Late Coming Details ({selectedEmp.lateInstances.length})\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"space-y-1.5 max-h-[200px] overflow-y-auto\">\n                      {selectedEmp.lateInstances.map((inst, i) => (\n                        <div key={i} className=\"flex items-center gap-3 p-2 rounded-lg bg-rose-500/5 border border-rose-500/10\">\n                          <span className=\"text-xs font-mono text-rose-400 font-bold\">{inst.date}</span>\n                          <span className=\"text-xs text-muted-foreground\">Punch-in:</span>\n                          <span className=\"text-xs font-bold text-rose-400\">{inst.checkIn}</span>\n                          <span className=\"text-xs text-muted-foreground\">({inst.minutesLate} min late)</span>\n                        </div>\n                      ))}\n                    </div>\n                  </CardContent>\n                </Card>\n              )}\n\n              {/* Early Out Details */}\n              {selectedEmp.earlyOutInstances.length > 0 && (\n                <Card className=\"glass-card border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                      <Clock className=\"w-4 h-4 text-amber\" />\n                      Early Departure Details ({selectedEmp.earlyOutInstances.length})\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"space-y-1.5\">\n                      {selectedEmp.earlyOutInstances.map((inst, i) => (\n                        <div key={i} className=\"flex items-center gap-3 p-2 rounded-lg bg-amber-500/5 border border-amber-500/10\">\n                          <span className=\"text-xs font-mono text-amber-400 font-bold\">{inst.date}</span>\n                          <span className=\"text-xs text-muted-foreground\">Punch-out:</span>\n                          <span className=\"text-xs font-bold text-amber-400\">{inst.checkOut}</span>\n                        </div>\n                      ))}\n                    </div>\n                  </CardContent>\n                </Card>\n              )}\n\n              {/* Alerts */}\n              {selectedEmp.alerts.length > 0 && (\n                <Card className=\"glass-card border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                      <AlertTriangle className=\"w-4 h-4 text-amber\" />\n                      Dashboard Alerts\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent className=\"space-y-2\">\n                    {selectedEmp.alerts.map((alert, i) => (\n                      <div key={i} className={`flex items-start gap-2 p-3 rounded-lg border ${\n                        alert.type === 'danger' ? 'bg-rose-500/5 border-rose-500/20' :\n                        alert.type === 'warning' ? 'bg-amber-500/5 border-amber-500/20' :\n                        alert.type === 'success' ? 'bg-emerald-500/5 border-emerald-500/20' :\n                        'bg-sky-500/5 border-sky-500/20'\n                      }`}>\n                        <AlertIcon type={alert.type} />\n                        <span className=\"text-xs\">{alert.message}</span>\n                      </div>\n                    ))}\n                  </CardContent>\n                </Card>\n              )}\n\n              {/* AI Insights */}\n              {selectedEmp.insights.length > 0 && (\n                <Card className=\"glass-card border-0\">\n                  <CardHeader className=\"pb-2\">\n                    <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                      <TrendingUp className=\"w-4 h-4 text-gold\" />\n                      Management Insights\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent className=\"space-y-2\">\n                    {selectedEmp.insights.map((insight, i) => (\n                      <div key={i} className=\"flex items-start gap-2 p-3 rounded-lg bg-gold/5 border border-gold/20\">\n                        <Info className=\"w-4 h-4 text-gold shrink-0 mt-0.5\" />\n                        <span className=\"text-xs text-muted-foreground\">{insight}</span>\n                      </div>\n                    ))}\n                  </CardContent>\n                </Card>\n              )}\n\n              {/* Attendance Excellence Award */}\n              <Card className={`glass-card border-0 overflow-hidden ${selectedEmp.isExcellenceEligible ? 'ring-2 ring-violet-500/50' : ''}`}>\n                <CardContent className=\"p-5\">\n                  <div className=\"flex items-center gap-3\">\n                    <div className={`p-3 rounded-xl ${selectedEmp.isExcellenceEligible ? 'bg-violet-500/20' : 'bg-white/5'}`}>\n                      <Award className={`w-6 h-6 ${selectedEmp.isExcellenceEligible ? 'text-violet-400' : 'text-muted-foreground'}`} />\n                    </div>\n                    <div className=\"flex-1\">\n                      <h3 className=\"text-sm font-bold\">Attendance Excellence Award</h3>\n                      <p className=\"text-[10px] text-muted-foreground mt-0.5\">\n                        Requirements: No Late Coming · No Early Out · No Uninformed Leave · Attendance ≥ 98%\n                      </p>\n                    </div>\n                    <div className=\"text-right\">\n                      {selectedEmp.isExcellenceEligible ? (\n                        <>\n                          <div className=\"text-lg font-black text-violet-400\">5/5</div>\n                          <span className=\"text-[10px] px-2 py-0.5 rounded-full bg-violet-500/20 text-violet-400 font-bold\">Champion 🏆</span>\n                        </>\n                      ) : (\n                        <span className=\"text-xs px-2 py-1 rounded-full bg-white/5 text-muted-foreground\">Not Eligible</span>\n                      )}\n                    </div>\n                  </div>\n                  {/* Eligibility Checklist */}\n                  <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-2 mt-3\">\n                    {[\n                      { label: 'No Late Coming', pass: selectedEmp.lateDays === 0 },\n                      { label: 'No Early Out', pass: selectedEmp.earlyOutDays === 0 },\n                      { label: 'No Uninformed Leave', pass: selectedEmp.uninformedLeaveDays === 0 },\n                      { label: 'Attendance ≥ 98%', pass: selectedEmp.attendanceRate >= 98 },\n                    ].map((req, i) => (\n                      <div key={i} className={`flex items-center gap-1.5 p-2 rounded-lg text-[10px] ${req.pass ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'}`}>\n                        {req.pass ? <CheckCircle className=\"w-3 h-3\" /> : <ShieldX className=\"w-3 h-3\" />}\n                        {req.label}\n                      </div>\n                    ))}\n                  </div>\n                </CardContent>\n              </Card>\n            </>\n          ) : (\n            /* No employee selected - show overview */\n            <>\n              {/* Department Compliance */}\n              <Card className=\"glass-card border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                    <Shield className=\"w-4 h-4 text-gold\" />\n                    Department-wise Punctuality Compliance\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  {data.deptCompliance.length > 0 ? (\n                    <ResponsiveContainer width=\"100%\" height={300}>\n                      <RadarChart data={data.deptCompliance}>\n                        <PolarGrid stroke=\"rgba(255,255,255,0.1)\" />\n                        <PolarAngleAxis dataKey=\"firm\" tick={{ fill: '#aaa', fontSize: 12 }} />\n                        <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fill: '#888', fontSize: 10 }} />\n                        <Radar name=\"Punctuality %\" dataKey=\"punctualityCompliance\" stroke={COLORS.teal} fill={COLORS.teal} fillOpacity={0.2} />\n                        <Radar name=\"Attendance %\" dataKey=\"attendanceCompliance\" stroke={COLORS.emerald} fill={COLORS.emerald} fillOpacity={0.2} />\n                        <Legend />\n                        <Tooltip contentStyle={{ backgroundColor: '#1a1a2e', border: '1px solid rgba(212,168,73,0.3)', borderRadius: 8 }} />\n                      </RadarChart>\n                    </ResponsiveContainer>\n                  ) : <div className=\"text-center text-sm text-muted-foreground py-8\">No department data</div>}\n                </CardContent>\n              </Card>\n\n              {/* All Employees Table */}\n              <Card className=\"glass-card border-0\">\n                <CardHeader className=\"pb-2\">\n                  <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                    <Users className=\"w-4 h-4 text-gold\" />\n                    All Employee Scorecards — Click to View Detail\n                  </CardTitle>\n                </CardHeader>\n                <CardContent className=\"overflow-x-auto\">\n                  <table className=\"w-full text-xs\">\n                    <thead>\n                      <tr className=\"border-b border-white/10\">\n                        <th className=\"text-left p-2 text-muted-foreground\">Employee</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Rating</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Present</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">On-Time</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Late</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Absent</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Att %</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Punc %</th>\n                        <th className=\"text-center p-2 text-muted-foreground\">Award</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {filteredScorecards.map(sc => (\n                        <tr\n                          key={sc.employeeId}\n                          onClick={() => setSelectedEmpId(sc.employeeId)}\n                          className=\"border-b border-white/5 hover:bg-white/5 cursor-pointer transition-colors\"\n                        >\n                          <td className=\"p-2\">\n                            <div className=\"font-semibold\">{sc.fullName}</div>\n                            <div className=\"text-[10px] text-muted-foreground\">{sc.employeeId} · {sc.firm}</div>\n                          </td>\n                          <td className=\"text-center p-2\"><RatingBadge rating={sc.overallRating} /></td>\n                          <td className=\"text-center p-2 font-mono\">{sc.presentDays}/{sc.workingDays}</td>\n                          <td className=\"text-center p-2 font-mono text-emerald-400\">{sc.onTimeDays}</td>\n                          <td className=\"text-center p-2 font-mono text-rose-400\">{sc.lateDays}</td>\n                          <td className=\"text-center p-2 font-mono text-amber-400\">{sc.absentDays}</td>\n                          <td className=\"text-center p-2 font-mono\">{sc.attendanceRate}%</td>\n                          <td className=\"text-center p-2 font-mono\">{sc.punctualityRate}%</td>\n                          <td className=\"text-center p-2\">\n                            {sc.isExcellenceEligible ? <Trophy className=\"w-4 h-4 text-violet-400 mx-auto\" /> : <span className=\"text-muted-foreground\">—</span>}\n                          </td>\n                        </tr>\n                      ))}\n                    </tbody>\n                  </table>\n                </CardContent>\n              </Card>\n            </>\n          )}\n        </div>\n      </div>\n    </motion.div>\n  );\n}\n","'use client';\n\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { Bot, Send, Sparkles, User, Loader2, BarChart3, Clock, Users, CalendarDays } from 'lucide-react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Input } from '@/components/ui/input';\nimport { Button } from '@/components/ui/button';\nimport { ScrollArea } from '@/components/ui/scroll-area';\nimport { Badge } from '@/components/ui/badge';\nimport { motion, AnimatePresence } from 'framer-motion';\n\ninterface Message {\n  role: 'user' | 'assistant';\n  content: string;\n}\n\nconst suggestions = [\n  { icon: Users, text: 'Who is absent today?', color: 'text-red-500' },\n  { icon: Clock, text: 'Who was late today?', color: 'text-amber-500' },\n  { icon: BarChart3, text: 'Show me attendance summary for this month', color: 'text-emerald-500' },\n  { icon: Clock, text: 'How many hours of OT this month?', color: 'text-blue-500' },\n  { icon: Users, text: 'Who are the employees in LAPL?', color: 'text-purple-500' },\n  { icon: CalendarDays, text: 'How many employees are present today?', color: 'text-teal-500' },\n];\n\n/**\n * Simple regex-based markdown renderer.\n * Handles: **bold**, *italic*, bullet points (- and •), numbered lists, tables, headers (##), and line breaks.\n */\nfunction renderMarkdown(text: string): string {\n  // Escape HTML\n  let html = text\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;');\n\n  // Handle tables: detect lines starting with | and convert to table\n  html = html.replace(/(?:^|\\n)((?:\\|[^\\n]+\\|\\n)+)/g, (_match, tableBlock: string) => {\n    const rows = tableBlock.trim().split('\\n');\n    if (rows.length < 2) return tableBlock;\n\n    const tableRows = rows.filter(row => !row.match(/^\\|[\\s-:|]+\\|$/)); // Remove separator rows\n    if (tableRows.length === 0) return tableBlock;\n\n    let tableHtml = '<table class=\"w-full text-xs border-collapse my-2\">';\n    tableRows.forEach((row, idx) => {\n      const cells = row.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1); // Remove empty first/last from split\n      const tag = idx === 0 ? 'th' : 'td';\n      const cellClass = idx === 0\n        ? 'px-2 py-1 text-left font-semibold border-b border-border bg-muted/50'\n        : 'px-2 py-1 border-b border-border';\n      tableHtml += '<tr>';\n      cells.forEach(cell => {\n        tableHtml += `<${tag} class=\"${cellClass}\">${cell.trim()}</${tag}>`;\n      });\n      tableHtml += '</tr>';\n    });\n    tableHtml += '</table>';\n    return tableHtml;\n  });\n\n  // Headers: ## and ###\n  html = html.replace(/^### (.+)$/gm, '<h4 class=\"text-sm font-bold mt-2 mb-1 text-foreground\">$1</h4>');\n  html = html.replace(/^## (.+)$/gm, '<h3 class=\"text-sm font-bold mt-3 mb-1 text-foreground\">$1</h3>');\n  html = html.replace(/^# (.+)$/gm, '<h2 class=\"text-base font-bold mt-3 mb-1 text-foreground\">$1</h2>');\n\n  // Bold: **text**\n  html = html.replace(/\\*\\*(.+?)\\*\\*/g, '<strong class=\"font-semibold text-foreground\">$1</strong>');\n\n  // Italic: *text* (but not inside bold)\n  html = html.replace(/(?<!\\*)\\*(?!\\*)(.+?)(?<!\\*)\\*(?!\\*)/g, '<em>$1</em>');\n\n  // Bullet points: lines starting with - or •\n  html = html.replace(/^[-•] (.+)$/gm, '<div class=\"flex gap-1.5 ml-1\"><span class=\"text-muted-foreground shrink-0\">•</span><span>$1</span></div>');\n\n  // Numbered lists: lines starting with 1. 2. etc.\n  html = html.replace(/^(\\d+)\\. (.+)$/gm, '<div class=\"flex gap-1.5 ml-1\"><span class=\"text-muted-foreground shrink-0 min-w-[1.2em]\">$1.</span><span>$2</span></div>');\n\n  // Line breaks (double newline -> paragraph break)\n  html = html.replace(/\\n\\n/g, '</p><p class=\"mt-1\">');\n  // Single newline -> <br/> (but not inside list items already handled)\n  html = html.replace(/\\n/g, '<br/>');\n\n  return html;\n}\n\nexport function AIAssistant() {\n  const [messages, setMessages] = useState<Message[]>([\n    {\n      role: 'assistant',\n      content: \"Hello! I'm your AI HR Assistant with **real-time data access**. I can answer questions about:\\n\\n- **Attendance**: Who's present/absent, late arrivals, work hours\\n- **Payroll**: Salary details, deductions, OT calculations\\n- **Employees**: Employee info by firm, location, department\\n\\nTry asking me something like **\\\"Who is absent today?\\\"** or **\\\"Show attendance summary this month\\\"**!\",\n    },\n  ]);\n  const [input, setInput] = useState('');\n  const [loading, setLoading] = useState(false);\n  const scrollRef = useRef<HTMLDivElement>(null);\n  const inputRef = useRef<HTMLInputElement>(null);\n\n  useEffect(() => {\n    if (scrollRef.current) {\n      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;\n    }\n  }, [messages, loading]);\n\n  const handleSend = useCallback(async (text?: string) => {\n    const message = text || input;\n    if (!message.trim() || loading) return;\n\n    setMessages(prev => [...prev, { role: 'user', content: message }]);\n    setInput('');\n    setLoading(true);\n\n    try {\n      const res = await fetch('/api/ai-assistant', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ message, context: 'HRMS Dashboard - Laxree Group of Companies' }),\n      });\n      const data = await res.json();\n      if (data.reply) {\n        setMessages(prev => [...prev, { role: 'assistant', content: data.reply }]);\n      } else {\n        setMessages(prev => [...prev, { role: 'assistant', content: 'I apologize, I couldn\\'t process your request. Please try again.' }]);\n      }\n    } catch {\n      setMessages(prev => [...prev, { role: 'assistant', content: 'I\\'m having trouble connecting. Please try again.' }]);\n    }\n    setLoading(false);\n    inputRef.current?.focus();\n  }, [input, loading]);\n\n  return (\n    <div className=\"space-y-3 h-full flex flex-col\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <Sparkles className=\"w-5 h-5 text-gold\" />\n            AI HR Assistant\n          </h2>\n          <p className=\"text-xs text-muted-foreground mt-0.5\">\n            Powered by AI with real-time data access &middot; Ask about attendance, payroll, or employees\n          </p>\n        </div>\n        <Badge variant=\"outline\" className=\"text-xs gap-1 shrink-0\">\n          <span className=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\" />\n          Live Data\n        </Badge>\n      </div>\n\n      {/* Suggestions */}\n      <div className=\"flex flex-wrap gap-1.5\">\n        {suggestions.map((s) => {\n          const Icon = s.icon;\n          return (\n            <Button\n              key={s.text}\n              variant=\"outline\"\n              size=\"sm\"\n              className=\"text-xs h-7 gap-1.5 hover:bg-muted/80\"\n              onClick={() => handleSend(s.text)}\n              disabled={loading}\n            >\n              <Icon className={`w-3 h-3 ${s.color}`} />\n              {s.text}\n            </Button>\n          );\n        })}\n      </div>\n\n      {/* Chat Messages */}\n      <Card className=\"glass-card card-gold-hover border-0 flex-1 flex flex-col min-h-0\">\n        <ScrollArea className=\"flex-1 p-4\" ref={scrollRef}>\n          <div className=\"space-y-4\">\n            <AnimatePresence initial={false}>\n              {messages.map((msg, i) => (\n                <motion.div\n                  key={i}\n                  initial={{ opacity: 0, y: 8 }}\n                  animate={{ opacity: 1, y: 0 }}\n                  transition={{ duration: 0.2 }}\n                  className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}\n                >\n                  <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${msg.role === 'assistant' ? 'bg-gold' : 'bg-muted'}`}>\n                    {msg.role === 'assistant' ? <Bot className=\"w-4 h-4 text-white\" /> : <User className=\"w-4 h-4\" />}\n                  </div>\n                  <div className={`max-w-[80%] p-3 rounded-xl text-sm ${msg.role === 'assistant' ? 'chat-bubble-ai' : 'chat-bubble-user'}`}>\n                    {msg.role === 'assistant' ? (\n                      <div\n                        className=\"prose-sm leading-relaxed [&_table]:text-xs [&_strong]:text-foreground [&_h3]:text-sm [&_h4]:text-xs\"\n                        dangerouslySetInnerHTML={{ __html: renderMarkdown(msg.content) }}\n                      />\n                    ) : (\n                      <div className=\"whitespace-pre-wrap\">{msg.content}</div>\n                    )}\n                  </div>\n                </motion.div>\n              ))}\n            </AnimatePresence>\n            {loading && (\n              <motion.div\n                initial={{ opacity: 0, y: 8 }}\n                animate={{ opacity: 1, y: 0 }}\n                className=\"flex gap-3\"\n              >\n                <div className=\"w-8 h-8 rounded-full bg-gold flex items-center justify-center shrink-0\">\n                  <Bot className=\"w-4 h-4 text-white\" />\n                </div>\n                <div className=\"chat-bubble-ai p-3 rounded-xl flex items-center gap-2\">\n                  <Loader2 className=\"w-4 h-4 animate-spin text-muted-foreground\" />\n                  <span className=\"text-xs text-muted-foreground\">Fetching data & thinking...</span>\n                </div>\n              </motion.div>\n            )}\n          </div>\n        </ScrollArea>\n      </Card>\n\n      {/* Input */}\n      <div className=\"flex gap-2\">\n        <Input\n          ref={inputRef}\n          placeholder=\"Ask about attendance, payroll, employees...\"\n          value={input}\n          onChange={e => setInput(e.target.value)}\n          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSend()}\n          className=\"flex-1\"\n          disabled={loading}\n        />\n        <Button\n          className=\"bg-gold text-white hover:bg-gold/90 shrink-0\"\n          onClick={() => handleSend()}\n          disabled={loading || !input.trim()}\n        >\n          {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Send className=\"w-4 h-4\" />}\n        </Button>\n      </div>\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback, useRef } from 'react';\nimport { FileText, Download, Printer, Building2, Mail, Phone, MapPin, FileSpreadsheet } from 'lucide-react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Separator } from '@/components/ui/separator';\nimport { useHRMSStore } from '@/lib/store';\nimport { motion } from 'framer-motion';\nimport Image from 'next/image';\nimport { toast } from 'sonner';\nimport * as XLSX from 'xlsx-js-style';\n\n// ── Advance Section Component ──\nfunction AdvanceSection({ employeeId, month, year, advanceDeduction }: { employeeId: string; month: number; year: number; advanceDeduction: number }) {\n  const [advances, setAdvances] = useState<any[]>([]);\n\n  useEffect(() => {\n    fetch(`/api/advances?employeeId=${employeeId}&month=${month}&year=${year}`)\n      .then(res => res.json())\n      .then(data => setAdvances(data))\n      .catch(() => {});\n  }, [employeeId, month, year]);\n\n  if (advances.length === 0) return null;\n\n  return (\n    <div className=\"mx-5 mb-3 border border-amber-300/30 rounded-lg overflow-hidden\">\n      <div className=\"bg-amber-500/10 px-4 py-2 border-b border-amber-300/20\">\n        <p className=\"text-xs font-bold text-amber-700 dark:text-amber-400\">Advance Details</p>\n      </div>\n      <div className=\"px-4 py-2 space-y-1.5\">\n        {advances.map((adv: any, idx: number) => (\n          <div key={adv.id} className=\"flex items-center justify-between text-xs\">\n            <div className=\"flex items-center gap-2\">\n              <span className=\"text-muted-foreground\">#{idx + 1}</span>\n              <span>{adv.reason}</span>\n              <span className=\"text-muted-foreground\">({new Date(adv.date).toLocaleDateString('en-IN')})</span>\n            </div>\n            <span className=\"font-bold text-amber-600 dark:text-amber-400\">₹{Number(adv.amount).toLocaleString('en-IN')}</span>\n          </div>\n        ))}\n        <div className=\"flex items-center justify-between text-xs border-t border-amber-200/20 pt-1.5 mt-1.5\">\n          <span className=\"font-semibold\">Total Advance Deducted</span>\n          <span className=\"font-bold text-amber-700 dark:text-amber-400\">₹{advanceDeduction.toLocaleString('en-IN')}</span>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nconst FIRM_BADGE_CLASS: Record<string, string> = {\n  LAPL: 'firm-badge-lapl',\n  LRSL: 'firm-badge-lrsl',\n  SI: 'firm-badge-si',\n  SDF: 'firm-badge-sdf',\n};\n\nconst FIRM_NAMES: Record<string, string> = {\n  LAPL: 'LAXREE AMENITIES PVT LTD',\n  LRSL: 'LAXREE ROOFING SOLUTION',\n  SI: 'SMARTH INTERNATIONAL',\n  SDF: 'SANGRAH DECOR & FURNITURE',\n};\n\nconst FIRM_LOGOS: Record<string, string> = {\n  LAPL: '/logos/lapl.jpg',\n  LRSL: '/logos/lrsl.jpg',\n  SI: '/logos/si.png',\n  SDF: '/logos/sdf.png',\n};\n\nconst FIRM_ADDRESSES: Record<string, string> = {\n  LAPL: 'Plot No. 1 & 2, Harbilas Sharda Marg, Civil Lines, Ajmer, Rajasthan 305001',\n  LRSL: 'Plot No. 1 & 2, Harbilas Sharda Marg, Civil Lines, Ajmer, Rajasthan 305001',\n  SI: 'Plot No. 1 & 2, Harbilas Sharda Marg, Civil Lines, Ajmer, Rajasthan 305001',\n  SDF: 'Plot No. 1 & 2, Harbilas Sharda Marg, Civil Lines, Ajmer, Rajasthan 305001',\n};\n\nconst FIRM_PHONES: Record<string, string> = {\n  LAPL: '+919251683663',\n  LRSL: '+919251683663',\n  SI: '+919251683663',\n  SDF: '+919251683663',\n};\n\nconst FIRM_EMAILS: Record<string, string> = {\n  LAPL: 'hr@laxree.com',\n  LRSL: 'hr@laxrereoofing.com',\n  SI: 'hr@smarthinternational.com',\n  SDF: 'hr@sangrahdecor.com',\n};\n\n// ── Convert decimal hours to HH.MM display format ──\nfunction formatHours(decimal: number): string {\n  if (!decimal || decimal === 0) return '0.00';\n  const hours = Math.floor(decimal);\n  const minutes = Math.round((decimal - hours) * 60);\n  if (minutes >= 60) return `${hours + 1}.00`;\n  return `${hours}.${String(minutes).padStart(2, '0')}`;\n}\n\n// ── Display a value that's already in HH.MM format (e.g., 5.25 = 5h 25min) ──\nfunction displayHHMM(value: number | undefined | null): string {\n  if (!value && value !== 0) return '0.00';\n  return value.toFixed(2);\n}\n\n// ── Get firm code from employee ID prefix ──\nfunction getFirmFromEmployeeId(employeeId: string): string {\n  const id = employeeId.toUpperCase();\n  if (id.startsWith('LAPL')) return 'LAPL';\n  if (id.startsWith('LRSL')) return 'LRSL';\n  if (id.startsWith('SI-') || id.startsWith('SI0')) return 'SI';\n  if (id.startsWith('SDF')) return 'SDF';\n  return '';\n}\n\nfunction FirmBadge({ f }: { f: string }) {\n  return <span className={FIRM_BADGE_CLASS[f] || 'firm-badge-lapl'}>{f}</span>;\n}\n\n// ── Convert number to words (Indian format) ──\nfunction numberToWords(num: number): string {\n  if (num === 0) return 'Zero';\n  const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',\n    'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];\n  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];\n\n  function convert(n: number): string {\n    if (n < 20) return ones[n];\n    if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 ? ' ' + ones[n % 10] : '');\n    if (n < 1000) return ones[Math.floor(n / 100)] + ' Hundred' + (n % 100 ? ' and ' + convert(n % 100) : '');\n    if (n < 100000) return convert(Math.floor(n / 1000)) + ' Thousand' + (n % 1000 ? ' ' + convert(n % 1000) : '');\n    if (n < 10000000) return convert(Math.floor(n / 100000)) + ' Lakh' + (n % 100000 ? ' ' + convert(n % 100000) : '');\n    return convert(Math.floor(n / 10000000)) + ' Crore' + (n % 10000000 ? ' ' + convert(n % 10000000) : '');\n  }\n\n  const rupees = Math.floor(num);\n  const paise = Math.round((num - rupees) * 100);\n  let result = 'Rupees ' + convert(rupees);\n  if (paise > 0) result += ' and ' + convert(paise) + ' Paise';\n  result += ' Only';\n  return result;\n}\n\ninterface FirmDetails {\n  code: string;\n  name: string;\n  address?: string;\n  contactPhone?: string;\n  contactEmail?: string;\n  logo?: string;\n}\n\nexport function SalarySlipGenerator() {\n  const { selectedEmployeeId } = useHRMSStore();\n  const [employeeId, setEmployeeId] = useState(selectedEmployeeId || '');\n  const [employees, setEmployees] = useState<{ employeeId: string; fullName: string; department: string; firm: string; location: string; salaryType: string; mobile?: string; email?: string; address?: string }[]>([]);\n  const [month, setMonth] = useState(new Date().getMonth() + 1);\n  const [year, setYear] = useState(new Date().getFullYear());\n  const [slip, setSlip] = useState<any>(null);\n  const [firms, setFirms] = useState<FirmDetails[]>([]);\n  const slipRef = useRef<HTMLDivElement>(null);\n\n  const loadEmployees = useCallback(async () => {\n    const data = await (await fetch('/api/employees')).json();\n    setEmployees(data);\n  }, []);\n\n  const loadFirms = useCallback(async () => {\n    try {\n      const res = await fetch('/api/firms');\n      if (res.ok) {\n        const data = await res.json();\n        setFirms(data);\n      }\n    } catch {}\n  }, []);\n\n  useEffect(() => { loadEmployees(); loadFirms(); }, [loadEmployees, loadFirms]);\n\n  useEffect(() => {\n    if (selectedEmployeeId) setEmployeeId(selectedEmployeeId);\n  }, [selectedEmployeeId]);\n\n  const loadSlip = useCallback(async () => {\n    if (!employeeId) return;\n    const [empRes, payRes] = await Promise.all([\n      fetch(`/api/employees/${employeeId}`),\n      fetch(`/api/payroll?employeeId=${employeeId}&month=${month}&year=${year}`),\n    ]);\n    const empData = await empRes.json();\n    const payData = await payRes.json();\n    setSlip({ employee: empData, payroll: payData[0] || null });\n  }, [employeeId, month, year]);\n\n  useEffect(() => { loadSlip(); }, [loadSlip]);\n\n  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];\n\n  // Get firm details for the employee\n  const firmCode = (slip?.employee?.employeeId ? getFirmFromEmployeeId(slip.employee.employeeId) : '') || slip?.employee?.department || slip?.employee?.firm || '';\n  const firmDetails = firms.find(f => f.code === firmCode);\n  const firmFullName = FIRM_NAMES[firmCode] || firmDetails?.name || 'Laxree Group of Companies';\n  const firmAddress = FIRM_ADDRESSES[firmCode] || firmDetails?.address || '';\n  const firmPhone = FIRM_PHONES[firmCode] || firmDetails?.contactPhone || '+919251683663';\n  const firmEmail = FIRM_EMAILS[firmCode] || firmDetails?.contactEmail || 'hr@laxree.com';\n  const firmLogo = FIRM_LOGOS[firmCode] || '/laxree-logo.png';\n\n  // ── Professional Excel Export (Beautiful & Colorful — Matching Payslip Format) ──\n  const handleExportExcel = () => {\n    if (!slip?.payroll) return;\n    const p = slip.payroll;\n    const e = slip.employee;\n    const perDayRate = p.perDayRate || (p.monthlySalary / (new Date(year, month, 0).getDate()));\n    const baseSalary = p.baseSalary != null ? p.baseSalary : Math.round((perDayRate * ((p.presentDays || 0) + (p.paidLeaves || 0)))) * 100 / 100;\n    const sundayEarn = p.sundayEarnings || 0;\n    const totalEarnings = p.grossSalary + (p.bonus || 0) + (p.incentive || 0) + (p.arrear || 0);\n\n    // Color constants\n    const BLUE = '1E3A5F';\n    const LIGHT_BLUE = 'DBEAFE';\n    const WHITE = 'FFFFFF';\n    const BLACK = '1A1A1A';\n    const EMERALD = '059669';\n    const RED = 'DC2626';\n    const GOLD = 'D4A843';\n    const TEAL = '0D9488';\n    const LIGHT_GREEN = 'ECFDF5';\n    const LIGHT_RED = 'FEF2F2';\n    const LIGHT_GOLD = 'FFF8E7';\n\n    const fullBorder = (color: string = 'B0B0B0', style: 'thin' | 'medium' = 'thin') => ({\n      top: { style, color: { rgb: color } },\n      bottom: { style, color: { rgb: color } },\n      left: { style, color: { rgb: color } },\n      right: { style, color: { rgb: color } },\n    });\n\n    const wb = XLSX.utils.book_new();\n\n    // ── Payslip Sheet in the exact format user wants ──\n    const data: any[][] = [\n      // Row 1: Title\n      [firmFullName + ' — PAY SLIP'],\n      // Row 2: Company Information Header\n      ['Salary Slip', '', '', '', 'COMPANY LOGO'],\n      // Row 3: Company Info section header\n      ['Company Information', '', '', '', ''],\n      // Rows 4-7: Company details\n      ['Company Name :', firmFullName, '', '', ''],\n      ['Company Address :', firmAddress, '', '', ''],\n      ['Company Phone no :', firmPhone, '', '', ''],\n      ['Company Email Address :', firmEmail, '', '', ''],\n      // Row 8: Employee Information header\n      ['Employee Information', '', '', '', ''],\n      // Rows 9-16: Employee details\n      ['Employee Name :', e.fullName, '', 'Employee Code :', e.employeeId],\n      ['Designation :', e.designation || 'N/A', '', 'Department :', e.department || firmCode || 'N/A'],\n      ['Pay Period :', `${months[month - 1]} ${year}`, '', 'Location :', e.location || 'N/A'],\n      ['Employee Address :', e.address || e.location || 'N/A', '', '', ''],\n      ['Employee Phone no :', e.mobile || 'N/A', '', 'Employee Email ID :', e.email || 'N/A'],\n      // Row 14: blank\n      [],\n      // Row 15: Earnings/Deductions header\n      ['Earnings', 'Amount', '', 'Deductions', 'Amount'],\n      // Rows 16-24: Earnings & Deductions rows\n      ['Basic', baseSalary.toLocaleString('en-IN'), '', 'Provident Fund', '0'],\n      ['Sunday Earnings', sundayEarn.toLocaleString('en-IN'), '', 'ESI', '0'],\n      ['Special Allowance', '0', '', 'Professional Tax', '0'],\n      ['Gross Salary', p.grossSalary.toLocaleString('en-IN'), '', 'Salary Advance', (p.advanceDeduction || 0).toLocaleString('en-IN')],\n      ['Other Earnings', (p.arrear || 0).toLocaleString('en-IN'), '', 'TDS', (p.tdsDeduction || 0).toLocaleString('en-IN')],\n      ['Incentives', (p.incentive || 0).toLocaleString('en-IN'), '', 'Loan', (p.loanDeduction || 0).toLocaleString('en-IN')],\n      ['Bonus', (p.bonus || 0).toLocaleString('en-IN'), '', 'Security Deposit', (p.securityDeposit || 0).toLocaleString('en-IN')],\n      ['Over Time Pay', (p.otAmount || 0).toLocaleString('en-IN'), '', 'Other Deduction', (p.otherDeductions || 0).toLocaleString('en-IN')],\n      ['Total Earnings', totalEarnings.toLocaleString('en-IN'), '', 'Net Pay', p.netSalary.toLocaleString('en-IN')],\n      // Row 25: blank\n      [],\n      // Row 26: In Words\n      ['In Words :', numberToWords(p.netSalary), '', '', ''],\n      // Row 27: blank\n      [],\n      // Row 28: Signature section\n      ['Prepared By :', '', '', 'Received By :', ''],\n      // Row 29: blank\n      [],\n      // Row 30: Footer\n      [`This is a computer-generated payslip by ${firmFullName}`],\n    ];\n\n    const ws = XLSX.utils.aoa_to_sheet(data);\n    const cols5 = ['A','B','C','D','E'];\n\n    // Row 1: Title\n    cols5.forEach(c => { if (ws[`${c}1`]) ws[`${c}1`].s = { font: { bold: true, color: { rgb: BLACK }, sz: 18 }, alignment: { horizontal: 'center' as const }, border: fullBorder(BLACK, 'medium') }; });\n\n    // Row 2: Salary Slip / Company Logo\n    if (ws['A2']) ws['A2'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 14 }, fill: { fgColor: { rgb: BLUE } }, alignment: { horizontal: 'center' as const }, border: fullBorder(BLUE, 'medium') };\n    if (ws['B2']) ws['B2'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 14 }, fill: { fgColor: { rgb: BLUE } }, border: fullBorder(BLUE, 'medium') };\n    if (ws['D2']) ws['D2'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 10 }, fill: { fgColor: { rgb: BLUE } }, alignment: { horizontal: 'center' as const }, border: fullBorder(BLUE, 'medium') };\n    if (ws['E2']) ws['E2'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 10 }, fill: { fgColor: { rgb: BLUE } }, alignment: { horizontal: 'center' as const }, border: fullBorder(BLUE, 'medium') };\n\n    // Row 3: Company Information section header\n    cols5.forEach(c => { if (ws[`${c}3`]) ws[`${c}3`].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: BLUE } }, border: fullBorder(BLUE) }; });\n\n    // Rows 4-7: Company details (light blue background)\n    for (const r of [4, 5, 6, 7]) {\n      if (ws[`A${r}`]) ws[`A${r}`].s = { font: { bold: true, sz: 10, color: { rgb: BLACK } }, fill: { fgColor: { rgb: LIGHT_BLUE } }, border: fullBorder('90B8E0') };\n      if (ws[`B${r}`]) ws[`B${r}`].s = { font: { sz: 10 }, fill: { fgColor: { rgb: LIGHT_BLUE } }, border: fullBorder('90B8E0') };\n    }\n\n    // Row 8: Employee Information header\n    cols5.forEach(c => { if (ws[`${c}8`]) ws[`${c}8`].s = { font: { bold: true, color: { rgb: BLACK }, sz: 11 }, fill: { fgColor: { rgb: 'E8E8E8' } }, border: fullBorder('999999') }; });\n\n    // Rows 9-13: Employee details (white background)\n    for (const r of [9, 10, 11, 12, 13]) {\n      if (ws[`A${r}`]) ws[`A${r}`].s = { font: { bold: true, sz: 10, color: { rgb: BLACK } }, border: fullBorder('CCCCCC') };\n      if (ws[`B${r}`]) ws[`B${r}`].s = { font: { sz: 10 }, border: fullBorder('CCCCCC') };\n      if (ws[`D${r}`]) ws[`D${r}`].s = { font: { bold: true, sz: 10, color: { rgb: BLACK } }, border: fullBorder('CCCCCC') };\n      if (ws[`E${r}`]) ws[`E${r}`].s = { font: { sz: 10 }, border: fullBorder('CCCCCC') };\n    }\n\n    // Row 15: Earnings/Deductions header\n    if (ws['A15']) ws['A15'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: EMERALD } }, alignment: { horizontal: 'center' as const }, border: fullBorder(EMERALD, 'medium') };\n    if (ws['B15']) ws['B15'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: EMERALD } }, alignment: { horizontal: 'center' as const }, border: fullBorder(EMERALD, 'medium') };\n    if (ws['D15']) ws['D15'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: RED } }, alignment: { horizontal: 'center' as const }, border: fullBorder(RED, 'medium') };\n    if (ws['E15']) ws['E15'].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: RED } }, alignment: { horizontal: 'center' as const }, border: fullBorder(RED, 'medium') };\n\n    // Rows 16-24: Earnings/Deductions data (alternating colors)\n    for (let i = 0; i < 9; i++) {\n      const r = 16 + i;\n      const isEven = i % 2 === 0;\n      const earnBg = isEven ? LIGHT_GREEN : LIGHT_GOLD;\n      const dedBg = isEven ? LIGHT_RED : 'FFF0F0';\n      const isTotal = i === 8; // last row\n\n      if (ws[`A${r}`]) ws[`A${r}`].s = { font: { sz: 10, bold: isTotal, color: { rgb: isTotal ? EMERALD : BLACK } }, fill: { fgColor: { rgb: earnBg } }, border: fullBorder(isTotal ? EMERALD : 'C0C0C0', isTotal ? 'medium' : 'thin') };\n      if (ws[`B${r}`]) ws[`B${r}`].s = { font: { sz: 10, bold: isTotal, color: { rgb: isTotal ? EMERALD : BLACK } }, fill: { fgColor: { rgb: earnBg } }, alignment: { horizontal: 'right' as const }, border: fullBorder(isTotal ? EMERALD : 'C0C0C0', isTotal ? 'medium' : 'thin') };\n      if (ws[`D${r}`]) ws[`D${r}`].s = { font: { sz: 10, bold: isTotal, color: { rgb: isTotal ? RED : BLACK } }, fill: { fgColor: { rgb: dedBg } }, border: fullBorder(isTotal ? RED : 'C0C0C0', isTotal ? 'medium' : 'thin') };\n      if (ws[`E${r}`]) ws[`E${r}`].s = { font: { sz: 10, bold: isTotal, color: { rgb: isTotal ? RED : BLACK } }, fill: { fgColor: { rgb: dedBg } }, alignment: { horizontal: 'right' as const }, border: fullBorder(isTotal ? RED : 'C0C0C0', isTotal ? 'medium' : 'thin') };\n    }\n\n    // Row 26: In Words (blue bg)\n    if (ws['A26']) ws['A26'].s = { font: { bold: true, sz: 10, color: { rgb: BLUE } }, fill: { fgColor: { rgb: LIGHT_BLUE } }, border: fullBorder(BLUE) };\n    if (ws['B26']) ws['B26'].s = { font: { italic: true, sz: 10, color: { rgb: BLUE } }, fill: { fgColor: { rgb: LIGHT_BLUE } }, border: fullBorder(BLUE) };\n\n    // Row 28: Signature section (blue bg)\n    cols5.forEach(c => { if (ws[`${c}28`]) ws[`${c}28`].s = { font: { bold: true, sz: 10, color: { rgb: WHITE } }, fill: { fgColor: { rgb: BLUE } }, border: fullBorder(BLUE) }; });\n\n    // Rows 30-31: Footer\n    cols5.forEach(c => { if (ws[`${c}30`]) ws[`${c}30`].s = { font: { italic: true, sz: 8, color: { rgb: '888888' } } }; });\n    cols5.forEach(c => { if (ws[`${c}31`]) ws[`${c}31`].s = { font: { italic: true, sz: 8, color: { rgb: '888888' } } }; });\n\n    ws['!cols'] = [\n      { wch: 22 }, { wch: 28 }, { wch: 4 }, { wch: 22 }, { wch: 28 },\n    ];\n    ws['!merges'] = [\n      { s: { r: 0, c: 0 }, e: { r: 0, c: 4 } },\n      { s: { r: 1, c: 0 }, e: { r: 1, c: 1 } },\n      { s: { r: 1, c: 3 }, e: { r: 1, c: 4 } },\n      { s: { r: 2, c: 0 }, e: { r: 2, c: 4 } },\n      { s: { r: 3, c: 1 }, e: { r: 3, c: 4 } },\n      { s: { r: 4, c: 1 }, e: { r: 4, c: 4 } },\n      { s: { r: 5, c: 1 }, e: { r: 5, c: 4 } },\n      { s: { r: 6, c: 1 }, e: { r: 6, c: 4 } },\n      { s: { r: 7, c: 0 }, e: { r: 7, c: 4 } },\n      { s: { r: 11, c: 1 }, e: { r: 11, c: 4 } },\n      { s: { r: 14, c: 2 }, e: { r: 14, c: 2 } },\n      { s: { r: 25, c: 1 }, e: { r: 25, c: 4 } },\n      { s: { r: 29, c: 0 }, e: { r: 29, c: 4 } },\n      { s: { r: 30, c: 0 }, e: { r: 30, c: 4 } },\n    ];\n    XLSX.utils.book_append_sheet(wb, ws, 'Salary Slip');\n\n    // ── Sheet 2: Detailed Breakdown ──\n    const detailData: any[][] = [\n      [firmFullName],\n      ['SALARY BREAKDOWN — ' + months[month - 1] + ' ' + year],\n      [],\n      ['Employee Details'],\n      ['Name', e.fullName, '', 'Code', e.employeeId],\n      ['Company', `${firmCode} - ${firmFullName}`, '', 'Location', e.location || 'N/A'],\n      ['Designation', e.designation || 'N/A', '', 'Salary Type', (e.salaryType || 'hourly').charAt(0).toUpperCase() + (e.salaryType || 'hourly').slice(1)],\n      [],\n      ['Earnings & Deductions Summary'],\n      ['Monthly Salary', p.monthlySalary.toLocaleString('en-IN'), '', 'Days in Month', new Date(year, month, 0).getDate()],\n      ['Base Salary', baseSalary.toLocaleString('en-IN'), '', 'Present Days', p.presentDays || 0],\n      ['Absent Days', (p.absentDays || 0).toString(), '', 'Gross Salary', p.grossSalary.toLocaleString('en-IN')],\n      [],\n      ['Hours Breakdown'],\n      ['Total Worked Hrs', displayHHMM(p.totalWorkedHrs || 0), '', 'OT Hours', displayHHMM(p.otHours || 0)],\n      ['Sunday Earnings', (p.sundayEarnings || 0).toLocaleString('en-IN'), '', 'Earn Sunday Hrs', (p.earnedSundayHrs || (p.sundayCount || 0) * 9).toFixed(0) + 'h'],\n      ['Sunday Worked Hrs', displayHHMM(p.sundayHrs || 0), '', 'OT Amount', (p.otAmount || 0).toLocaleString('en-IN')],\n    ];\n\n    const ws2 = XLSX.utils.aoa_to_sheet(detailData);\n    const cols = ['A','B','C','D','E'];\n    // Style\n    cols.forEach(c => { if (ws2[`${c}1`]) ws2[`${c}1`].s = { font: { bold: true, color: { rgb: GOLD }, sz: 14 }, fill: { fgColor: { rgb: BLACK } }, alignment: { horizontal: 'center' as const }, border: fullBorder(GOLD, 'medium') }; });\n    cols.forEach(c => { if (ws2[`${c}2`]) ws2[`${c}2`].s = { font: { bold: true, color: { rgb: WHITE }, sz: 11 }, fill: { fgColor: { rgb: BLUE } }, alignment: { horizontal: 'center' as const }, border: fullBorder(BLUE) }; });\n    ['A','D'].forEach(c => { if (ws2[`${c}4`]) ws2[`${c}4`].s = { font: { bold: true, color: { rgb: GOLD }, sz: 10 }, fill: { fgColor: { rgb: '2D2D2D' } } }; });\n    for (const r of [5,6,7]) {\n      if (ws2[`A${r}`]) ws2[`A${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`B${r}`]) ws2[`B${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_GOLD } } };\n      if (ws2[`D${r}`]) ws2[`D${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`E${r}`]) ws2[`E${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_GOLD } } };\n    }\n    ['A','D'].forEach(c => { if (ws2[`${c}9`]) ws2[`${c}9`].s = { font: { bold: true, color: { rgb: GOLD }, sz: 10 }, fill: { fgColor: { rgb: '2D2D2D' } } }; });\n    for (const r of [10,11,12,13]) {\n      if (ws2[`A${r}`]) ws2[`A${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`B${r}`]) ws2[`B${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_BLUE } } };\n      if (ws2[`D${r}`]) ws2[`D${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`E${r}`]) ws2[`E${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_BLUE } } };\n    }\n    ['A','D'].forEach(c => { if (ws2[`${c}15`]) ws2[`${c}15`].s = { font: { bold: true, color: { rgb: GOLD }, sz: 10 }, fill: { fgColor: { rgb: '2D2D2D' } } }; });\n    for (const r of [16,17,18]) {\n      if (ws2[`A${r}`]) ws2[`A${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`B${r}`]) ws2[`B${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_GOLD } } };\n      if (ws2[`D${r}`]) ws2[`D${r}`].s = { font: { sz: 10, color: { rgb: '666666' } } };\n      if (ws2[`E${r}`]) ws2[`E${r}`].s = { font: { bold: true, sz: 10 }, fill: { fgColor: { rgb: LIGHT_GOLD } } };\n    }\n\n    ws2['!cols'] = [{ wch: 32 }, { wch: 22 }, { wch: 4 }, { wch: 22 }, { wch: 22 }];\n    ws2['!merges'] = [\n      { s: { r: 0, c: 0 }, e: { r: 0, c: 4 } },\n      { s: { r: 1, c: 0 }, e: { r: 1, c: 4 } },\n    ];\n    XLSX.utils.book_append_sheet(wb, ws2, 'Breakdown');\n\n    XLSX.writeFile(wb, `Payslip_${e.fullName}_${months[month - 1]}_${year}.xlsx`);\n    toast.success('Payslip Excel downloaded successfully!');\n  };\n\n  // ── Print Handler (Professional Blue-White Format matching user's desired layout) ──\n  const handlePrint = () => {\n    if (!slip?.payroll || !slipRef.current) return;\n    const p = slip.payroll;\n    const e = slip.employee;\n    const perDayRate = p.perDayRate || (p.monthlySalary / (new Date(year, month, 0).getDate()));\n    const baseSalary = p.baseSalary != null ? p.baseSalary : Math.round((perDayRate * ((p.presentDays || 0) + (p.paidLeaves || 0)))) * 100 / 100;\n    const sundayEarn = p.sundayEarnings || 0;\n    const totalEarnings = p.grossSalary + (p.bonus || 0) + (p.incentive || 0) + (p.arrear || 0);\n\n    const logoAbsUrl = `${window.location.origin}${firmLogo}`;\n\n    const printWin = window.open('', '_blank', 'width=800,height=1000');\n    if (!printWin) return;\n    printWin.document.write(`<!DOCTYPE html><html><head><title>Salary Slip - ${e.fullName}</title>\n    <style>\n      @import url('https://fonts.googleapis.com/css2?family=Merriweather:wght@300;400;700;900&display=swap');\n      @page { size: A4; margin: 10mm; }\n      * { margin: 0; padding: 0; box-sizing: border-box; }\n      body { font-family: 'Merriweather', 'Georgia', 'Liberation Serif', serif; font-size: 11px; color: #222; background: #fff; }\n      .payslip { max-width: 750px; margin: 0 auto; border: 2px solid #1E3A5F; border-radius: 8px; overflow: hidden; }\n      .title { text-align: center; font-size: 20px; font-weight: 800; padding: 10px; color: #1A1A1A; border-bottom: 2px solid #1E3A5F; }\n      .company-header { background: #1E3A5F; color: white; padding: 14px 20px; display: flex; align-items: center; justify-content: space-between; }\n      .company-header .left h2 { font-size: 16px; font-weight: 700; margin-bottom: 2px; }\n      .company-header .left p { font-size: 10px; color: #b0c4de; }\n      .company-header .logo-box { width: 70px; height: 70px; background: white; border-radius: 8px; overflow: hidden; display: flex; align-items: center; justify-content: center; }\n      .company-header .logo-box img { width: 100%; height: 100%; object-fit: contain; }\n      .section-header { background: #1E3A5F; color: white; padding: 6px 20px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }\n      .info-grid { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; padding: 10px 20px; background: #DBEAFE; }\n      .info-grid .label { font-weight: 600; font-size: 10px; color: #1E3A5F; }\n      .info-grid .value { font-size: 10px; }\n      .emp-section { background: white; }\n      .emp-section .info-grid { background: #f8f9fa; }\n      .table-section { padding: 0; }\n      table { width: 100%; border-collapse: collapse; }\n      th { background: #059669; color: white; font-size: 11px; font-weight: 700; padding: 8px 12px; text-align: left; }\n      th.ded { background: #DC2626; }\n      td { padding: 6px 12px; font-size: 10px; border-bottom: 1px solid #e5e7eb; }\n      tr:nth-child(even) td { background: #ECFDF5; }\n      tr:nth-child(even) td.ded-cell { background: #FEF2F2; }\n      tr.total-row td { font-weight: 700; border-top: 2px solid #333; background: #f0fdf4 !important; font-size: 12px; }\n      tr.total-row td.ded-cell { background: #fef2f2 !important; color: #DC2626; }\n      tr.total-row td.earn-total { color: #059669; }\n      .net-pay-row td { font-weight: 800; background: #FEF2F2 !important; color: #DC2626; font-size: 13px; border-top: 2px solid #DC2626; }\n      .in-words { padding: 8px 20px; background: #DBEAFE; font-size: 10px; color: #1E3A5F; }\n      .in-words .label { font-weight: 700; }\n      .in-words .value { font-style: italic; }\n      .signature-section { background: #1E3A5F; color: white; padding: 12px 20px; display: grid; grid-template-columns: 1fr 1fr; gap: 40px; }\n      .sig-line { border-top: 1px solid white; padding-top: 4px; text-align: center; font-size: 9px; margin-top: 20px; }\n      .footer { padding: 6px 20px; text-align: center; font-size: 8px; color: #999; border-top: 1px solid #eee; }\n    </style></head><body>\n    <div class=\"payslip\">\n      <div class=\"title\">PAY SLIP — ${months[month - 1]} ${year}</div>\n      <div class=\"company-header\">\n        <div class=\"left\">\n          <h2>Salary Slip</h2>\n          <p>${firmFullName}</p>\n        </div>\n        <div class=\"logo-box\"><img src=\"${logoAbsUrl}\" alt=\"${firmCode}\" /></div>\n      </div>\n      <div class=\"info-grid\">\n        <span class=\"label\">Company Name :</span><span class=\"value\">${firmFullName}</span>\n        <span class=\"label\">Company Address :</span><span class=\"value\">${firmAddress}</span>\n        <span class=\"label\">Company Phone no :</span><span class=\"value\">${firmPhone}</span>\n        <span class=\"label\">Company Email Address :</span><span class=\"value\">${firmEmail}</span>\n      </div>\n      <div class=\"section-header\">Employee Information</div>\n      <div class=\"emp-section\">\n        <div class=\"info-grid\">\n          <span class=\"label\">Employee Name :</span><span class=\"value\">${e.fullName}</span>\n          <span class=\"label\">Employee Code :</span><span class=\"value\">${e.employeeId}</span>\n          <span class=\"label\">Designation :</span><span class=\"value\">${e.designation || 'N/A'}</span>\n          <span class=\"label\">Department :</span><span class=\"value\">${e.department || firmCode || 'N/A'}</span>\n          <span class=\"label\">Pay Period :</span><span class=\"value\">${months[month - 1]} ${year}</span>\n          <span class=\"label\">Location :</span><span class=\"value\">${e.location || 'N/A'}</span>\n          <span class=\"label\">Employee Address :</span><span class=\"value\">${e.address || e.location || 'N/A'}</span>\n          <span class=\"label\">Employee Phone no :</span><span class=\"value\">${e.mobile || 'N/A'}</span>\n          <span class=\"label\">Employee Email ID :</span><span class=\"value\">${e.email || 'N/A'}</span>\n        </div>\n      </div>\n      <div class=\"table-section\">\n        <table>\n          <tr><th>Earnings</th><th>Amount</th><th class=\"ded\">Deductions</th><th class=\"ded\">Amount</th></tr>\n          <tr><td>Basic</td><td>₹${baseSalary.toLocaleString('en-IN')}</td><td class=\"ded-cell\">Provident Fund</td><td class=\"ded-cell\">₹0</td></tr>\n          <tr><td>Sunday Earnings</td><td>₹${sundayEarn.toLocaleString('en-IN')}</td><td class=\"ded-cell\">ESI</td><td class=\"ded-cell\">₹0</td></tr>\n          <tr><td>Special Allowance</td><td>₹0</td><td class=\"ded-cell\">Professional Tax</td><td class=\"ded-cell\">₹0</td></tr>\n          <tr><td>Gross Salary</td><td>₹${p.grossSalary.toLocaleString('en-IN')}</td><td class=\"ded-cell\">Salary Advance</td><td class=\"ded-cell\">₹${(p.advanceDeduction || 0).toLocaleString('en-IN')}</td></tr>\n          <tr><td>Other Earnings</td><td>₹${(p.arrear || 0).toLocaleString('en-IN')}</td><td class=\"ded-cell\">TDS</td><td class=\"ded-cell\">₹${(p.tdsDeduction || 0).toLocaleString('en-IN')}</td></tr>\n          <tr><td>Incentives</td><td>₹${(p.incentive || 0).toLocaleString('en-IN')}</td><td class=\"ded-cell\">Loan</td><td class=\"ded-cell\">₹${(p.loanDeduction || 0).toLocaleString('en-IN')}</td></tr>\n          <tr><td>Bonus</td><td>₹${(p.bonus || 0).toLocaleString('en-IN')}</td><td class=\"ded-cell\">Security Deposit</td><td class=\"ded-cell\">₹${(p.securityDeposit || 0).toLocaleString('en-IN')}</td></tr>\n          <tr><td>Over Time Pay</td><td>₹${(p.otAmount || 0).toLocaleString('en-IN')}</td><td class=\"ded-cell\">Other Deduction</td><td class=\"ded-cell\">₹${(p.otherDeductions || 0).toLocaleString('en-IN')}</td></tr>\n          <tr class=\"total-row\"><td class=\"earn-total\">Total Earnings</td><td class=\"earn-total\">₹${totalEarnings.toLocaleString('en-IN')}</td><td class=\"ded-cell net-pay-label\">Net Pay</td><td class=\"ded-cell\" style=\"font-size:14px;font-weight:800;color:#1E3A5F;\">₹${p.netSalary.toLocaleString('en-IN')}</td></tr>\n        </table>\n      </div>\n      <div class=\"in-words\">\n        <span class=\"label\">In Words : </span><span class=\"value\">${numberToWords(p.netSalary)}</span>\n      </div>\n      <div class=\"signature-section\">\n        <div class=\"sig-line\">Prepared By</div>\n        <div class=\"sig-line\">Received By</div>\n      </div>\n      <div class=\"footer\">\n        This is a computer-generated payslip by ${firmFullName}. For queries contact HR at ${firmPhone}\n      </div>\n    </div>\n    <script>window.onload=function(){window.print();}</script>\n    </body></html>`);\n    printWin.document.close();\n  };\n\n  const firm = (slip?.employee?.employeeId ? getFirmFromEmployeeId(slip.employee.employeeId) : '') || slip?.employee?.department || slip?.employee?.firm || '';\n  const p = slip?.payroll;\n  const e = slip?.employee;\n  const perDayRateCalc = p ? (p.perDayRate || (p.monthlySalary / (new Date(year, month, 0).getDate()))) : 0;\n  const baseSalaryCalc = p ? (p.baseSalary != null ? p.baseSalary : Math.round((perDayRateCalc * ((p.presentDays || 0) + (p.paidLeaves || 0)))) * 100 / 100) : 0;\n  const sundayEarningsCalc = p ? (p.sundayEarnings || 0) : 0;\n  const sundayCountCalc = p ? (p.sundayCount || 0) : 0;\n  const earnedSundayHrsCalc = p ? (p.earnedSundayHrs || sundayCountCalc * 9) : 0;\n  const totalEarningsCalc = p ? p.grossSalary + (p.bonus || 0) + (p.incentive || 0) + (p.arrear || 0) : 0;\n\n  return (\n    <div className=\"space-y-4\">\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\"\n      >\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <FileText className=\"w-5 h-5 text-gold\" />\n            Salary Slip Generator\n          </h2>\n          <p className=\"text-sm text-muted-foreground\">Professional payslips with company branding</p>\n        </div>\n      </motion.div>\n\n      <div className=\"flex flex-wrap gap-3\">\n        <Select value={employeeId} onValueChange={setEmployeeId}>\n          <SelectTrigger className=\"w-64\"><SelectValue placeholder=\"Select Employee\" /></SelectTrigger>\n          <SelectContent>{employees.map(emp => <SelectItem key={emp.employeeId} value={emp.employeeId}>{emp.fullName} ({emp.employeeId})</SelectItem>)}</SelectContent>\n        </Select>\n        <Select value={String(month)} onValueChange={v => setMonth(Number(v))}>\n          <SelectTrigger className=\"w-36\"><SelectValue /></SelectTrigger>\n          <SelectContent>{months.map((m, i) => <SelectItem key={i} value={String(i + 1)}>{m}</SelectItem>)}</SelectContent>\n        </Select>\n        <Select value={String(year)} onValueChange={v => setYear(Number(v))}>\n          <SelectTrigger className=\"w-24\"><SelectValue /></SelectTrigger>\n          <SelectContent>{[2024, 2025, 2026, 2027].map(y => <SelectItem key={y} value={String(y)}>{y}</SelectItem>)}</SelectContent>\n        </Select>\n        {slip?.payroll && (\n          <div className=\"flex gap-2\">\n            <Button variant=\"outline\" onClick={handlePrint} className=\"gap-1.5\">\n              <Printer className=\"w-4 h-4\" /> Print Payslip\n            </Button>\n            <Button className=\"gradient-laxree text-white gap-1.5\" onClick={handleExportExcel}>\n              <FileSpreadsheet className=\"w-4 h-4\" /> Export Excel\n            </Button>\n          </div>\n        )}\n      </div>\n\n      {slip?.payroll ? (\n        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>\n          <Card className=\"border-2 border-blue-900/30 dark:border-blue-500/20 overflow-hidden\" ref={slipRef}>\n            {/* ═══ SALARY SLIP FORMAT — Blue-White Professional ═══ */}\n            <div className=\"bg-white dark:bg-card\" style={{ fontFamily: \"'Merriweather', 'Georgia', 'Liberation Serif', serif\" }}>\n              {/* Title */}\n              <div className=\"text-center py-2 border-b-2 border-[#1E3A5F] dark:border-blue-500\">\n                <div className=\"flex items-center justify-between px-4\">\n                  <h2 className=\"text-xl font-extrabold text-[#1E3A5F] dark:text-blue-400 tracking-wide\">PAY SLIP</h2>\n                  <span className=\"text-xs text-muted-foreground\">{months[month - 1]} {year}</span>\n                </div>\n              </div>\n\n              {/* Company Header with Logo */}\n              <div className=\"bg-[#1E3A5F] dark:bg-blue-900 px-5 py-3 flex items-center justify-between\">\n                <div>\n                  <h3 className=\"text-white font-bold text-base\">{firmFullName}</h3>\n                  <p className=\"text-blue-200 text-xs\">{months[month - 1]} {year}</p>\n                </div>\n                <div className=\"w-16 h-16 bg-white rounded-lg overflow-hidden flex items-center justify-center p-1\">\n                  <img src={firmLogo} alt={firmCode} className=\"w-full h-full object-contain\" />\n                </div>\n              </div>\n\n              {/* Company Info Grid */}\n              <div className=\"grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 px-5 py-3 bg-blue-50 dark:bg-blue-950/30 text-sm\">\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Company Name :</span>\n                <span>{firmFullName}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Company Address :</span>\n                <span>{firmAddress}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Company Phone no :</span>\n                <span>{firmPhone}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Company Email Address :</span>\n                <span>{firmEmail}</span>\n              </div>\n\n              {/* Employee Information Header */}\n              <div className=\"bg-[#1E3A5F] dark:bg-blue-900 px-5 py-1.5\">\n                <h3 className=\"text-white font-bold text-xs uppercase tracking-wider\">Employee Information</h3>\n              </div>\n\n              {/* Employee Info Grid */}\n              <div className=\"grid grid-cols-[auto_1fr_auto_1fr] gap-x-3 gap-y-1 px-5 py-3 bg-gray-50 dark:bg-muted/20 text-sm\">\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Employee Name :</span>\n                <span>{e.fullName}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Employee Code :</span>\n                <span>{e.employeeId}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Designation :</span>\n                <span>{e.designation || 'N/A'}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Department :</span>\n                <span>{e.department || firmCode || 'N/A'}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Pay Period :</span>\n                <span>{months[month - 1]} {year}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Location :</span>\n                <span>{e.location || 'N/A'}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Employee Address :</span>\n                <span>{e.address || e.location || 'N/A'}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Employee Phone no :</span>\n                <span>{e.mobile || 'N/A'}</span>\n                <span className=\"font-semibold text-[#1E3A5F] dark:text-blue-400\">Employee Email ID :</span>\n                <span>{e.email || 'N/A'}</span>\n              </div>\n\n              {/* Earnings & Deductions Table */}\n              <div className=\"px-5 py-3\">\n                <table className=\"w-full text-sm border-collapse\">\n                  <thead>\n                    <tr>\n                      <th className=\"bg-emerald-600 text-white px-3 py-2 text-left font-bold\">Earnings</th>\n                      <th className=\"bg-emerald-600 text-white px-3 py-2 text-left font-bold\">Amount</th>\n                      <th className=\"bg-red-600 text-white px-3 py-2 text-left font-bold\">Deductions</th>\n                      <th className=\"bg-red-600 text-white px-3 py-2 text-left font-bold\">Amount</th>\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {[\n                      { earn: 'Basic', earnVal: baseSalaryCalc, ded: 'Provident Fund', dedVal: 0 },\n                      { earn: 'Sunday Earnings', earnVal: sundayEarningsCalc, ded: 'ESI', dedVal: 0 },\n                      { earn: 'Special Allowance', earnVal: 0, ded: 'Professional Tax', dedVal: 0 },\n                      { earn: 'Gross Salary', earnVal: p.grossSalary, ded: 'Salary Advance', dedVal: p.advanceDeduction || 0 },\n                      { earn: 'Other Earnings', earnVal: p.arrear || 0, ded: 'TDS', dedVal: p.tdsDeduction || 0 },\n                      { earn: 'Incentives', earnVal: p.incentive || 0, ded: 'Loan', dedVal: p.loanDeduction || 0 },\n                      { earn: 'Bonus', earnVal: p.bonus || 0, ded: 'Security Deposit', dedVal: p.securityDeposit || 0 },\n                      { earn: 'Over Time Pay', earnVal: p.otAmount || 0, ded: 'Other Deduction', dedVal: p.otherDeductions || 0 },\n                    ].map((row, idx) => (\n                      <tr key={idx} className={idx % 2 === 0 ? 'bg-emerald-50 dark:bg-emerald-950/20' : ''}>\n                        <td className={`px-3 py-1.5 border-b border-gray-200 ${idx % 2 === 0 ? 'bg-emerald-50 dark:bg-emerald-950/20' : ''}`}>{row.earn}</td>\n                        <td className={`px-3 py-1.5 border-b border-gray-200 text-right ${idx % 2 === 0 ? 'bg-emerald-50 dark:bg-emerald-950/20' : ''}`}>₹{row.earnVal.toLocaleString('en-IN')}</td>\n                        <td className={`px-3 py-1.5 border-b border-gray-200 ${idx % 2 === 0 ? 'bg-red-50 dark:bg-red-950/20' : ''}`}>{row.ded}</td>\n                        <td className={`px-3 py-1.5 border-b border-gray-200 text-right ${idx % 2 === 0 ? 'bg-red-50 dark:bg-red-950/20' : ''}`}>₹{row.dedVal.toLocaleString('en-IN')}</td>\n                      </tr>\n                    ))}\n                    {/* Total Earnings / Net Pay row */}\n                    <tr className=\"border-t-2 border-gray-800 dark:border-gray-300\">\n                      <td className=\"px-3 py-2 font-bold text-emerald-700 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-950/40\">Total Earnings</td>\n                      <td className=\"px-3 py-2 font-bold text-emerald-700 dark:text-emerald-400 text-right bg-emerald-100 dark:bg-emerald-950/40\">₹{totalEarningsCalc.toLocaleString('en-IN')}</td>\n                      <td className=\"px-3 py-2 font-bold text-red-600 dark:text-red-400 bg-red-100 dark:bg-red-950/40\">Net Pay</td>\n                      <td className=\"px-3 py-2 font-extrabold text-[#1E3A5F] dark:text-blue-400 text-right bg-red-100 dark:bg-red-950/40 text-lg\">₹{p.netSalary.toLocaleString('en-IN')}</td>\n                    </tr>\n                  </tbody>\n                </table>\n              </div>\n\n              {/* Advance Details */}\n              {(p.advanceDeduction > 0) && (\n                <AdvanceSection employeeId={e.employeeId} month={month} year={year} advanceDeduction={p.advanceDeduction} />\n              )}\n\n              {/* In Words */}\n              <div className=\"mx-5 mb-3 px-4 py-2 bg-blue-50 dark:bg-blue-950/30 rounded text-sm\">\n                <span className=\"font-bold text-[#1E3A5F] dark:text-blue-400\">In Words : </span>\n                <span className=\"italic text-[#1E3A5F] dark:text-blue-300\">{numberToWords(p.netSalary)}</span>\n              </div>\n\n              {/* Signature Section */}\n              <div className=\"bg-[#1E3A5F] dark:bg-blue-900 px-5 py-4 grid grid-cols-2 gap-10\">\n                <div className=\"mt-8 pt-2 border-t border-white/50 text-center text-white text-xs\">Prepared By</div>\n                <div className=\"mt-8 pt-2 border-t border-white/50 text-center text-white text-xs\">Received By</div>\n              </div>\n\n              {/* Footer */}\n              <div className=\"text-center text-[9px] text-muted-foreground py-2 border-t border-dashed\">\n                This is a computer-generated payslip by {firmFullName}. For queries contact HR at {firmPhone}\n              </div>\n            </div>\n          </Card>\n        </motion.div>\n      ) : (\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardContent className=\"p-8 text-center text-muted-foreground\">\n            <FileText className=\"w-12 h-12 mx-auto mb-3 opacity-30\" />\n            <p>Select an employee and period to generate salary slip</p>\n            {employeeId && <p className=\"text-sm mt-2\">No payroll found for this period. Generate payroll first.</p>}\n          </CardContent>\n        </Card>\n      )}\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback } from 'react';\nimport { Settings, Save, RefreshCw, Info, Clock, IndianRupee } from 'lucide-react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Input } from '@/components/ui/input';\nimport { Label } from '@/components/ui/label';\nimport { Separator } from '@/components/ui/separator';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { Badge } from '@/components/ui/badge';\nimport { toast } from 'sonner';\nimport { motion } from 'framer-motion';\nimport Image from 'next/image';\n\nexport function SettingsPanel() {\n  const [settings, setSettings] = useState<Record<string, string>>({});\n\n  const loadSettings = useCallback(async () => {\n    const res = await fetch('/api/settings');\n    setSettings(await res.json());\n  }, []);\n\n  useEffect(() => { loadSettings(); }, [loadSettings]);\n\n  const handleSave = async () => {\n    await fetch('/api/settings', {\n      method: 'PUT',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(settings),\n    });\n    toast.success('Settings saved successfully');\n  };\n\n  const handleReseed = async () => {\n    await fetch('/api/seed', { method: 'POST' });\n    toast.success('Database re-seeded with demo data');\n    loadSettings();\n  };\n\n  const settingGroups = [\n    {\n      title: 'Company Information',\n      icon: Settings,\n      fields: [\n        { key: 'companyName', label: 'Company Name', defaultValue: 'Laxree' },\n        { key: 'companyFullName', label: 'Full Company Name', defaultValue: 'Laxree Group of Companies' },\n        { key: 'companyAddress', label: 'Company Address', defaultValue: 'Ajmer, Rajasthan, India' },\n        { key: 'currency', label: 'Currency', defaultValue: 'INR' },\n      ],\n    },\n    {\n      title: 'Payroll Configuration',\n      icon: IndianRupee,\n      fields: [\n        { key: 'pfRate', label: 'PF Rate (%)', defaultValue: '12' },\n        { key: 'esiRate', label: 'ESI Rate (%)', defaultValue: '0.75' },\n        { key: 'gracePeriod', label: 'Late Grace Period (min)', defaultValue: '15' },\n        { key: 'otMultiplier', label: 'OT Multiplier', defaultValue: '1' },\n        { key: 'holidayOTMultiplier', label: 'Holiday OT Multiplier', defaultValue: '1' },\n      ],\n    },\n    {\n      title: 'Salary Formula Settings',\n      icon: Clock,\n      fields: [\n        { key: 'salaryFormula', label: 'Salary Formula', defaultValue: 'hourly' },\n        { key: 'sundayRule', label: 'Sunday Rule', defaultValue: 'earned_per_6_days' },\n      ],\n    },\n  ];\n\n  return (\n    <div className=\"space-y-4\">\n      <motion.div\n        initial={{ opacity: 0, y: -10 }}\n        animate={{ opacity: 1, y: 0 }}\n        className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3\"\n      >\n        <div>\n          <h2 className=\"text-xl font-bold flex items-center gap-2\">\n            <Settings className=\"w-5 h-5 text-gold\" />\n            Settings\n          </h2>\n          <p className=\"text-sm text-muted-foreground\">Configure your Laxree HRMS system</p>\n        </div>\n        <div className=\"flex gap-2\">\n          <Button variant=\"outline\" onClick={handleReseed}><RefreshCw className=\"w-4 h-4 mr-2\" /> Reset Demo Data</Button>\n          <Button className=\"gradient-laxree text-white\" onClick={handleSave}><Save className=\"w-4 h-4 mr-2\" /> Save Settings</Button>\n        </div>\n      </motion.div>\n\n      {/* Laxree Brand Card */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.05 }}\n      >\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardContent className=\"p-6\">\n            <div className=\"flex items-center gap-4\">\n              <div className=\"w-16 h-16 rounded-2xl gradient-laxree flex items-center justify-center overflow-hidden shadow-[0_0_20px_rgba(212,168,67,0.3)]\">\n                <Image src=\"/laxree-logo.png\" alt=\"Laxree\" width={52} height={52} className=\"rounded-xl\" />\n              </div>\n              <div>\n                <h3 className=\"text-lg font-bold text-gold-gradient\">Laxree Group of Companies</h3>\n                <p className=\"text-sm text-muted-foreground\">AI-Powered HRMS Dashboard &middot; Firms: LAPL, LRSL, SI, SDF</p>\n                <div className=\"flex items-center gap-2 mt-1\">\n                  <Badge variant=\"outline\" className=\"text-[10px]\">v2.0</Badge>\n                  <Badge variant=\"outline\" className=\"text-[10px]\">Enterprise</Badge>\n                  <Badge variant=\"outline\" className=\"text-[10px]\">AI Enabled</Badge>\n                </div>\n              </div>\n            </div>\n          </CardContent>\n        </Card>\n      </motion.div>\n\n      {settingGroups.map((group, gi) => {\n        const GroupIcon = group.icon;\n        return (\n          <motion.div\n            key={group.title}\n            initial={{ opacity: 0, y: 10 }}\n            animate={{ opacity: 1, y: 0 }}\n            transition={{ delay: 0.1 + gi * 0.05 }}\n          >\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardHeader className=\"pb-2\">\n                <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n                  <GroupIcon className=\"w-4 h-4 text-gold\" />\n                  {group.title}\n                </CardTitle>\n              </CardHeader>\n              <CardContent>\n                <div className=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n                  {group.fields.map((field) => (\n                    <div key={field.key}>\n                      <Label className=\"text-xs\">{field.label}</Label>\n                      {field.key === 'salaryFormula' ? (\n                        <Select\n                          value={settings[field.key] || field.defaultValue}\n                          onValueChange={(v) => setSettings({ ...settings, [field.key]: v })}\n                        >\n                          <SelectTrigger className=\"mt-1\">\n                            <SelectValue />\n                          </SelectTrigger>\n                          <SelectContent>\n                            <SelectItem value=\"hourly\">Hourly Rate Based</SelectItem>\n                            <SelectItem value=\"daily\">Daily Rate Based</SelectItem>\n                            <SelectItem value=\"monthly\">Monthly Fixed</SelectItem>\n                          </SelectContent>\n                        </Select>\n                      ) : field.key === 'sundayRule' ? (\n                        <Select\n                          value={settings[field.key] || field.defaultValue}\n                          onValueChange={(v) => setSettings({ ...settings, [field.key]: v })}\n                        >\n                          <SelectTrigger className=\"mt-1\">\n                            <SelectValue />\n                          </SelectTrigger>\n                          <SelectContent>\n                            <SelectItem value=\"earned_per_6_days\">Earned per 6 working days</SelectItem>\n                            <SelectItem value=\"fixed\">Fixed weekly off</SelectItem>\n                            <SelectItem value=\"compensatory\">Compensatory off</SelectItem>\n                          </SelectContent>\n                        </Select>\n                      ) : (\n                        <Input\n                          value={settings[field.key] || field.defaultValue || ''}\n                          onChange={e => setSettings({ ...settings, [field.key]: e.target.value })}\n                          className=\"mt-1\"\n                        />\n                      )}\n                    </div>\n                  ))}\n                </div>\n              </CardContent>\n            </Card>\n          </motion.div>\n        );\n      })}\n\n      {/* Salary Formula Info Card */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.3 }}\n      >\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardHeader className=\"pb-2\">\n            <CardTitle className=\"text-sm font-semibold flex items-center gap-2\">\n              <Info className=\"w-4 h-4 text-gold\" />\n              Laxree Salary Formula Reference\n            </CardTitle>\n          </CardHeader>\n          <CardContent>\n            <div className=\"space-y-2 text-sm text-muted-foreground\">\n              <div className=\"flex items-start gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5 mt-0.5 shrink-0\">Hourly</Badge>\n                <span>Gross = Total Worked Hours × Hourly Rate + OT Amount</span>\n              </div>\n              <div className=\"flex items-start gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5 mt-0.5 shrink-0\">Net</Badge>\n                <span>Net = Gross + Arrear − Total Deductions</span>\n              </div>\n              <div className=\"flex items-start gap-2\">\n                <Badge variant=\"outline\" className=\"text-[9px] h-4 px-1.5 mt-0.5 shrink-0\">Daily</Badge>\n                <span>Net = (Daily Rate × Days Present) + Sunday Amt − Deductions</span>\n              </div>\n              <Separator />\n              <p className=\"text-xs\">\n                Hourly Rate = Monthly Salary ÷ (Shift Hours × Days in Month) &nbsp;|&nbsp;\n                OT Rate = Hourly Rate × {settings.otMultiplier || '1'} (normal rate, NOT 1.5x) &nbsp;|&nbsp;\n                Holiday OT = Hourly Rate × {settings.holidayOTMultiplier || '2'}\n              </p>\n              <p className=\"text-xs\">\n                Sunday Rule: {settings.sundayRule === 'earned_per_6_days' ? 'Earned per 6 working days' :\n                  settings.sundayRule === 'fixed' ? 'Fixed weekly off' : 'Compensatory off'}\n              </p>\n            </div>\n          </CardContent>\n        </Card>\n      </motion.div>\n\n      {/* About */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.35 }}\n      >\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardHeader className=\"pb-2\">\n            <CardTitle className=\"text-sm font-semibold\">About</CardTitle>\n          </CardHeader>\n          <CardContent>\n            <div className=\"grid grid-cols-2 gap-2 text-sm\">\n              <div><span className=\"text-muted-foreground\">System:</span> Laxree HRMS</div>\n              <div><span className=\"text-muted-foreground\">Version:</span> 2.0.0</div>\n              <div><span className=\"text-muted-foreground\">License:</span> Enterprise</div>\n              <div><span className=\"text-muted-foreground\">Database:</span> SQLite / PostgreSQL (Auto)</div>\n              <div><span className=\"text-muted-foreground\">AI Engine:</span> Active</div>\n              <div><span className=\"text-muted-foreground\">Firms:</span> LAPL, LRSL, SI, SDF</div>\n            </div>\n          </CardContent>\n        </Card>\n      </motion.div>\n    </div>\n  );\n}\n","'use client';\n\nimport { useEffect, useState, useCallback } from 'react';\nimport { motion } from 'framer-motion';\nimport {\n  ArrowLeft, Mail, Phone, MapPin, Building2, Calendar,\n  Clock, FileText, IndianRupee, Briefcase, User,\n  AlertCircle, FolderOpen,\n} from 'lucide-react';\nimport { Card, CardContent } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';\nimport { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';\nimport { ScrollArea } from '@/components/ui/scroll-area';\nimport { useHRMSStore } from '@/lib/store';\n\n// ── Firm badge class map ──\nconst FIRM_BADGE_CLASS: Record<string, string> = {\n  LAPL: 'firm-badge-lapl',\n  LRSL: 'firm-badge-lrsl',\n  SI: 'firm-badge-si',\n  SDF: 'firm-badge-sdf',\n  Roofing: 'firm-badge-roofing',\n};\n\n// ── Convert decimal hours to HH.MM display format ──\nfunction formatHours(decimal: number): string {\n  if (!decimal || decimal === 0) return '0.00';\n  const hours = Math.floor(decimal);\n  const minutes = Math.round((decimal - hours) * 60);\n  if (minutes >= 60) return `${hours + 1}.00`;\n  return `${hours}.${String(minutes).padStart(2, '0')}`;\n}\n\n// ── Employee Data Type ──\ninterface EmployeeData {\n  id: string;\n  employeeId: string;\n  fullName: string;\n  mobile: string | null;\n  email: string | null;\n  department: string;\n  location: string;\n  designation: string;\n  joiningDate: string;\n  salaryType: string;\n  basicSalary: number;\n  dailyRate: number;\n  perDaySalary: number;\n  overtimeRate: number;\n  shiftStart: string;\n  shiftEnd: string;\n  shiftHours: number;\n  employmentType: string;\n  status: string;\n  panNumber: string | null;\n  aadhaarNumber: string | null;\n  pfNumber: string | null;\n  esiNumber: string | null;\n  bankName: string | null;\n  bankAccount: string | null;\n  bankIfsc: string | null;\n  address: string | null;\n  attendance: any[];\n  payrolls: any[];\n  leaves: any[];\n  overtimes: any[];\n}\n\n// ── Attendance status badge ──\nconst AttStatusBadge = ({ status }: { status: string }) => {\n  const config: Record<string, { bg: string; text: string; label: string }> = {\n    present: { bg: 'bg-emerald-500/15 border-emerald-500/20', text: 'text-emerald-600 dark:text-emerald-400', label: 'Present' },\n    late: { bg: 'bg-yellow-500/15 border-yellow-500/20', text: 'text-yellow-600 dark:text-yellow-400', label: 'Late' },\n    absent: { bg: 'bg-red-500/15 border-red-500/20', text: 'text-red-600 dark:text-red-400', label: 'Absent' },\n    'half-day': { bg: 'bg-orange-500/15 border-orange-500/20', text: 'text-orange-600 dark:text-orange-400', label: 'Half-Day' },\n    holiday: { bg: 'bg-purple-500/15 border-purple-500/20', text: 'text-purple-600 dark:text-purple-400', label: 'Holiday' },\n    'weekly-off': { bg: 'bg-blue-500/15 border-blue-500/20', text: 'text-blue-600 dark:text-blue-400', label: 'Weekly Off' },\n  };\n  const s = config[status] || { bg: 'bg-muted border-border', text: 'text-muted-foreground', label: status };\n  return (\n    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border ${s.bg} ${s.text}`}>\n      {s.label}\n    </span>\n  );\n};\n\n// ── Leave status badge ──\nconst LeaveStatusBadge = ({ status }: { status: string }) => {\n  const map: Record<string, { bg: string; text: string }> = {\n    approved: { bg: 'bg-emerald-500/15 border-emerald-500/20', text: 'text-emerald-600 dark:text-emerald-400' },\n    rejected: { bg: 'bg-red-500/15 border-red-500/20', text: 'text-red-600 dark:text-red-400' },\n    pending: { bg: 'bg-yellow-500/15 border-yellow-500/20', text: 'text-yellow-600 dark:text-yellow-400' },\n  };\n  const s = map[status] || { bg: 'bg-muted border-border', text: 'text-muted-foreground' };\n  return (\n    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border ${s.bg} ${s.text}`}>\n      {status.charAt(0).toUpperCase() + status.slice(1)}\n    </span>\n  );\n};\n\nexport function EmployeeProfile() {\n  const { selectedEmployeeId, setCurrentPage } = useHRMSStore();\n  const [employee, setEmployee] = useState<EmployeeData | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  const loadEmployee = useCallback(async () => {\n    if (selectedEmployeeId) {\n      setLoading(true);\n      try {\n        const res = await fetch(`/api/employees/${selectedEmployeeId}`);\n        const data = await res.json();\n        setEmployee(data);\n      } catch {\n        setEmployee(null);\n      }\n      setLoading(false);\n    }\n  }, [selectedEmployeeId]);\n\n  useEffect(() => { loadEmployee(); }, [loadEmployee]);\n\n  if (loading) {\n    return (\n      <div className=\"space-y-4\">\n        <div className=\"h-10 w-32 bg-muted/50 rounded animate-pulse\" />\n        <div className=\"h-40 bg-muted/50 rounded-xl animate-pulse\" />\n        <div className=\"h-64 bg-muted/50 rounded-xl animate-pulse\" />\n      </div>\n    );\n  }\n\n  if (!employee) {\n    return (\n      <div className=\"flex flex-col items-center justify-center min-h-[60vh] glass-card card-gold-hover p-8\">\n        <div className=\"w-16 h-16 rounded-2xl gradient-laxree flex items-center justify-center mb-4\">\n          <User className=\"w-8 h-8 text-white\" />\n        </div>\n        <h2 className=\"text-xl font-bold mb-2\">No Employee Selected</h2>\n        <p className=\"text-muted-foreground text-sm text-center max-w-md\">\n          Select an employee from the Employee Management page to view their profile.\n        </p>\n        <Button\n          variant=\"outline\"\n          className=\"mt-4\"\n          onClick={() => setCurrentPage('employees')}\n        >\n          Go to Employees\n        </Button>\n      </div>\n    );\n  }\n\n  // ── Quick stats ──\n  const quickStats = [\n    {\n      icon: IndianRupee,\n      label: 'Monthly Salary',\n      value: `₹${(employee.basicSalary ?? employee.monthlySalary ?? 0).toLocaleString('en-IN')}`,\n      color: 'text-gold',\n    },\n    {\n      icon: Calendar,\n      label: 'Joining Date',\n      value: new Date(employee.joiningDate).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }),\n      color: 'text-cyan-500',\n    },\n    {\n      icon: Clock,\n      label: 'Shift',\n      value: `${employee.shiftStart} – ${employee.shiftEnd}`,\n      color: 'text-amber-500',\n    },\n    {\n      icon: Briefcase,\n      label: 'Employment',\n      value: employee.employmentType || 'Full Time',\n      color: 'text-violet-500',\n    },\n  ];\n\n  return (\n    <div className=\"space-y-4\">\n      {/* ── Back button ── */}\n      <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }}>\n        <Button variant=\"ghost\" onClick={() => setCurrentPage('employees')} className=\"gap-1.5\">\n          <ArrowLeft className=\"w-4 h-4\" /> Back to Employees\n        </Button>\n      </motion.div>\n\n      {/* ── Profile Header ── */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.05 }}\n      >\n        <Card className=\"glass-card card-gold-hover border-0\">\n          <CardContent className=\"p-6\">\n            <div className=\"flex flex-col sm:flex-row items-start gap-4\">\n              {/* Avatar */}\n              <div className=\"w-16 h-16 rounded-full gradient-laxree flex items-center justify-center text-white text-2xl font-bold shadow-lg shrink-0\">\n                {employee.fullName.charAt(0).toUpperCase()}\n              </div>\n\n              {/* Info */}\n              <div className=\"flex-1 min-w-0\">\n                <div className=\"flex flex-wrap items-center gap-2 mb-1\">\n                  <h2 className=\"text-2xl font-bold\">{employee.fullName}</h2>\n                  <span className={FIRM_BADGE_CLASS[employee.department] || 'firm-badge-lapl'}>\n                    {employee.department}\n                  </span>\n                  <span\n                    className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border ${\n                      employee.status === 'Yes'\n                        ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/20'\n                        : 'bg-red-500/15 text-red-600 dark:text-red-400 border-red-500/20'\n                    }`}\n                  >\n                    <span className={`w-1.5 h-1.5 rounded-full mr-1 ${employee.status === 'Yes' ? 'bg-emerald-500' : 'bg-red-500'}`} />\n                    {employee.status === 'Yes' ? 'Active' : 'Inactive'}\n                  </span>\n                </div>\n                <div className=\"flex flex-wrap items-center gap-3 text-sm text-muted-foreground\">\n                  <span className=\"flex items-center gap-1\">\n                    <MapPin className=\"w-3.5 h-3.5\" /> {employee.location}\n                  </span>\n                  <span>•</span>\n                  <span>{employee.designation}</span>\n                  <span>•</span>\n                  <span className=\"font-mono text-xs\">{employee.employeeId}</span>\n                </div>\n\n                {/* Contact info row */}\n                <div className=\"flex flex-wrap items-center gap-4 mt-3 text-xs text-muted-foreground\">\n                  {employee.email && (\n                    <span className=\"flex items-center gap-1\">\n                      <Mail className=\"w-3 h-3\" /> {employee.email}\n                    </span>\n                  )}\n                  {employee.mobile && (\n                    <span className=\"flex items-center gap-1\">\n                      <Phone className=\"w-3 h-3\" /> {employee.mobile}\n                    </span>\n                  )}\n                </div>\n              </div>\n            </div>\n\n            {/* Quick Stats Row */}\n            <div className=\"grid grid-cols-2 md:grid-cols-4 gap-3 mt-6\">\n              {quickStats.map((stat, i) => {\n                const Icon = stat.icon;\n                return (\n                  <motion.div\n                    key={stat.label}\n                    initial={{ opacity: 0, y: 10 }}\n                    animate={{ opacity: 1, y: 0 }}\n                    transition={{ delay: 0.1 + i * 0.05 }}\n                    className=\"flex items-center gap-2.5 p-3 rounded-lg bg-muted/30 border border-border/30\"\n                  >\n                    <div className={`w-8 h-8 rounded-lg bg-muted/80 flex items-center justify-center shrink-0`}>\n                      <Icon className={`w-4 h-4 ${stat.color}`} />\n                    </div>\n                    <div className=\"min-w-0\">\n                      <p className=\"text-[10px] text-muted-foreground\">{stat.label}</p>\n                      <p className=\"text-sm font-semibold truncate\">{stat.value}</p>\n                    </div>\n                  </motion.div>\n                );\n              })}\n            </div>\n          </CardContent>\n        </Card>\n      </motion.div>\n\n      {/* ── Tab Panels ── */}\n      <motion.div\n        initial={{ opacity: 0, y: 10 }}\n        animate={{ opacity: 1, y: 0 }}\n        transition={{ delay: 0.2 }}\n      >\n        <Tabs defaultValue=\"attendance\" className=\"space-y-4\">\n          <TabsList className=\"bg-muted/50\">\n            <TabsTrigger value=\"attendance\" className=\"text-xs\">Attendance</TabsTrigger>\n            <TabsTrigger value=\"payroll\" className=\"text-xs\">Payroll</TabsTrigger>\n            <TabsTrigger value=\"leaves\" className=\"text-xs\">Leaves</TabsTrigger>\n            <TabsTrigger value=\"overtime\" className=\"text-xs\">Overtime</TabsTrigger>\n            <TabsTrigger value=\"documents\" className=\"text-xs\">Documents</TabsTrigger>\n          </TabsList>\n\n          {/* ── Attendance Tab ── */}\n          <TabsContent value=\"attendance\" className=\"mt-4\">\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-0\">\n                <ScrollArea className=\"max-h-[50vh]\">\n                  <Table>\n                    <TableHeader>\n                      <TableRow className=\"hover:bg-transparent\">\n                        <TableHead>Date</TableHead>\n                        <TableHead>Check-In</TableHead>\n                        <TableHead>Check-Out</TableHead>\n                        <TableHead>Hours</TableHead>\n                        <TableHead>Status</TableHead>\n                        <TableHead className=\"hidden md:table-cell\">OT</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {employee.attendance?.length > 0 ? (\n                        employee.attendance.map((a: any) => (\n                          <TableRow key={a.id} className=\"hover:bg-muted/30\">\n                            <TableCell className=\"text-sm\">\n                              {new Date(a.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}\n                            </TableCell>\n                            <TableCell className=\"text-sm font-mono\">{a.checkIn || '—'}</TableCell>\n                            <TableCell className=\"text-sm font-mono\">{a.checkOut || '—'}</TableCell>\n                            <TableCell className=\"text-sm font-medium\">\n                              {a.totalHours > 0 ? `${formatHours(a.totalHours)}h` : '—'}\n                            </TableCell>\n                            <TableCell><AttStatusBadge status={a.status} /></TableCell>\n                            <TableCell className=\"hidden md:table-cell text-sm\">\n                              {a.overtimeHours > 0 ? (\n                                <span className=\"text-cyan-600 dark:text-cyan-400 font-medium\">{formatHours(a.overtimeHours)}h</span>\n                              ) : '—'}\n                            </TableCell>\n                          </TableRow>\n                        ))\n                      ) : (\n                        <TableRow>\n                          <TableCell colSpan={6} className=\"text-center py-8 text-muted-foreground text-sm\">\n                            No attendance records\n                          </TableCell>\n                        </TableRow>\n                      )}\n                    </TableBody>\n                  </Table>\n                </ScrollArea>\n              </CardContent>\n            </Card>\n          </TabsContent>\n\n          {/* ── Payroll Tab ── */}\n          <TabsContent value=\"payroll\" className=\"mt-4\">\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-0\">\n                <ScrollArea className=\"max-h-[50vh]\">\n                  <Table>\n                    <TableHeader>\n                      <TableRow className=\"hover:bg-transparent\">\n                        <TableHead>Period</TableHead>\n                        <TableHead>Work Hours</TableHead>\n                        <TableHead>Gross</TableHead>\n                        <TableHead>Deductions</TableHead>\n                        <TableHead>Net Salary</TableHead>\n                        <TableHead>Status</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {employee.payrolls?.length > 0 ? (\n                        employee.payrolls.map((p: any) => (\n                          <TableRow key={p.id} className=\"hover:bg-muted/30\">\n                            <TableCell className=\"text-sm font-medium\">\n                              {new Date(p.year, p.month - 1).toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}\n                            </TableCell>\n                            <TableCell className=\"text-sm text-muted-foreground\">\n                              {p.totalWorkHours > 0 ? `${p.totalWorkHours}h` : '—'}\n                            </TableCell>\n                            <TableCell className=\"text-sm\">₹{p.grossSalary.toLocaleString('en-IN')}</TableCell>\n                            <TableCell className=\"text-sm text-red-500\">₹{p.totalDeductions.toLocaleString('en-IN')}</TableCell>\n                            <TableCell className=\"text-sm font-bold text-gold\">\n                              ₹{p.netSalary.toLocaleString('en-IN')}\n                            </TableCell>\n                            <TableCell>\n                              <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border ${\n                                p.status === 'generated'\n                                  ? 'bg-yellow-500/15 text-yellow-600 dark:text-yellow-400 border-yellow-500/20'\n                                  : p.status === 'paid'\n                                    ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/20'\n                                    : 'bg-muted text-muted-foreground border-border'\n                              }`}>\n                                {p.status}\n                              </span>\n                            </TableCell>\n                          </TableRow>\n                        ))\n                      ) : (\n                        <TableRow>\n                          <TableCell colSpan={6} className=\"text-center py-8 text-muted-foreground text-sm\">\n                            No payroll records\n                          </TableCell>\n                        </TableRow>\n                      )}\n                    </TableBody>\n                  </Table>\n                </ScrollArea>\n              </CardContent>\n            </Card>\n          </TabsContent>\n\n          {/* ── Leaves Tab ── */}\n          <TabsContent value=\"leaves\" className=\"mt-4\">\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-0\">\n                <ScrollArea className=\"max-h-[50vh]\">\n                  <Table>\n                    <TableHeader>\n                      <TableRow className=\"hover:bg-transparent\">\n                        <TableHead>Type</TableHead>\n                        <TableHead>Start</TableHead>\n                        <TableHead>End</TableHead>\n                        <TableHead>Days</TableHead>\n                        <TableHead>Reason</TableHead>\n                        <TableHead>Status</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {employee.leaves?.length > 0 ? (\n                        employee.leaves.map((l: any) => (\n                          <TableRow key={l.id} className=\"hover:bg-muted/30\">\n                            <TableCell className=\"text-sm font-medium\">{l.type}</TableCell>\n                            <TableCell className=\"text-sm\">\n                              {new Date(l.startDate).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}\n                            </TableCell>\n                            <TableCell className=\"text-sm\">\n                              {new Date(l.endDate).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}\n                            </TableCell>\n                            <TableCell className=\"text-sm\">{l.days}</TableCell>\n                            <TableCell className=\"text-sm text-muted-foreground max-w-[200px] truncate\">\n                              {l.reason || '—'}\n                            </TableCell>\n                            <TableCell><LeaveStatusBadge status={l.status} /></TableCell>\n                          </TableRow>\n                        ))\n                      ) : (\n                        <TableRow>\n                          <TableCell colSpan={6} className=\"text-center py-8 text-muted-foreground text-sm\">\n                            No leave records\n                          </TableCell>\n                        </TableRow>\n                      )}\n                    </TableBody>\n                  </Table>\n                </ScrollArea>\n              </CardContent>\n            </Card>\n          </TabsContent>\n\n          {/* ── Overtime Tab ── */}\n          <TabsContent value=\"overtime\" className=\"mt-4\">\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-0\">\n                <ScrollArea className=\"max-h-[50vh]\">\n                  <Table>\n                    <TableHeader>\n                      <TableRow className=\"hover:bg-transparent\">\n                        <TableHead>Date</TableHead>\n                        <TableHead>Hours</TableHead>\n                        <TableHead>Rate</TableHead>\n                        <TableHead>Amount</TableHead>\n                        <TableHead className=\"hidden md:table-cell\">Sunday</TableHead>\n                        <TableHead className=\"hidden md:table-cell\">Holiday</TableHead>\n                      </TableRow>\n                    </TableHeader>\n                    <TableBody>\n                      {employee.overtimes?.length > 0 ? (\n                        employee.overtimes.map((o: any) => (\n                          <TableRow key={o.id} className=\"hover:bg-muted/30\">\n                            <TableCell className=\"text-sm\">\n                              {new Date(o.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}\n                            </TableCell>\n                            <TableCell className=\"text-sm font-medium\">{o.hours}h</TableCell>\n                            <TableCell className=\"text-sm\">₹{o.rate}/hr</TableCell>\n                            <TableCell className=\"text-sm font-bold text-gold\">\n                              ₹{o.amount.toLocaleString('en-IN')}\n                            </TableCell>\n                            <TableCell className=\"hidden md:table-cell text-sm\">\n                              {o.isSunday ? (\n                                <span className=\"text-blue-600 dark:text-blue-400 font-medium\">Yes</span>\n                              ) : 'No'}\n                            </TableCell>\n                            <TableCell className=\"hidden md:table-cell text-sm\">\n                              {o.isHoliday ? (\n                                <span className=\"text-purple-600 dark:text-purple-400 font-medium\">Yes</span>\n                              ) : 'No'}\n                            </TableCell>\n                          </TableRow>\n                        ))\n                      ) : (\n                        <TableRow>\n                          <TableCell colSpan={6} className=\"text-center py-8 text-muted-foreground text-sm\">\n                            No overtime records\n                          </TableCell>\n                        </TableRow>\n                      )}\n                    </TableBody>\n                  </Table>\n                </ScrollArea>\n              </CardContent>\n            </Card>\n          </TabsContent>\n\n          {/* ── Documents Tab ── */}\n          <TabsContent value=\"documents\" className=\"mt-4\">\n            <Card className=\"glass-card card-gold-hover border-0\">\n              <CardContent className=\"p-8\">\n                <div className=\"flex flex-col items-center justify-center text-center\">\n                  <div className=\"w-14 h-14 rounded-2xl bg-muted/50 flex items-center justify-center mb-4\">\n                    <FolderOpen className=\"w-7 h-7 text-muted-foreground\" />\n                  </div>\n                  <h3 className=\"text-lg font-semibold mb-2\">Document Management</h3>\n                  <p className=\"text-sm text-muted-foreground max-w-md\">\n                    Document upload and management features are under development. Employees will be able to upload and manage their documents here.\n                  </p>\n                </div>\n              </CardContent>\n            </Card>\n          </TabsContent>\n        </Tabs>\n      </motion.div>\n    </div>\n  );\n}\n","'use client';\n\n// ════════════════════════════════════════════════════════════════════════\n// v24·0625 — AttendanceQueries (HRMS side)\n// ════════════════════════════════════════════════════════════════════════\n// HR uses this page to view attendance queries raised by ERP employees\n// and respond to them. The page calls ERP's external API via a server-side\n// proxy at /api/erp-bridge/attendance-queries (which adds the API key\n// header so the browser never sees the secret).\n//\n// SAFETY: HR can ONLY respond to queries. They cannot modify attendance\n// data — that requires direct HRMS admin access (separate flow).\n// The response is stored in ERP's AttendanceQuery table.\n// ════════════════════════════════════════════════════════════════════════\n\nimport { useEffect, useState } from 'react';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Button } from '@/components/ui/button';\nimport { Textarea } from '@/components/ui/textarea';\nimport { Badge } from '@/components/ui/badge';\nimport { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';\nimport { useHRMSStore } from '@/lib/store';\nimport { toast } from 'sonner';\nimport { MessageSquareText, Send, RefreshCw, Clock, CheckCircle2, AlertCircle } from 'lucide-react';\n\ninterface AttendanceQuery {\n  id: string;\n  userId: string;\n  hrmsEmployeeId: string | null;\n  queryMonth: number;\n  queryYear: number;\n  queryText: string;\n  status: string;\n  hrReply: string | null;\n  repliedBy: string | null;\n  repliedAt: string | null;\n  createdAt: string;\n  user: {\n    id: string;\n    name: string;\n    email: string;\n    department: string | null;\n    designation: string | null;\n    phone: string | null;\n  };\n}\n\nconst months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\n\nexport function AttendanceQueries() {\n  const { adminName } = useHRMSStore();\n  const [queries, setQueries] = useState<AttendanceQuery[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const [filter, setFilter] = useState<'ALL' | 'OPEN' | 'RESPONDED' | 'CLOSED'>('OPEN');\n  const [respondingTo, setRespondingTo] = useState<string | null>(null);\n  const [replyText, setReplyText] = useState('');\n  const [submitting, setSubmitting] = useState(false);\n\n  const fetchQueries = async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const res = await fetch(`/api/erp-bridge/attendance-queries?status=${filter === 'ALL' ? '' : filter}`, {\n        method: 'GET',\n        headers: { 'Content-Type': 'application/json' },\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data?.error || 'Failed to fetch queries');\n      setQueries(Array.isArray(data.queries) ? data.queries : []);\n    } catch (err: any) {\n      setError(err?.message || 'Unknown error');\n      setQueries([]);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  useEffect(() => {\n    fetchQueries();\n    // Auto-refresh every 30 seconds so HR sees new queries without manual refresh\n    const t = setInterval(fetchQueries, 30000);\n    return () => clearInterval(t);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [filter]);\n\n  const submitResponse = async (queryId: string) => {\n    if (!replyText.trim()) {\n      toast.error('Please enter a reply before submitting.');\n      return;\n    }\n    setSubmitting(true);\n    try {\n      const res = await fetch(`/api/erp-bridge/attendance-queries/${queryId}/respond`, {\n        method: 'PATCH',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          hrReply: replyText.trim(),\n          repliedBy: adminName || 'HR',\n          status: 'RESPONDED',\n        }),\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data?.error || 'Failed to respond');\n      toast.success('Reply sent to employee.');\n      setReplyText('');\n      setRespondingTo(null);\n      fetchQueries();\n    } catch (err: any) {\n      toast.error(err?.message || 'Failed to send reply.');\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  const closeQuery = async (queryId: string) => {\n    setSubmitting(true);\n    try {\n      const res = await fetch(`/api/erp-bridge/attendance-queries/${queryId}/respond`, {\n        method: 'PATCH',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          hrReply: 'Query closed by HR.',\n          repliedBy: adminName || 'HR',\n          status: 'CLOSED',\n        }),\n      });\n      if (!res.ok) {\n        const data = await res.json();\n        throw new Error(data?.error || 'Failed to close');\n      }\n      toast.success('Query closed.');\n      fetchQueries();\n    } catch (err: any) {\n      toast.error(err?.message || 'Failed to close query.');\n    } finally {\n      setSubmitting(false);\n    }\n  };\n\n  const filtered = filter === 'ALL' ? queries : queries.filter(q => q.status === filter);\n\n  return (\n    <div className=\"space-y-6\">\n      {/* Header */}\n      <div className=\"flex items-center justify-between flex-wrap gap-3\">\n        <div>\n          <h1 className=\"text-2xl font-bold flex items-center gap-2\">\n            <MessageSquareText className=\"w-6 h-6 text-amber-500\" />\n            ERP Attendance Queries\n          </h1>\n          <p className=\"text-sm text-muted-foreground mt-1\">\n            Queries raised by ERP employees about their HRMS attendance. Respond directly — replies are stored in ERP.\n          </p>\n        </div>\n        <div className=\"flex items-center gap-2\">\n          <Select value={filter} onValueChange={(v) => setFilter(v as any)}>\n            <SelectTrigger className=\"w-[140px]\">\n              <SelectValue />\n            </SelectTrigger>\n            <SelectContent>\n              <SelectItem value=\"OPEN\">Open</SelectItem>\n              <SelectItem value=\"RESPONDED\">Responded</SelectItem>\n              <SelectItem value=\"CLOSED\">Closed</SelectItem>\n              <SelectItem value=\"ALL\">All</SelectItem>\n            </SelectContent>\n          </Select>\n          <Button variant=\"outline\" size=\"icon\" onClick={fetchQueries} disabled={loading}>\n            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />\n          </Button>\n        </div>\n      </div>\n\n      {/* Error banner */}\n      {error && (\n        <Card className=\"border-red-500/40 bg-red-500/5\">\n          <CardContent className=\"pt-6 flex items-start gap-3\">\n            <AlertCircle className=\"w-5 h-5 text-red-500 mt-0.5 flex-shrink-0\" />\n            <div className=\"text-sm flex-1 min-w-0\">\n              <div className=\"font-semibold text-red-500\">Cannot reach ERP bridge</div>\n              <div className=\"text-muted-foreground mt-1\">{error}</div>\n              <div className=\"text-muted-foreground mt-3 text-xs leading-relaxed\">\n                To enable this page, the HRMS admin needs to set <strong>two environment variables</strong> on the HRMS Vercel project:\n              </div>\n              <ul className=\"text-xs text-muted-foreground mt-2 ml-4 list-disc space-y-1\">\n                <li>\n                  <code className=\"px-1 py-0.5 rounded bg-muted\">ERP_BRIDGE_URL</code> — base URL of the ERP deployment\n                  (e.g. <code className=\"px-1 py-0.5 rounded bg-muted\">https://erp-ea.vercel.app</code>)\n                </li>\n                <li>\n                  <code className=\"px-1 py-0.5 rounded bg-muted\">ERP_BRIDGE_API_KEY</code> — shared secret that must\n                  <strong> exactly match</strong> the <code className=\"px-1 py-0.5 rounded bg-muted\">ERP_BRIDGE_API_KEY</code> set on the ERP Vercel project.\n                </li>\n              </ul>\n              <div className=\"text-xs text-muted-foreground mt-3 pt-3 border-t border-border/60\">\n                <strong>Steps:</strong>\n                <ol className=\"list-decimal ml-4 mt-1 space-y-0.5\">\n                  <li>Open Vercel → HRMS project → Settings → Environment Variables</li>\n                  <li>Add the two variables above (Production + Preview environments)</li>\n                  <li>Trigger a redeploy (Redeploy button on the Deployments tab)</li>\n                  <li>Come back to this page — queries from ERP employees will appear here</li>\n                </ol>\n              </div>\n              <div className=\"text-xs text-muted-foreground mt-3 pt-3 border-t border-border/60\">\n                <strong className=\"text-foreground\">Also required on the ERP side:</strong> the ERP Vercel project must set\n                <code className=\"mx-1 px-1 py-0.5 rounded bg-muted\">HRMS_BRIDGE_URL</code> (this HRMS deployment URL) and\n                <code className=\"mx-1 px-1 py-0.5 rounded bg-muted\">HRMS_BRIDGE_API_KEY</code> (same value as\n                <code className=\"mx-1 px-1 py-0.5 rounded bg-muted\">HRMS_BRIDGE_API_KEY</code> on HRMS) — otherwise ERP employees\n                cannot see their attendance or raise queries.\n              </div>\n              {error.includes('401') && (\n                <div className=\"text-xs mt-3 pt-3 border-t border-border/60 bg-amber-500/10 -mx-3 px-3 py-2 rounded-md\">\n                  <strong className=\"text-amber-700 dark:text-amber-400\">⚠ HTTP 401 specific guidance:</strong>{' '}\n                  A 401 means HRMS reached ERP successfully, but ERP rejected the shared secret. If you have\n                  <em> already </em> set <code className=\"px-1 py-0.5 rounded bg-muted\">ERP_BRIDGE_API_KEY</code> on\n                  <em> both </em> Vercel projects with the same value, the most likely cause is that\n                  <strong> at least one of the projects has not been redeployed since the env var was added</strong>.\n                  Vercel only applies new env vars on the <strong>next</strong> deployment — running deployments\n                  keep using the old environment. Fix: trigger a redeploy on <strong>both</strong> the ERP and HRMS\n                  Vercel projects (Deployments tab → ⋮ → Redeploy), then come back to this page.\n                </div>\n              )}\n            </div>\n          </CardContent>\n        </Card>\n      )}\n\n      {/* Empty state */}\n      {!loading && !error && filtered.length === 0 && (\n        <Card>\n          <CardContent className=\"py-12 flex flex-col items-center text-center\">\n            <CheckCircle2 className=\"w-12 h-12 text-green-500 mb-3\" />\n            <div className=\"text-lg font-semibold\">No {filter !== 'ALL' ? filter.toLowerCase() : ''} queries</div>\n            <p className=\"text-sm text-muted-foreground mt-1\">\n              {filter === 'OPEN'\n                ? 'All caught up. New queries from ERP will appear here automatically.'\n                : `No ${filter.toLowerCase()} queries found. Try a different filter.`}\n            </p>\n          </CardContent>\n        </Card>\n      )}\n\n      {/* Query cards */}\n      <div className=\"grid gap-4\">\n        {filtered.map((q) => {\n          const isResponding = respondingTo === q.id;\n          const isOpen = q.status === 'OPEN';\n          return (\n            <Card key={q.id} className={isOpen ? 'border-amber-500/40' : ''}>\n              <CardHeader className=\"pb-3\">\n                <div className=\"flex items-start justify-between gap-3\">\n                  <div className=\"flex-1 min-w-0\">\n                    <CardTitle className=\"text-base flex items-center gap-2\">\n                      <span>{q.user.name}</span>\n                      <Badge\n                        variant={q.status === 'OPEN' ? 'default' : q.status === 'RESPONDED' ? 'secondary' : 'outline'}\n                        className={q.status === 'OPEN' ? 'bg-amber-500 text-black hover:bg-amber-500' : ''}\n                      >\n                        {q.status}\n                      </Badge>\n                    </CardTitle>\n                    <div className=\"text-xs text-muted-foreground mt-1 flex flex-wrap gap-x-3 gap-y-1\">\n                      <span>📧 {q.user.email || '—'}</span>\n                      <span>🏢 {q.user.department || '—'}</span>\n                      <span>📱 {q.user.phone || '—'}</span>\n                      <span>🕒 {new Date(q.createdAt).toLocaleString('en-IN')}</span>\n                    </div>\n                  </div>\n                  <div className=\"text-right flex-shrink-0\">\n                    <div className=\"text-xs text-muted-foreground uppercase tracking-wide\">For</div>\n                    <div className=\"text-sm font-semibold\">\n                      {months[q.queryMonth - 1]} {q.queryYear}\n                    </div>\n                    {q.hrmsEmployeeId && (\n                      <div className=\"text-[10px] text-muted-foreground mt-0.5\">\n                        HRMS ID: {q.hrmsEmployeeId}\n                      </div>\n                    )}\n                  </div>\n                </div>\n              </CardHeader>\n              <CardContent className=\"space-y-3\">\n                {/* Query text */}\n                <div className=\"text-sm bg-muted/50 rounded-md p-3 border-l-2 border-amber-500/60\">\n                  <div className=\"text-[10px] uppercase tracking-wide text-muted-foreground font-semibold mb-1\">\n                    Employee's Query\n                  </div>\n                  {q.queryText}\n                </div>\n\n                {/* Existing reply */}\n                {q.hrReply && (\n                  <div className=\"text-sm bg-green-500/5 rounded-md p-3 border-l-2 border-green-500/60\">\n                    <div className=\"text-[10px] uppercase tracking-wide text-green-600 font-semibold mb-1 flex items-center gap-1\">\n                      <CheckCircle2 className=\"w-3 h-3\" />\n                      HR Reply · {q.repliedBy || 'HR'} · {q.repliedAt ? new Date(q.repliedAt).toLocaleString('en-IN') : ''}\n                    </div>\n                    {q.hrReply}\n                  </div>\n                )}\n\n                {/* Respond form */}\n                {isResponding ? (\n                  <div className=\"space-y-2\">\n                    <Textarea\n                      placeholder=\"Type your response to the employee…\"\n                      value={replyText}\n                      onChange={(e) => setReplyText(e.target.value)}\n                      rows={3}\n                      autoFocus\n                    />\n                    <div className=\"flex gap-2 justify-end\">\n                      <Button\n                        variant=\"outline\"\n                        size=\"sm\"\n                        onClick={() => { setRespondingTo(null); setReplyText(''); }}\n                        disabled={submitting}\n                      >\n                        Cancel\n                      </Button>\n                      <Button\n                        size=\"sm\"\n                        onClick={() => submitResponse(q.id)}\n                        disabled={submitting || !replyText.trim()}\n                      >\n                        <Send className=\"w-3.5 h-3.5 mr-1\" />\n                        {submitting ? 'Sending…' : 'Send Reply'}\n                      </Button>\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"flex gap-2 justify-end\">\n                    {q.status !== 'CLOSED' && (\n                      <Button\n                        variant=\"outline\"\n                        size=\"sm\"\n                        onClick={() => closeQuery(q.id)}\n                        disabled={submitting}\n                      >\n                        Close\n                      </Button>\n                    )}\n                    {isOpen && (\n                      <Button\n                        size=\"sm\"\n                        onClick={() => { setRespondingTo(q.id); setReplyText(q.hrReply || ''); }}\n                      >\n                        <MessageSquareText className=\"w-3.5 h-3.5 mr-1\" />\n                        {q.hrReply ? 'Update Reply' : 'Respond'}\n                      </Button>\n                    )}\n                  </div>\n                )}\n              </CardContent>\n            </Card>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n","'use client';\n\nimport { useHRMSStore } from '@/lib/store';\nimport { Moon, Sun, Menu, Clock, LogOut, Crown } from 'lucide-react';\nimport { Button } from '@/components/ui/button';\nimport { useEffect, useState } from 'react';\nimport { motion } from 'framer-motion';\nimport { toast } from 'sonner';\nimport Image from 'next/image';\n\nexport function Header() {\n  const { currentPage, darkMode, toggleDarkMode, setCurrentPage, setSidebarOpen, sidebarOpen, selectedFirm, adminName, logout } = useHRMSStore();\n  const [clock, setClock] = useState('');\n\n  const displayName = adminName || 'Admin';\n\n  // Real-time IST clock\n  useEffect(() => {\n    const updateClock = () => {\n      const now = new Date();\n      const istOffset = 5.5 * 60 * 60 * 1000;\n      const ist = new Date(now.getTime() + istOffset + now.getTimezoneOffset() * 60000);\n      const hh = String(ist.getHours()).padStart(2, '0');\n      const mm = String(ist.getMinutes()).padStart(2, '0');\n      const ss = String(ist.getSeconds()).padStart(2, '0');\n      setClock(`${hh}:${mm}:${ss}`);\n    };\n    updateClock();\n    const interval = setInterval(updateClock, 1000);\n    return () => clearInterval(interval);\n  }, []);\n\n  const pageTitle: Record<string, string> = {\n    dashboard: 'Dashboard',\n    employees: 'Employee Management',\n    attendance: 'Attendance Tracker',\n    payroll: 'Payroll Automation',\n    leaves: 'Leave Management',\n    holidays: 'Holiday Calendar',\n    overtime: 'Overtime Management',\n    departments: 'Department Management',\n    reports: 'Reports & Analytics',\n    'ai-assistant': 'AI HR Assistant',\n    'salary-slip': 'Salary Slip Generator',\n    settings: 'Settings',\n    'employee-profile': 'Employee Profile',\n  };\n\n  const firmLabel = selectedFirm && selectedFirm !== '__all__' ? selectedFirm : 'All Firms';\n\n  const handleLogout = () => {\n    logout();\n    toast.success('Logged out successfully');\n  };\n\n  return (\n    <header className=\"header-blur flex items-center justify-between h-14 px-3 md:px-6 z-10 gap-2\">\n      <div className=\"flex items-center gap-2 min-w-0 flex-1 overflow-hidden\">\n        <Button variant=\"ghost\" size=\"icon\" className=\"md:hidden shrink-0 h-8 w-8\" onClick={() => setSidebarOpen(!sidebarOpen)}>\n          <Menu className=\"w-4 h-4\" />\n        </Button>\n        <div className=\"min-w-0 overflow-hidden\">\n          <h1 className=\"text-sm md:text-lg font-semibold truncate-fix\">{pageTitle[currentPage] || 'Dashboard'}</h1>\n          <p className=\"text-[10px] md:text-xs text-muted-foreground hidden sm:flex items-center gap-1.5 truncate-fix\">\n            <Image src=\"/laxree-logo.png\" alt=\"\" width={10} height={10} className=\"rounded-sm shrink-0\" />\n            <span className=\"truncate-fix\">Laxree Group</span>\n            <span className=\"text-border shrink-0\">|</span>\n            <span className=\"truncate-fix\">{firmLabel}</span>\n            <span className=\"text-border shrink-0\">|</span>\n            <span className=\"text-gold shrink-0\">AI-Powered HRMS</span>\n          </p>\n        </div>\n      </div>\n\n      <div className=\"flex items-center gap-1.5 md:gap-2 shrink-0\">\n        {/* Real-time Clock */}\n        <motion.div\n          className=\"hidden lg:flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-muted/50 text-xs font-mono text-muted-foreground border border-border/50 shrink-0\"\n          initial={{ opacity: 0 }}\n          animate={{ opacity: 1 }}\n        >\n          <Clock className=\"w-3 h-3 text-gold\" />\n          <span>{clock} IST</span>\n        </motion.div>\n\n        {/* Admin Name Display — hidden on small screens */}\n        <div className=\"hidden md:flex items-center gap-1.5 px-2 py-1 rounded-lg bg-gold/5 border border-gold/15 shrink-0 max-w-[160px]\">\n          <div className=\"w-5 h-5 rounded-full gradient-laxree flex items-center justify-center text-white text-[8px] font-bold shrink-0\">\n            {displayName.charAt(0).toUpperCase()}\n          </div>\n          <span className=\"text-xs font-medium text-gold-gradient truncate-fix\">{displayName}</span>\n          <Crown className=\"w-2.5 h-2.5 text-gold shrink-0\" />\n        </div>\n\n        {/* Dark Mode Toggle */}\n        <Button variant=\"ghost\" size=\"icon\" onClick={toggleDarkMode} className=\"relative hover:bg-gold/5 shrink-0 h-8 w-8\" title=\"Toggle dark mode\">\n          {darkMode ? <Sun className=\"w-4 h-4 text-gold\" /> : <Moon className=\"w-4 h-4\" />}\n        </Button>\n\n        {/* Logout */}\n        <Button variant=\"ghost\" size=\"icon\" className=\"text-muted-foreground hover:text-destructive hover:bg-destructive/5 shrink-0 h-8 w-8\" onClick={handleLogout} title=\"Logout\">\n          <LogOut className=\"w-4 h-4\" />\n        </Button>\n      </div>\n    </header>\n  );\n}\n","var _excluded = [\"children\", \"width\", \"height\", \"viewBox\", \"className\", \"style\", \"title\", \"desc\"];\nfunction _extends() { _extends = Object.assign ? Object.assign.bind() : function (target) { for (var i = 1; i < arguments.length; i++) { var source = arguments[i]; for (var key in source) { if (Object.prototype.hasOwnProperty.call(source, key)) { target[key] = source[key]; } } } return target; }; return _extends.apply(this, arguments); }\n